import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void matmul_kernel(const __half* A, const __half* B, __half* C, int M, int K, int N) {
    // Use shared memory for tiling
    __shared__ __half As[16][16];
    __shared__ __half Bs[16][16];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = by * 16 + ty;
    int col = bx * 16 + tx;

    float sum = 0.0f;

    // Loop over tiles
    for (int tile = 0; tile < (K + 15) / 16; ++tile) {
        // Load tiles into shared memory
        int a_row = row;
        int a_col = tile * 16 + tx;
        int b_row = tile * 16 + ty;
        int b_col = col;

        // Load A tile
        if (a_row < M && a_col < K) {
            As[ty][tx] = A[a_row * K + a_col];
        } else {
            As[ty][tx] = __float2half(0.0f);
        }

        // Load B tile (transposed)
        if (b_row < K && b_col < N) {
            Bs[ty][tx] = B[b_col * K + b_row];  // Note: B is transposed, so access B[col][row]
        } else {
            Bs[ty][tx] = __float2half(0.0f);
        }

        __syncthreads();

        // Compute partial dot product
        for (int k = 0; k < 16; ++k) {
            sum += __half2float(As[ty][k]) * __half2float(Bs[k][tx]);
        }

        __syncthreads();
    }

    // Write result
    if (row < M && col < N) {
        C[row * N + col] = __float2half(sum);
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    auto A_contiguous = A.contiguous();
    auto B_contiguous = B.contiguous();

    int M = A_contiguous.size(0);
    int K = A_contiguous.size(1);
    int N = B_contiguous.size(0);

    auto out = torch::empty({M, N}, torch::TensorOptions().dtype(torch::kFloat16).device(torch::kCUDA));

    dim3 block(16, 16);
    dim3 grid((N + 15) / 16, (M + 15) / 16);

    matmul_kernel<<<grid, block>>>(
        reinterpret_cast<const __half*>(A_contiguous.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(B_contiguous.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(out.data_ptr<at::Half>()),
        M, K, N
    );

    return out;
}
"""

cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

matmul_op = load_inline(
    name="matmul_ext",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matmul_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul = matmul_op.matmul_cuda

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.matmul(A, B)

