import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA source – WMMA (Tensor Core) fp16 GEMM: C = A @ B.T
# ----------------------------------------------------------------------
cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <mma.h>

using namespace nvcuda;

// ---------------------------------------------------------------
// WMMA tile sizes (Tensor Core 16x16x16)
#define WMMA_M 16
#define WMMA_N 16
#define WMMA_K 16

// Block tile sizes (must be multiples of WMMA tile sizes)
#define BLOCK_M 64          // rows of C computed by a thread block
#define BLOCK_N 64          // cols of C computed by a thread block
#define BLOCK_K WMMA_K      // K‑dimension chunk loaded per iteration

// Shared‑memory layout
//   As : BLOCK_M x BLOCK_K  (row‑major)
//   Bs : BLOCK_K x BLOCK_N  (row‑major)
extern __shared__ __half shared_mem[];
// ----------------------------------------------------------------
// Kernel
// ----------------------------------------------------------------
__global__ void wmma_gemm_fp16_kernel(const __half* __restrict__ A,
                                      const __half* __restrict__ B,
                                      __half* __restrict__ C,
                                      int M, int N, int K) {
    // ----- block coordinates -----
    const int block_row = blockIdx.y * BLOCK_M;
    const int block_col = blockIdx.x * BLOCK_N;

    // ----- shared memory pointers -----
    __half* As = shared_mem;                                 // [BLOCK_M][BLOCK_K]
    __half* Bs = As + BLOCK_M * BLOCK_K;                     // [BLOCK_K][BLOCK_N]

    // ----- each warp will compute one WMMA tile (16x16) -----
    // With dim3(32,4) we have 4 warps (threadIdx.y = 0..3)
    const int warp_id   = threadIdx.y;                       // 0..3
    const int tile_row  = warp_id / 2;                       // 0 or 1
    const int tile_col  = warp_id % 2;                       // 0 or 1
    const int c_row = block_row + tile_row * WMMA_M;         // global row start for this warp
    const int c_col = block_col + tile_col * WMMA_N;         // global col start for this warp

    // WMMA fragments
    wmma::fragment<wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K,
                   __half, wmma::row_major> a_frag;
    wmma::fragment<wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K,
                   __half, wmma::col_major> b_frag;
    wmma::fragment<wmma::accumulator, WMMA_M, WMMA_N, WMMA_K,
                   float> c_frag;

    wmma::fill_fragment(c_frag, 0.0f);   // accumulator init

    // ----- loop over K dimension in BLOCK_K (16) sized chunks -----
    for (int kk = 0; kk < K; kk += BLOCK_K) {
        // ---- load A tile into shared memory ----
        int a_row = block_row + threadIdx.y * (WMMA_M / 4) + (threadIdx.x % (WMMA_M / 4));
        int a_col = kk + threadIdx.x;
        if (a_row < M && a_col < K) {
            As[threadIdx.y * BLOCK_K + threadIdx.x] = A[a_row * K + a_col];
        } else {
            As[threadIdx.y * BLOCK_K + threadIdx.x] = __float2half(0.0f);
        }

        // ---- load B tile into shared memory ----
        int b_row = kk + threadIdx.y;
        int b_col = block_col + threadIdx.x;
        if (b_row < K && b_col < N) {
            Bs[threadIdx.y * BLOCK_N + threadIdx.x] = B[b_row * N + b_col];
        } else {
            Bs[threadIdx.y * BLOCK_N + threadIdx.x] = __float2half(0.0f);
        }

        __syncthreads();

        // ---- load fragments from shared memory ----
        const __half* tileA = As + tile_row * WMMA_M * BLOCK_K;   // start of this warp's A sub‑tile
        const __half* tileB = Bs + tile_col * WMMA_N;           // start of this warp's B sub‑tile

        wmma::load_matrix_sync(a_frag, tileA, BLOCK_K);
        wmma::load_matrix_sync(b_frag, tileB, BLOCK_N);

        // ---- matrix multiply‑accumulate ----
        wmma::mma_sync(c_frag, a_frag, b_frag, c_frag);

        __syncthreads();
    }

    // ---- write the accumulator back to global memory (half output) ----
    if (c_row < M && c_col < N) {
        wmma::store_matrix_sync(C + c_row * N + c_col, c_frag, N, wmma::mem_row_major);
    }
}

// ----------------------------------------------------------------
// Wrapper called from Python
// ----------------------------------------------------------------
torch::Tensor wmma_gemm_fp16(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(),
                "Both inputs must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2,
                "Both inputs must be 2‑D matrices");
    TORCH_CHECK(A.dtype() == torch::kHalf && B.dtype() == torch::kHalf,
                "Both inputs must be fp16");

    const int M = A.size(0);
    const int K = A.size(1);
    const int N = B.size(0);       // B is (N, K)

    auto C = torch::empty({M, N}, A.options());

    dim3 block(32, 4);   // 128 threads = 4 warps
    dim3 grid((N + BLOCK_N - 1) / BLOCK_N,
              (M + BLOCK_M - 1) / BLOCK_M);

    size_t shmem_bytes = (BLOCK_M * BLOCK_K + BLOCK_K * BLOCK_N) * sizeof(__half);

    wmma_gemm_fp16_kernel<<<grid, block, shmem_bytes,
        at::cuda::getCurrentCUDAStream()>>>(
        reinterpret_cast<const __half*>(A.data_ptr()),
        reinterpret_cast<const __half*>(B.data_ptr()),
        reinterpret_cast<__half*>(C.data_ptr()),
        M, N, K);

