import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------------------------------------------------------------------------
# CUDA kernel: tiled half‑precision GEMM computing C = A @ B.T
#   A : (M, K)  half
#   B : (N, K)  half   (note: we treat B as not transposed and index its rows)
#   C : (M, N)  half
# ---------------------------------------------------------------------------
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef TILE
#define TILE 16          // 16×16 thread block, 16×16 shared‑memory tiles
#endif

// ---------------------------------------------------------------
// Kernel: each thread computes one element C[row, col]
//
// Shared memory layout:
//   As[TILE][TILE] stores a tile of A  (row-major)
//   Bs[TILE][TILE] stores a tile of B transposed, i.e.
//       Bs[tile_row][tile_col] = B[col][k]   so that we can read Bs[k][col]
// ---------------------------------------------------------------
__global__ void matmul_tile_kernel(const __half* __restrict__ A,
                                   const __half* __restrict__ B,
                                   __half* __restrict__ C,
                                   int M, int K, int N) {
    // thread identifiers
    const int tx = threadIdx.x;   // column within tile
    const int ty = threadIdx.y;   // row    within tile

    const int col = blockIdx.x * TILE + tx;   // column of C (also row of B)
    const int row = blockIdx.y * TILE + ty;   // row    of C (also row of A)

    // accumulator in fp32 for accuracy
    float acc = 0.0f;

    // shared memory tiles
    __shared__ __half As[TILE][TILE];
    __shared__ __half Bs[TILE][TILE];   // note: transposed store

    // loop over K dimension in TILE‑sized chunks
    const int numTiles = (K + TILE - 1) / TILE;
    for (int t = 0; t < numTiles; ++t) {
        // global indices for the elements we need to load
        int a_row = row;
        int a_col = t * TILE + tx;

        int b_row = col;                 // B's row (since we want B[j,k])
        int b_col = t * TILE + ty;       // note the swap of tx/ty for transposition

        // Load A tile
        if (a_row < M && a_col < K) {
            As[ty][tx] = A[a_row * K + a_col];
        } else {
            As[ty][tx] = __float2half(0.0f);
        }

        // Load B tile transposed (store Bs[tx][ty])
        if (b_row < N && b_col < K) {
            Bs[tx][ty] = B[b_row * K + b_col];
        } else {
            Bs[tx][ty] = __float2half(0.0f);
        }

        __syncthreads();

        // Compute partial dot‑product for this tile
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc += __half2float(As[ty][k]) * __half2float(Bs[k][tx]);
        }

        __syncthreads();
    }

    // Write result
    if (row < M && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

// ---------------------------------------------------------------
// Wrapper called from Python
// ---------------------------------------------------------------
torch::Tensor matmul_fp16(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(),
                "Both inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kFloat16 && B.dtype() == torch::kFloat16,
                "Both inputs must be half‑precision (float16)");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2,
                "Both inputs must be 2‑D matrices");
    TORCH_CHECK(A.size(1) == B.size(1),
                "Inner dimensions must match: A.shape[1] == B.shape[1]");

    const int M = A.size(0);
    const int K = A.size(1);
    const int N = B.size(0);          // B is (N, K)

    auto C = torch::empty({M, N},
                          A.options());   // same dtype/device as A

    const int TILE = 16;
    dim3 block(TILE, TILE);
    dim3 grid((N + TILE - 1) / TILE,
              (M + TILE - 1) / TILE);

    matmul_tile_kernel<<<grid, block>>>(
        A.data_ptr<at::Half>(),
        B.data_ptr<at::Half>(),
        C.data_ptr<at::Half>(),
        M, K, N);

    return C;
}
"""

