    """C = A @ B.T  (half‑precision) using a custom tiled CUDA kernel."""
    def __init__(self):
        super().__init__()
        self._impl = ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._impl.matmul_fp16(A, B)

