#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <c10/cuda/CUDAStream.h>

#ifndef CHECK_CUDA
#define CHECK_CUDA(x) TORCH_CHECK(x.is_cuda(), #x " must be a CUDA tensor")
#endif
#ifndef CHECK_CONTIGUOUS
#define CHECK_CONTIGUOUS(x) TORCH_CHECK(x.is_contiguous(), #x " must be contiguous")
#endif
#ifndef CHECK_INPUT
#define CHECK_INPUT(x) CHECK_CUDA(x); CHECK_CONTIGUOUS(x)
#endif

// tile size (both dimensions)
constexpr int TILE = 16;

// ------------------------------------------------------------------
// Kernel: each thread computes one output element using shared‑memory tiles.
// ------------------------------------------------------------------
__global__ void matmul_tiled_fp16_kernel(
    const __half* __restrict__ A,
    const __half* __restrict__ B,
    __half* __restrict__ C,
    int M, int N, int K)
{
    // thread coordinates within the output matrix
    int row = blockIdx.y * TILE + threadIdx.y; // [0, M)
    int col = blockIdx.x * TILE + threadIdx.x; // [0, N)

    // shared memory tiles
    __shared__ __half As[TILE][TILE];
    __shared__ __half Bs[TILE][TILE];

    float acc = 0.0f;

    // loop over K dimension in TILE‑sized chunks
    for (int t = 0; t < K; t += TILE) {
        // global indices for the elements to load
        int a_row = row;
        int a_col = t + threadIdx.x;   // column inside A tile
        int b_row = col;
        int b_col = t + threadIdx.y;   // column inside B tile (B is N×K)

        // load A tile (row‑major)
        As[threadIdx.y][threadIdx.x] = (a_row < M && a_col < K)
            ? A[a_row * K + a_col]
            : __float2half(0.0f);

        // load B tile (row‑major, each row = original column)
        Bs[threadIdx.y][threadIdx.x] = (b_row < N && b_col < K)
            ? B[b_row * K + b_col]
            : __float2half(0.0f);

        __syncthreads();

        // compute partial dot product for this tile
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc += __half2float(As[threadIdx.y][k]) *
                   __half2float(Bs[k][threadIdx.x]);
        }

        __syncthreads();
    }

    // write result
    if (row < M && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

// ------------------------------------------------------------------
// PyTorch binding
// ------------------------------------------------------------------
torch::Tensor matmul_tiled_fp16(torch::Tensor A, torch::Tensor B) {
    CHECK_INPUT(A);
    CHECK_INPUT(B);
    TORCH_CHECK(A.dtype() == torch::kFloat16, "A must be half precision");
    TORCH_CHECK(B.dtype() == torch::kFloat16, "B must be half precision");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2‑D tensors");

