    int64_t K = A.size(1);
    TORCH_CHECK(B.size(1) == K, "Inner dimensions must match (A: MxK, B: NxK)");
    int64_t N = B.size(0);   // B is stored as (N, K)

    auto C = torch::empty({M, N}, A.options());

    const dim3 block(TILE, TILE);
    const dim3 grid( (N + TILE - 1) / TILE,
                     (M + TILE - 1) / TILE );

    matmul_tiled_fp16_kernel<<<grid, block, 0,
        c10::cuda::getCurrentCUDAStream()>>>(
            reinterpret_cast<const __half*>(A.data_ptr<at::Half>()),
            reinterpret_cast<const __half*>(B.data_ptr<at::Half>()),
            reinterpret_cast<__half*>(C.data_ptr<at::Half>()),
            static_cast<int>(M),
            static_cast<int>(N),
            static_cast<int>(K));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch error: ", cudaGetErrorString(err));
    }
    return C;
}
