import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------------------------------------------------------
# CUDA source: tiled FP16 GEMM (C = A @ B.T) using shared memory
# ------------------------------------------------------------------
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef TILE_M
#define TILE_M 64          // rows of C computed by a block
#endif
#ifndef TILE_N
#define TILE_N 64          // cols of C computed by a block
#endif
#ifndef TILE_K
#define TILE_K 32          // reduction tile size
#endif

// C = A (M x K) * B.T (K x N)
// A: row‑major fp16 [M][K]
// B: row‑major fp16 [N][K]   (we treat it as transposed inside the kernel)
// C: row‑major fp16 [M][N]
__global__ void gemm_fp16_tiled_kernel(
    const __half* __restrict__ A,
    const __half* __restrict__ B,
    __half* __restrict__ C,
    int M, int N, int K)
{
    // block tile origin
    const int block_row = blockIdx.y * TILE_M;
    const int block_col = blockIdx.x * TILE_N;

    // thread's output element within the tile
    const int thread_row = threadIdx.y;   // 0 .. blockDim.y-1
    const int thread_col = threadIdx.x;   // 0 .. blockDim.x-1

    // global coordinates of the element this thread will write
    const int row = block_row + thread_row;
    const int col = block_col + thread_col;

    // shared memory tiles
    extern __shared__ __half shared[];
    __half* As = shared;                                          // TILE_M x TILE_K
    __half* Bs = shared + TILE_M * TILE_K;                        // TILE_K x TILE_N

    float acc = 0.0f;   // accumulation in FP32

    // Loop over K dimension in tiles
    for (int k0 = 0; k0 < K; k0 += TILE_K) {
        // -------- load A tile into shared memory ----------
        int a_row = row;
        int a_col = k0 + thread_col;
        if (a_row < M && a_col < K) {
            As[thread_row * TILE_K + thread_col] = A[a_row * K + a_col];
        } else {
            As[thread_row * TILE_K + thread_col] = __float2half(0.0f);
        }

        // -------- load B tile (transposed) into shared -----
        // B is stored as (N, K) row‑major, we need B_T (K, N) column‑major.
        // Element B_T[k, n] == B[n, k] == B[n*K + k]
        int b_row = k0 + thread_row;          // k index
        int b_col = col;                      // n index
        if (b_row < K && b_col < N) {
            Bs[thread_row * TILE_N + thread_col] = B[b_col * K + b_row];
        } else {
            Bs[thread_row * TILE_N + thread_col] = __float2half(0.0f);
        }

        __syncthreads();

        // -------- compute partial dot product ---------------
        #pragma unroll
        for (int t = 0; t < TILE_K; ++t) {
            float a_val = __half2float(As[thread_row * TILE_K + t]);
            float b_val = __half2float(Bs[t * TILE_N + thread_col]);
            acc += a_val * b_val;
        }

        __syncthreads();
    }

    // -------- write result ----------
    if (row < M && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

// ------------------------------------------------------------------
// Host wrapper
// ------------------------------------------------------------------
torch::Tensor gemm_fp16_tiled(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(),
                "inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kFloat16 && B.dtype() == torch::kFloat16,
                "inputs must be float16");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2,
                "inputs must be 2‑D");

    const int64_t M = A.size(0);
    const int64_t K = A.size(1);
    const int64_t N = B.size(0);   // B is (N, K)

    auto C = torch::empty({M, N}, A.options());

    dim3 blockDim(TILE_N, TILE_M / TILE_K);   // (64, 2) -> 128 threads, adjust for occupancy
    // To keep 256 threads per block for good occupancy:
    // Use 32x8 threads (256) and let each thread compute one element.
    blockDim.x = 32;
    blockDim.y = 8;

    dim3 gridDim((N + TILE_N - 1) / TILE_N,
                 (M + TILE_M - 1) / TILE_M);

    size_t shared_bytes = (TILE_M * TILE_K + TILE_K * TILE_N) * sizeof(__half);

    gemm_fp16_tiled_kernel<<<gridDim, blockDim, shared_bytes>>>(
        reinterpret_cast<const __half*>(A.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(B.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(C.data_ptr<at::Half>()),
        static_cast<int>(M),
        static_cast<int>(N),
        static_cast<int>(K));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch error: ", cudaGetErrorString(err));
    }
    return C;
}
"""

