import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# -------------------------------------------------------------------------
# CUDA kernel: fp16 GEMM using WMMA (Tensor Cores) with 128x128 tiles.
# -------------------------------------------------------------------------
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <mma.h>

using namespace nvcuda;

// tile size (output per block)
constexpr int WMMA_M = 16;
constexpr int WMMA_N = 16;
constexpr int WMMA_K = 16;
constexpr int TILE_M = 128;   // 8 warps * 16 rows
constexpr int TILE_N = 128;   // 8 warps * 16 cols

// each block = 32 (tx) x 8 (ty) threads = 256 threads = 8 warps
// one warp computes a 16x16 output tile
__global__ void wmma_fp16_gemm_kernel(const __half* __restrict__ A,
                                      const __half* __restrict__ B,
                                      __half* __restrict__ C,
                                      int M, int N, int K) {
    // block coordinates (in tiles of 128x128)
    int block_tile_i = blockIdx.y;   // rows
    int block_tile_j = blockIdx.x;   // cols

    // warp id inside the block (0..7).  one warp per 16‑row×16‑col sub‑tile
    int warp_id = threadIdx.y;               // because blockDim.y == 8
    int lane_id = threadIdx.x;               // 0..31 within warp

    // compute the starting indices of the 16×16 tile this warp will write
    int row_base = block_tile_i * TILE_M + warp_id * WMMA_M;   // M dimension
    int col_base = block_tile_j * TILE_N + warp_id * WMMA_N;   // N dimension

    // accumulator fragment (float)
    wmma::fragment<wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, float> acc_frag;
    wmma::fill_fragment(acc_frag, 0.0f);

    // loop over K dimension tiles
    for (int tile_k = 0; tile_k < K; tile_k += WMMA_K) {
        // ---- load A tile (row‑major) into fragment ----
        wmma::fragment<wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K, __half, wmma::row_major> a_frag;
        const __half* a_tile_ptr = A + (row_base * K) + tile_k;
        // each warp loads its 16×16 sub‑matrix; wmma::load_matrix_sync expects
        // the pointer to the first element of the sub‑matrix.
        wmma::load_matrix_sync(a_frag, a_tile_ptr, K);

        // ---- load B tile (row‑major) into fragment ----
        wmma::fragment<wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K, __half, wmma::row_major> b_frag;
        const __half* b_tile_ptr = B + (tile_k * N) + col_base;
        wmma::load_matrix_sync(b_frag, b_tile_ptr, N);

        // ---- matrix multiply‑accumulate ----
        wmma::mma_sync(acc_frag, a_frag, b_frag, acc_frag);
    }

    // ---- store the result (convert FP32 accumulator to FP16) ----
    // only store if within bounds (handles possible non‑multiple‑of‑128 sizes)
    if (row_base < M && col_base < N) {
        __half* c_tile_ptr = C + (row_base * N) + col_base;
        wmma::store_matrix_sync(c_tile_ptr, acc_frag, N, wmma::mem_row_major);
    }
}

// -------------------------------------------------------------------------
// PyTorch binding
// -------------------------------------------------------------------------
torch::Tensor wmma_fp16_gemm(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(),
                "Both inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kFloat16 && B.dtype() == torch::kFloat16,
                "Inputs must be torch.float16");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2,
                "Inputs must be 2‑D matrices");
    TORCH_CHECK(A.size(1) == B.size(0),
                "Inner dimensions must match for matmul");

    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::empty({M, N}, A.options());

    // launch configuration: one 128×128 tile per block
    dim3 block(32, 8);                         // 256 threads (8 warps)
    dim3 grid((N + TILE_N - 1) / TILE_N,
              (M + TILE_M - 1) / TILE_M);

    wmma_fp16_gemm_kernel<<<grid, block>>>(
        reinterpret_cast<const __half*>(A.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(B.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(C.data_ptr<at::Half>()),
        M, N, K);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch failed: ", cudaGetErrorString(err));
    }
    return C;
}
"""

