# -------------------------------------------------------------------------
# CUDA source implementing a simple fp16 GEMM (C = A @ B) with shared‑memory tiling.
# Accumulation is done in float for numerical stability, final result stored
# as fp16.  Works for any N (square matrices) on RTX PRO 6000 (sm_12x).
# -------------------------------------------------------------------------
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef TILE_SIZE
#define TILE_SIZE 32          // 32x32 threads per block = 1024 threads (max)
#endif

// ---------------------------------------------------------------------
// Kernel: C = A @ B, all matrices are N×N, row‑major, fp16 I/O.
// ---------------------------------------------------------------------
__global__ void gemm_fp16_kernel(const __half* __restrict__ A,
                                 const __half* __restrict__ B,
                                 __half* __restrict__ C,
                                 int N) {
    // Global row & column of the output element computed by this thread
    const int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    const int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    // Shared memory tiles for A and B
    __shared__ __half As[TILE_SIZE][TILE_SIZE];
    __shared__ __half Bs[TILE_SIZE][TILE_SIZE];

    float acc = 0.0f;   // accumulation in FP32

    // Loop over K dimension in TILE_SIZE steps
    for (int k0 = 0; k0 < N; k0 += TILE_SIZE) {
        // Load a tile of A (row‑major)
        int a_row = row;
        int a_col = k0 + threadIdx.x;
        if (a_row < N && a_col < N) {
            As[threadIdx.y][threadIdx.x] = A[a_row * N + a_col];
        } else {
            As[threadIdx.y][threadIdx.x] = __float2half(0.0f);
        }

        // Load a tile of B (row‑major)
        int b_row = k0 + threadIdx.y;
        int b_col = col;
        if (b_row < N && b_col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[b_row * N + b_col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = __float2half(0.0f);
        }

        __syncthreads();

        // Compute partial dot‑product for this tile
        #pragma unroll
        for (int t = 0; t < TILE_SIZE; ++t) {
            acc += __half2float(As[threadIdx.y][t]) *
                   __half2float(Bs[t][threadIdx.x]);
        }

        __syncthreads();
    }

    // Write result
    if (row < N && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

// ---------------------------------------------------------------------
// PyTorch binding
// ---------------------------------------------------------------------
torch::Tensor gemm_fp16_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(),
                "Both inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kFloat16 && B.dtype() == torch::kFloat16,
                "Inputs must be torch.float16");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2,
                "Inputs must be 2‑D matrices");
    TORCH_CHECK(A.size(0) == A.size(1) && B.size(0) == B.size(1) &&
                A.size(0) == B.size(0),
                "Only square matrices of equal size are supported");

    const int N = A.size(0);
    auto C = torch::empty_like(A);

    const dim3 block(TILE_SIZE, TILE_SIZE);
    const dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE,
                    (N + TILE_SIZE - 1) / TILE_SIZE);

    gemm_fp16_kernel<<<grid, block>>>(
        reinterpret_cast<const __half*>(A.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(B.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(C.data_ptr<at::Half>()),
        N);

    // Propagate any launch errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch failed: ", cudaGetErrorString(err));
    }
    return C;
}
