# C++ source (uses torch::mm which dispatches to cuBLAS/Tensor Cores)
# ----------------------------------------------------------------------
cpp_src = r"""
#include <torch/extension.h>

// Wrapper that simply calls the highly‑optimized torch::mm.
// All inputs are expected to be CUDA half tensors (fp16) and square.
torch::Tensor gemm_fp16(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(),
                "inputs must be CUDA tensors");
    TORCH_CHECK(A.scalar_type() == at::kHalf && B.scalar_type() == at::kHalf,
                "inputs must be float16 (half) tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2,
                "inputs must be 2‑D matrices");
    TORCH_CHECK(A.size(0) == A.size(1) && B.size(0) == B.size(1),
                "inputs must be square matrices");
    TORCH_CHECK(A.size(1) == B.size(0),
                "inner dimensions must match");

    // torch::mm will invoke cuBLAS (and on SM 12.x will automatically
