#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef M_SQRT2_PI
#define M_SQRT2_PI 0.7978845608028654f   // sqrt(2/pi)
#endif

// GELU (tanh approximation) kernel processing two FP16 values per thread via half2.
__global__ void gelu_kernel_half2(const __half* __restrict__ in,
                                  __half* __restrict__ out,
                                  const int64_t N) {          // N = total #elements
    const float coeff = 0.044715f;
    const int64_t idx0 = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; // half2 index
    const int64_t stride = (int64_t)gridDim.x * blockDim.x;

    // each thread works on a pair (i, i+1)
    for (int64_t i = idx0; i < (N + 1) / 2; i += stride) {
        int64_t e0 = i * 2;                 // first element index
        int64_t e1 = e0 + 1;                 // second element index (may be >=N)

        // load two half values, guard second if out‑of‑bounds
        __half2 hpair;
        if (e1 < N) {
            // both valid
            hpair = __halves2half2(in[e0], in[e1]);
        } else {
            // only first valid, second dummy (won't be written)
            hpair = __halves2half2(in[e0], __float2half(0.0f));
        }

        // convert to float2 for arithmetic
        float2 xf = __half22float2(hpair);
        float x0 = xf.x;
        float x1 = xf.y;

        // GELU tanh approximation
        float t0 = tanhf(M_SQRT2_PI * (x0 + coeff * x0 * x0 * x0));
        float y0 = 0.5f * x0 * (1.0f + t0);

