#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void group_norm_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    int batch_size,
    int num_features,
    int num_groups,
    int elements_per_group,
    float eps
) {
    int batch_idx = blockIdx.x;
    int group_idx = blockIdx.y;

    if (batch_idx >= batch_size || group_idx >= num_groups) return;

    int feature_start = group_idx * elements_per_group;
    int feature_end = feature_start + elements_per_group;

    // Shared memory for mean and variance calculation
    extern __shared__ float shared_data[];
    float* shared_mean = shared_data;
    float* shared_var = shared_data + blockDim.x;

    int tid = threadIdx.x;

    // Load data into registers and calculate mean
    float sum = 0.0f;
    for (int i = feature_start + tid; i < feature_end; i += blockDim.x) {
        float val = __half2float(input[batch_idx * num_features + i]);
        sum += val;
    }
    shared_mean[tid] = sum;
    __syncthreads();

    // Reduction to get mean
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_mean[tid] += shared_mean[tid + s];
        }
        __syncthreads();
    }

    float mean = shared_mean[0] / elements_per_group;

    // Calculate variance
    float sum_sq = 0.0f;
    for (int i = feature_start + tid; i < feature_end; i += blockDim.x) {
        float val = __half2float(input[batch_idx * num_features + i]);
        float diff = val - mean;
        sum_sq += diff * diff;
    }
    shared_var[tid] = sum_sq;
    __syncthreads();

    // Reduction to get variance
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_var[tid] += shared_var[tid + s];
        }
        __syncthreads();
    }

    float var = shared_var[0] / elements_per_group;
    float inv_std = rsqrtf(var + eps);

    // Normalize and apply scale/shift
    for (int i = feature_start + tid; i < feature_end; i += blockDim.x) {
        float val = __half2float(input[batch_idx * num_features + i]);
        float normalized = (val - mean) * inv_std;
        float result = normalized * __half2float(weight[i]) + __half2float(bias[i]);
        output[batch_idx * num_features + i] = __float2half(result);
    }
