    int batch_idx = blockIdx.x;
    int group_idx = blockIdx.y;

    if (batch_idx >= batch_size || group_idx >= num_groups) return;

    // Shared memory for mean and variance calculation
    extern __shared__ float shared_data[];
    float* shared_sum = shared_data;
    float* shared_sum_sq = shared_data + blockDim.x;

    int tid = threadIdx.x;

    // Calculate base offset for this batch and group
    int features_per_group = num_features / num_groups;
    int feature_start = group_idx * features_per_group;

    // Process all features in this group
    for (int feat_idx = feature_start + tid; feat_idx < feature_start + features_per_group; feat_idx += blockDim.x) {
        // Calculate base offset for this feature
        int base_offset = batch_idx * num_features * elements_per_group + feat_idx * elements_per_group;

        // Calculate mean and variance for this feature
        float sum = 0.0f;
        float sum_sq = 0.0f;

        // Load data and accumulate
        for (int i = 0; i < elements_per_group; i++) {
            float val = __half2float(input[base_offset + i]);
            sum += val;
            sum_sq += val * val;
        }

        shared_sum[tid] = sum;
        shared_sum_sq[tid] = sum_sq;
        __syncthreads();

