        for (int s = blockDim.x / 2; s > 0; s >>= 1) {
            if (tid < s) {
                shared_sum[tid] += shared_sum[tid + s];
                shared_sum_sq[tid] += shared_sum_sq[tid + s];
            }
            __syncthreads();
        }

        // Compute mean and variance
        float mean_val = shared_sum[0] / elements_per_group;
        float var_val = (shared_sum_sq[0] / elements_per_group) - (mean_val * mean_val);
        float inv_std = rsqrtf(var_val + eps);

        // Normalize and apply scale/shift
        float weight_val = __half2float(weight[feat_idx]);
        float bias_val = __half2float(bias[feat_idx]);

        for (int i = 0; i < elements_per_group; i++) {
