#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__device__ __forceinline__ float half_to_float(__half h) {
    return __half2float(h);
}

__device__ __forceinline__ __half float_to_half(float f) {
    return __float2half(f);
}

__global__ void group_norm_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    float* __restrict__ mean,
    float* __restrict__ rstd,
    int batch_size,
    int num_features,
    int total_elements,
    int num_groups,
    int elements_per_group
) {
    int feature_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (feature_idx >= num_features) return;

    int group_idx = feature_idx / (num_features / num_groups);
    int group_start = group_idx * elements_per_group;

    // Compute mean and variance for this group
    float sum = 0.0f;
    for (int i = 0; i < elements_per_group; i++) {
        sum += half_to_float(input[group_start + i]);
    }
    float group_mean = sum / elements_per_group;

    float sum_sq_diff = 0.0f;
    for (int i = 0; i < elements_per_group; i++) {
        float diff = half_to_float(input[group_start + i]) - group_mean;
        sum_sq_diff += diff * diff;
    }
    float group_var = sum_sq_diff / elements_per_group;
    float group_rstd = 1.0f / sqrtf(group_var + 1e-5f);

    // Store computed statistics
    mean[feature_idx] = group_mean;
    rstd[feature_idx] = group_rstd;

    // Normalize and apply affine transformation
    int batch_start = feature_idx * (total_elements / num_features);
    for (int i = 0; i < total_elements / num_features; i++) {
        int idx = batch_start + i;
        float normalized = (half_to_float(input[idx]) - group_mean) * group_rstd;
        float result = normalized * half_to_float(weight[feature_idx]) + half_to_float(bias[feature_idx]);
        output[idx] = float_to_half(result);
    }
}

