import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA implementation of GroupNorm (fp16 I/O, fp32 accumulation)
# ----------------------------------------------------------------------
cuda_src = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef BLOCK_SIZE
#define BLOCK_SIZE 128          // tuned for RTX 6000 (SM 12.0)
#endif
#ifndef WARP_SIZE
#define WARP_SIZE 32
#endif

// ----------------------------------------------------------------------
// Kernel: one block processes one (batch, group) slice
// ----------------------------------------------------------------------
extern "C" __global__
void group_norm_forward_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    const int N,
    const int C,
    const int G,
    const int S,          // spatial size = product of dims >=2
    const float eps)
{
    // block index maps to (n, g)
    const int block_id = blockIdx.x;          // 0 .. N*G-1
    const int n = block_id / G;               // batch index
    const int g = block_id % G;               // group index

    const int C_per_group = C / G;
    const int c_start = g * C_per_group;      // first channel of this group
    const int elems_per_group = C_per_group * S; // total elements for this slice

    const int tid = threadIdx.x;
    const int stride = BLOCK_SIZE;

    // --------------------------------------------------------------
    // First pass: each thread accumulates sum and sum of squares (fp32)
    // --------------------------------------------------------------
    float sum = 0.0f;
    float sumsq = 0.0f;

    for (int idx = tid; idx < elems_per_group; idx += stride) {
        int c_off = idx / S;          // channel offset inside group
        int s_off = idx % S;          // spatial offset
        int c = c_start + c_off;     // absolute channel index

        // flat index: ((n*C + c)*S) + s
        int flat = ((n * C + c) * S) + s_off;

        float v = __half2float(input[flat]);
        sum   += v;
        sumsq += v * v;
    }

    // --------------------------------------------------------------
    // Block-wide reduction using shared memory + warp shuffles
    // --------------------------------------------------------------
    __shared__ float sum_shmem[BLOCK_SIZE];
    __shared__ float sumsq_shmem[BLOCK_SIZE];

    sum_shmem[tid]   = sum;
    sumsq_shmem[tid] = sumsq;
    __syncthreads();

    // reduce within warp
    float sum_val   = sum_shmem[tid];
    float sumsq_val = sumsq_shmem[tid];
    for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
        sum_val   += __shfl_down_sync(0xffffffff, sum_val,   offset);
        sumsq_val += __shfl_down_sync(0xffffffff, sumsq_val, offset);
    }

    // first warp writes its reduction to shared memory
    if (tid < WARP_SIZE) {
        sum_shmem[tid]   = sum_val;
        sumsq_shmem[tid] = sumsq_val;
    }
    __syncthreads();

    // now first thread has the totals
    float total_sum   = sum_shmem[0];
    float total_sumsq = sumsq_shmem[0];

    // --------------------------------------------------------------
    // Compute mean & inv_std
    // --------------------------------------------------------------
    float mean = total_sum / static_cast<float>(elems_per_group);
    float var  = total_sumsq / static_cast<float>(elems_per_group) - mean * mean;
    float inv_std = rsqrtf(var + eps);

    // broadcast to all threads via shared memory
    __shared__ float mean_s, inv_std_s;
    if (tid == 0) {
        mean_s    = mean;
        inv_std_s = inv_std;
    }
    __syncthreads();
    mean    = mean_s;
    inv_std = inv_std_s;

    // --------------------------------------------------------------
    // Second pass: write normalized output with affine transform
    // --------------------------------------------------------------
    for (int idx = tid; idx < elems_per_group; idx += stride) {
        int c_off = idx / S;
        int s_off = idx % S;
        int c = c_start + c_off;
        int flat = ((n * C + c) * S) + s_off;

        float v = __half2float(input[flat]);
        float w = __half2float(__ldg(&weight[c]));
        float b = __half2float(__ldg(&bias[c]));

        float norm = ((v - mean) * inv_std) * w + b;
        output[flat] = __float2half(norm);
    }
}

// ----------------------------------------------------------------------
// C++ binding
// ----------------------------------------------------------------------
torch::Tensor group_norm_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    const int64_t num_groups,
    const float eps)
{
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "weight/bias must be CUDA");
    TORCH_CHECK(input.dtype() == torch::kFloat16, "input must be float16");
    TORCH_CHECK(weight.dtype() == torch::kFloat16 && bias.dtype() == torch::kFloat16,
                "weight/bias must be float16");

    const int N = input.size(0);
