// One block per (batch, group)
__global__ void group_norm_forward_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    const int N,
    const int C,
    const int G,
    const int S,                // spatial size (product of remaining dimensions)
    const float eps)
{
    const int group_id = blockIdx.x;                 // 0 .. N*G-1
    const int n = group_id / G;                      // batch index
    const int g = group_id % G;                      // group index
    const int channels_per_group = C / G;
    const int c_start = g * channels_per_group;      // first channel in this group

    const int elements_per_group = channels_per_group * S; // total elems for reduction
    const int tid = threadIdx.x;

    // --------------------------------------------------------------
    // 1) Compute sum and sum of squares in one pass
    // --------------------------------------------------------------
    float sum = 0.0f;
    float sumsq = 0.0f;
    for (int i = tid; i < elements_per_group; i += BLOCK_SIZE) {
        int s = i % S;                     // spatial offset
        int c_off = i / S;                 // channel offset within group
        int c = c_start + c_off;           // absolute channel
        int idx = ((n * C + c) * S) + s;   // flat index
