        __syncthreads();
    }

    // broadcast the final mean & inv_std from thread 0
    float mean, inv_std;
    if (threadIdx.x == 0) {
        float total_sum   = sh_sum[0];
        float total_sumsq = sh_sumsq[0];
        mean = total_sum / elems_per_group;
        float var = total_sumsq / elems_per_group - mean * mean;
