    // 3) Second pass: normalize + affine
    // ------------------------------------------------------------------
    for (int idx = threadIdx.x; idx < elems_per_group; idx += BLOCK_SIZE) {
        int c_offset = idx / HW;
        int spatial  = idx % HW;
