// One block processes a (batch, group) pair.
// ------------------------------------------------------------------
template <int TPB>
__global__ void gn_forward_kernel(
    const __half* __restrict__ x,          // [N, C, HW]
    const __half* __restrict__ weight,     // [C]
    const __half* __restrict__ bias,       // [C]
