    int N, int C, int HW,
    int G, int group_size,
    float eps)
{
    const int n   = blockIdx.x;            // batch index
    const int g   = blockIdx.y;            // group index
    const int tid = threadIdx.x;

    const int elems_per_group = group_size * HW;   // total elements for this (n,g)

    // ----------------------------------------------------------------
    // 1) Compute sum and sum of squares (grid‑stride over group elements)
    // ----------------------------------------------------------------
    float sum  = 0.0f;
    float sum2 = 0.0f;

    for (int idx = tid; idx < elems_per_group; idx += TPB) {
        int local_c = idx / HW;            // 0 .. group_size-1
        int hw      = idx % HW;            // 0 .. HW-1
        int c       = g * group_size + local_c; // absolute channel
        int flat    = ((n * C + c) * HW) + hw; // linear index in x

