    // 2) Block‑level reduction using warp shuffles
    // ----------------------------------------------------------------
    // each warp reduces its own values
    const int lane = tid & 31;            // threadIdx.x % 32
    const int wid  = tid >> 5;            // threadIdx.x / 32

    // warp‑level reduction
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum  += __shfl_down_sync(0xffffffff, sum,  offset);
        sum2 += __shfl_down_sync(0xffffffff, sum2, offset);
