# CUDA kernel: correct half‑precision Group Normalization
# ------------------------------------------------------------
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef CHECK
#define CHECK(x) TORCH_CHECK(x, #x)
#endif

// ------------------------------------------------------------
// Kernel: one block per (batch, group)
// ------------------------------------------------------------
template <int BLOCK_SIZE>
__global__ void groupnorm_forward_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    int N, int C, int G, int D,
    float eps) {

    const int n = blockIdx.x;               // batch index
    const int g = blockIdx.y;               // group index
    const int channels_per_group = C / G;
    const int c_start = g * channels_per_group;
    const int c_end   = c_start + channels_per_group;

    const int tid = threadIdx.x;
    const int stride = BLOCK_SIZE;

    // --------------------------------------------------------
    // 1) First pass: compute sum and sum of squares
    // --------------------------------------------------------
    float sum  = 0.0f;
    float sum2 = 0.0f;

    for (int c = c_start; c < c_end; ++c) {
        const int base = ((n * C) + c) * D;
        for (int d = tid; d < D; d += stride) {
            float v = __half2float(input[base + d]);
            sum  += v;
            sum2 += v * v;
        }
    }

    // --------------------------------------------------------
    // 2) Block-wide reduction of sum and sum2
    // --------------------------------------------------------
    __shared__ float s_sum[BLOCK_SIZE];
    __shared__ float s_sum2[BLOCK_SIZE];
    s_sum[tid]  = sum;
    s_sum2[tid] = sum2;
    __syncthreads();

    // tree reduction
    for (int s = BLOCK_SIZE / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_sum[tid]  += s_sum[tid + s];
            s_sum2[tid] += s_sum2[tid + s];
        }
        __syncthreads();
    }

    // --------------------------------------------------------
    // 3) Compute mean, variance, inv_std (store in shared for reuse)
    // --------------------------------------------------------
    float mean, var, inv_std;
    if (tid == 0) {
        float elems = float(channels_per_group) * float(D);
        mean = s_sum[0] / elems;
        var  = s_sum2[0] / elems - mean * mean;
        inv_std = rsqrtf(var + eps);
        // reuse shared memory to broadcast to all threads
        s_sum[0]   = mean;
        s_sum2[0]  = inv_std;
    }
    __syncthreads();
    mean    = s_sum[0];
    inv_std = s_sum2[0];

    // --------------------------------------------------------
    // 4) Second pass: normalize, apply affine, write output
    // --------------------------------------------------------
    for (int c = c_start; c < c_end; ++c) {
        const int base = ((n * C) + c) * D;
        float w = __half2float(weight[c]);
        float b = __half2float(bias[c]);
        for (int d = tid; d < D; d += stride) {
            float x = __half2float(input[base + d]);
            float y = (x - mean) * inv_std;
            y = y * w + b;
            output[base + d] = __float2half(y);
        }
    }
}

