    const int64_t tile_id = blockIdx.y;           // tile index along spatial dim
    const int64_t tile_start = tile_id * TILE_SIZE;
    const int64_t tile_end   = min(N, tile_start + TILE_SIZE);

    const int tid = threadIdx.x;                  // 0 .. THREADS_PER_BLOCK-1
    const int c0 = tid;                           // first feature handled
    const int c1 = tid + THREADS_PER_BLOCK;       // second feature (if any)

