# CUDA kernel: RMSNorm for fp16 tensors (vectorized with half2)
# ----------------------------------------------------------------------
cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cmath>

__global__ void rmsnorm_kernel(
    const __half* __restrict__ x,
    __half* __restrict__ out,
    int batch,
    int channels,
    int height,
    int width,
    float eps)
{
    // total number of (batch, height, width) positions
    const int N = batch * height * width;
    const int tid = threadIdx.x;
    const int stride = blockDim.x * gridDim.x;

    // each thread processes several positions (grid‑stride loop)
    for (int pos = blockIdx.x * blockDim.x + tid; pos < N; pos += stride) {
        // decode linear index into (b, h, w)
        int tmp = pos;
        int w = tmp % width;
        tmp /= width;
        int h = tmp % height;
        tmp /= height;
        int b = tmp;

        // base offset for channel 0 of this (b,h,w)
        // layout: NCHW (contiguous in channel dimension)
        int base = ((b * channels) * height + h) * width + w;
        int channel_stride = height * width;   // distance between successive channels

        // ---------- first pass: compute sum of squares ----------
        float sum_sq = 0.0f;
        // process two channels at a time with half2
        int c = 0;
        for (; c <= channels - 2; c += 2) {
            // load two half values
            __half2 v = __halves2half2(
                x[base + c * channel_stride],
                x[base + (c + 1) * channel_stride]);
            // square element‑wise
            __half2 sq = __hmul2(v, v);
            // convert to float2 for accumulation
            float2 f = __half22float2(sq);
            sum_sq += f.x + f.y;
        }
        // handle odd channel count (should not happen for typical RMSNorm, but keep safe)
        for (; c < channels; ++c) {
            float val = __half2float(x[base + c * channel_stride]);
            sum_sq += val * val;
        }

        // compute RMS = sqrt(mean(x^2) + eps)
        float rms = sqrtf(sum_sq / static_cast<float>(channels) + eps);

        // ---------- second pass: write normalized output ----------
        c = 0;
        for (; c <= channels - 2; c += 2) {
            __half2 v = __halves2half2(
                x[base + c * channel_stride],
                x[base + (c + 1) * channel_stride]);
            // convert to float2
            float2 f = __half22float2(v);
            // normalize
            f.x = f.x / rms;
            f.y = f.y / rms;
            // back to half2 (round‑to‑nearest)
            __half2 out_h2 = __float22half2_rn(f);
            // store
            out[base + c * channel_stride] = __low2half(out_h2);
            out[base + (c + 1) * channel_stride] = __high2half(out_h2);
        }
        for (; c < channels; ++c) {
            float val = __half2float(x[base + c * channel_stride]);
