#error "Kernel is targeted for compute capability 12.0 (RTX PRO 6000 Blackwell)"
#endif

// -----------------------------------------------------------------
// RMSNorm kernel for the fixed feature size C = 64
// -----------------------------------------------------------------
template <int C>
__global__ void rmsnorm_kernel_64(const __half* __restrict__ x,
                                  __half* __restrict__ out,
                                  int B, int H, int W,
                                  float eps) {
    // one warp (32 threads) handles one spatial location (b, h, w)
    // each thread processes two channels: c and c+32
    const int HW = H * W;
    const int total_spatial = B * HW;               // number of (b,h,w) points

    // grid‑stride over spatial locations
    for (int loc = blockIdx.x; loc < total_spatial; loc += gridDim.x) {
        // decode (b, h, w) from linear loc
        int b = loc / HW;
        int rem = loc % HW;
        int h = rem / W;
        int w = rem % W;

        // base pointer for the first channel of this location
        // layout: (B, C, H, W) contiguous in C dimension
        int base = ((b * C) * H + h) * W + w;        // stride per channel = HW

        // each thread works on two channels
        int c0 = threadIdx.x;               // 0 .. 31
        int c1 = threadIdx.x + 32;          // 32 .. 63

        // load the two half values, convert to float
        int idx0 = base + c0 * HW;
        int idx1 = base + c1 * HW;
        float v0 = __half2float(x[idx0]);
        float v1 = __half2float(x[idx1]);

        // accumulate squares
        float sum = v0 * v0 + v1 * v1;

        // -----------------------------------------------------------------
        // warp‑level reduction (sum of squares over all 64 channels)
        // -----------------------------------------------------------------
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum += __shfl_down_sync(0xffffffff, sum, offset);
        }
        // after the loop, lane 0 holds the sum of its own 2‑channel squares
        // we need to combine the two warps (0‑31 and 32‑63)
        // lane 0 of each warp writes its partial sum to shared memory
        __shared__ float warp_sum[2];
        if (threadIdx.x == 0) warp_sum[0] = sum;
        if (threadIdx.x == 32) warp_sum[1] = sum;
        __syncthreads();

        // lane 0 (threadIdx.x == 0) finishes the reduction of the two partials
        float total_sq = 0.0f;
        if (threadIdx.x == 0) {
            total_sq = warp_sum[0] + warp_sum[1];
            // compute inverse RMS once per location
            float inv_rms = rsqrtf(total_sq / static_cast<float>(C) + eps);
            // broadcast to all threads in the block
            warp_sum[0] = inv_rms;   // reuse warp_sum[0] as broadcast buffer
        }
        __syncthreads();
        float inv_rms = warp_sum[0];   // now every thread sees the same value

        // -----------------------------------------------------------------
        // write normalized output
        // -----------------------------------------------------------------
        __half out0 = __float2half(v0 * inv_rms);
        __half out1 = __float2half(v1 * inv_rms);
        out[idx0] = out0;
        out[idx1] = out1;
    }
}

// -----------------------------------------------------------------
// Launcher (dispatches the templated kernel)
// -----------------------------------------------------------------
void rmsnorm_cuda_launcher(const at::Half* x,
                           at::Half* out,
                           int B, int C, int H, int W,
                           float eps) {
    // This implementation is specialized for C == 64.
    TORCH_CHECK(C == 64, "rmsnorm_cuda_launcher currently supports only C = 64");
    const int threads = 32;                     // one warp per location
    const int total_spatial = B * H * W;
    int grid = (total_spatial + 0) / 1;         // one block per location in principle
    if (grid > 65535) grid = 65535;            // cap to maximum grid dimension
    rmsnorm_kernel_64<64><<<grid, threads, 0,
        at::cuda::getCurrentCUDAStream()>>>(
        reinterpret_cast<const __half*>(x),
        reinterpret_cast<__half*>(out),
        B, H, W, eps);
}
