        int hw = height * width;
        int b  = pos / hw;
        int residual = pos - b * hw;
        int i  = residual / width;
        int j  = residual - i * width;

        // ---------- load two channel elements per thread ----------
        float v0 = 0.0f, v1 = 0.0f;
        float sq = 0.0f;                // sum of squares for this thread

        // first channel (c = lane_id)
        int c0 = lane_id;
        if (c0 < channels) {
            int idx0 = (((b * channels + c0) * height) + i) * width + j;
            v0 = __half2float(x[idx0]);
            sq += v0 * v0;
        }

        // second channel (c = lane_id + 32)
        int c1 = lane_id + 32;
        if (c1 < channels) {
            int idx1 = (((b * channels + c1) * height) + i) * width + j;
            v1 = __half2float(x[idx1]);
            sq += v1 * v1;
