cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef TILE_M
#define TILE_M 16
#endif
#ifndef TILE_N
#define TILE_N 16
#endif
#ifndef TILE_K
#define TILE_K 16
#endif

// ------------------------------------------------------------
// Kernel: each block computes a TILE_M x TILE_N output tile for one batch
// ------------------------------------------------------------
__global__ void bmm_tiled_kernel(
    const __half* __restrict__ A,
    const __half* __restrict__ B,
    __half* __restrict__ C,
    const int64_t batch,
    const int64_t M,
    const int64_t N,
    const int64_t K)
{
    // batch index (grid.z)
    const int64_t b = blockIdx.z;

    // thread indices within the tile
    const int tx = threadIdx.x;   // column inside tile (N dimension)
    const int ty = threadIdx.y;   // row    inside tile (M dimension)

    // global coordinates of the output element this thread will write
    const int64_t row = blockIdx.y * TILE_M + ty;   // [0, M)
    const int64_t col = blockIdx.x * TILE_N + tx;   // [0, N)

    // pointers to the beginning of the current batch
    const __half* A_batch = A + b * M * K;
    const __half* B_batch = B + b * K * N;
    __half* C_batch = C + b * M * N;

    // accumulator in FP32
    float acc = 0.0f;

    // shared memory tiles
    __shared__ __half As[TILE_M * TILE_K];
    __shared__ __half Bs[TILE_K * TILE_N];

    // loop over K dimension in tiles
    for (int64_t tk = 0; tk < K; tk += TILE_K) {
        // ----- load A tile -----
        int64_t a_row = row;
        int64_t a_col = tk + tx;          // tx walks the K dimension inside tile
        if (a_row < M && a_col < K) {
            As[ty * TILE_K + tx] = A_batch[a_row * K + a_col];
        } else {
            As[ty * TILE_K + tx] = __float2half(0.0f);
        }

        // ----- load B tile -----
        int64_t b_row = tk + ty;          // ty walks the K dimension inside tile
        int64_t b_col = col;
        if (b_row < K && b_col < N) {
            Bs[ty * TILE_N + tx] = B_batch[b_row * N + b_col];
        } else {
            Bs[ty * TILE_N + tx] = __float2half(0.0f);
        }

        __syncthreads();

        // ----- compute partial dot product -----
        #pragma unroll
        for (int k = 0; k < TILE_K; ++k) {
            float a_val = __half2float(As[ty * TILE_K + k]);
            float b_val = __half2float(Bs[k * TILE_N + tx]);
            acc += a_val * b_val;
        }

        __syncthreads();   // ensure all threads have finished using the tile before it is overwritten
    }

    // write result
    if (row < M && col < N) {
        C_batch[row * N + col] = __float2half(acc);
    }
}

// ------------------------------------------------------------
// Host wrapper
// ------------------------------------------------------------
torch::Tensor bmm_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kFloat16 && B.dtype() == torch::kFloat16,
                "inputs must be float16");
    TORCH_CHECK(A.dim() == 3 && B.dim() == 3, "inputs must be 3‑D tensors");
    TORCH_CHECK(A.size(0) == B.size(0), "batch dimensions must match");
    TORCH_CHECK(A.size(2) == B.size(1), "inner dimensions must match");

    const int64_t batch = A.size(0);
    const int64_t M = A.size(1);
    const int64_t K = A.size(2);
    const int64_t N = B.size(2);

    auto C = torch::empty({batch, M, N}, A.options());

    dim3 block(TILE_N, TILE_M);
    dim3 grid(
        (N + TILE_N - 1) / TILE_N,
        (M + TILE_M - 1) / TILE_M,
        batch
    );

    bmm_tiled_kernel<<<grid, block>>>(
        reinterpret_cast<const __half*>(A.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(B.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(C.data_ptr<at::Half>()),
        batch, M, N, K
    );

    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "CUDA kernel launch failed: ", cudaGetErrorString(err));

    return C;
}
"""

