#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef TILE_M
#define TILE_M 32   // rows per block
#endif
#ifndef TILE_N
#define TILE_N 32   // cols per block
#endif
#ifndef TILE_K
#define TILE_K 16   // reduction tile size
#endif

// Kernel: batched GEMM C = A * B   (all fp16, accumulate in float)
__global__ void batched_gemm_fp16(
    const __half* __restrict__ A,
    const __half* __restrict__ B,
    __half* __restrict__ C,
    int M, int N, int K,
    int strideA, int strideB, int strideC) {

    const int batch = blockIdx.z;
    const __half* A_batch = A + batch * strideA;
    const __half* B_batch = B + batch * strideB;
    __half*       C_batch = C + batch * strideC;

    // thread coordinates within the output tile
    const int tx = threadIdx.x;   // column inside tile
    const int ty = threadIdx.y;   // row inside tile

    const int row = blockIdx.y * TILE_M + ty;   // global row index
    const int col = blockIdx.x * TILE_N + tx;   // global col index

    // shared memory for a tile of A and B
    extern __shared__ __half shared_mem[];
    __half* As = shared_mem;                                   // TILE_M * TILE_K
    __half* Bs = shared_mem + TILE_M * TILE_K;                  // TILE_K * TILE_N

    float acc = 0.0f;   // accumulator in float

    // Loop over K dimension in tiles
    for (int t = 0; t < K; t += TILE_K) {
        // Load A tile (row-major)
        int a_row = row;
        int a_col = t + tx;
        if (a_row < M && a_col < K) {
            As[ty * TILE_K + tx] = A_batch[a_row * K + a_col];
        } else {
            As[ty * TILE_K + tx] = __float2half(0.0f);
        }

        // Load B tile (row-major, but we will access column‑wise later)
        int b_row = t + ty;
        int b_col = col;
        if (b_row < K && b_col < N) {
            Bs[ty * TILE_N + tx] = B_batch[b_row * N + b_col];
        } else {
            Bs[ty * TILE_N + tx] = __float2half(0.0f);
        }

        __syncthreads();

        // Compute partial dot‑product for this tile
#pragma unroll
        for (int k = 0; k < TILE_K; ++k) {
            float a_val = __half2float(As[ty * TILE_K + k]);
            float b_val = __half2float(Bs[k * TILE_N + tx]);
            acc += a_val * b_val;
        }

        __syncthreads();
