#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void bmm_fp16_kernel(
    const __half* __restrict__ A,
    const __half* __restrict__ B,
    __half* __restrict__ C,
    int batch,
    int M,
    int N,
    int K)
{
    // 2‑D thread layout per batch
    int b = blockIdx.z;                       // batch index
    int row = blockIdx.y * blockDim.y + threadIdx.y; // M dimension
    int col = blockIdx.x * blockDim.x + threadIdx.x; // N dimension

    if (b >= batch || row >= M || col >= N) return;

    const __half* A_batch = A + (size_t)b * M * K;
    const __half* B_batch = B + (size_t)b * K * N;
    __half*       C_batch = C + (size_t)b * M * N;

    const __half* a_row_ptr = A_batch + (size_t)row * K;   // start of A[row, :]
    const __half* b_col_ptr = B_batch + col;               // start of B[:, col]

    float acc = 0.0f;
    // loop over K dimension
    for (int k = 0; k < K; ++k) {
        // B is row‑major (K × N), so element (k, col) is at offset k*N + col
        __half a_val = a_row_ptr[k];
        __half b_val = b_col_ptr[(size_t)k * N];
        acc += __half2float(a_val) * __half2float(b_val);
    }

    C_batch[(size_t)row * N + col] = __float2half(acc);
