import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA LayerNorm (fp16 I/O, float accumulation)
# Optimizations:
#   * 1024 threads per block (max occupancy)
#   * Grid‑stride loops (each block processes a chunk of the instance)
#   * One‑pass Welford‑style reduction (sum & sum‑of‑squares) using half2 loads
#   * Warp‑shuffle reductions + single‑warp final reduction
#   * Minimal shared memory (per‑warp partials)
# ----------------------------------------------------------------------
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <int BLOCK_SIZE>
__device__ __forceinline__ float warp_reduce_sum(float val) {
