import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA kernel: fast fp16 LayerNorm (one block per outer slice, vectorized loads,
# 1024 threads per block, reduction in shared memory)
# ----------------------------------------------------------------------
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef MAX_TPB
#define MAX_TPB 1024
#endif

// ----------------------------------------------------------------------
// Helper: reduce sum in shared memory (in-place)
// ----------------------------------------------------------------------
__device__ inline float block_reduce_sum(float *sdata, int tid, int blockSize) {
    // tree reduction
    for (int stride = blockSize / 2; stride > 0; stride >>= 1) {
        __syncthreads();
        if (tid < stride) {
            sdata[tid] += sdata[tid + stride];
        }
    }
    __syncthreads();
    return sdata[0];
}

// ----------------------------------------------------------------------
// LayerNorm kernel
// ----------------------------------------------------------------------
__global__ void layernorm_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    int norm_size,
    float eps) {

    const int outer_idx = blockIdx.x;                     // one slice per block
    const __half* in_ptr  = input  + (size_t)outer_idx * norm_size;
    __half* out_ptr = output + (size_t)outer_idx * norm_size;

    const int tid = threadIdx.x;
    const int blockSize = blockDim.x;

    // --------------------------------------------------------------
    // 1) Vectorized pass: compute sum and sum of squares (float acc)
    // --------------------------------------------------------------
    const int half2_cnt = norm_size / 2;                  // number of __half2 elements
    const bool has_tail = (norm_size & 1);

    const __half2* in_ptr2 = reinterpret_cast<const __half2*>(in_ptr);
    const __half2* w_ptr2   = reinterpret_cast<const __half2*>(weight);
    const __half2* b_ptr2   = reinterpret_cast<const __half2*>(bias);

    float sum  = 0.0f;
    float sum2 = 0.0f;

    for (int i = tid; i < half2_cnt; i += blockSize) {
        // load two half values at once
        __half2 v2 = __ldg(&in_ptr2[i]);
        float2 f = __half22float2(v2);
        sum  += f.x + f.y;
        sum2 += f.x * f.x + f.y * f.y;
    }

    // tail element (if odd length)
    if (has_tail && tid == 0) {
        float v = __half2float(in_ptr[norm_size - 1]);
        sum  += v;
        sum2 += v * v;
    }

    // --------------------------------------------------------------
    // 2) Block-wide reduction (shared memory)
    // --------------------------------------------------------------
    __shared__ float s_sum[MAX_TPB];
    __shared__ float s_sum2[MAX_TPB];
    s_sum[tid]  = sum;
    s_sum2[tid] = sum2;
    __syncthreads();

    float block_sum  = block_reduce_sum(s_sum,  tid, blockSize);
    float block_sum2 = block_reduce_sum(s_sum2, tid, blockSize);

    // --------------------------------------------------------------
    // 3) Compute mean & inv_std (thread 0) and broadcast
    // --------------------------------------------------------------
    __shared__ float s_mean;
    __shared__ float s_inv_std;
    if (tid == 0) {
        float mean = block_sum / static_cast<float>(norm_size);
        float var  = block_sum2 / static_cast<float>(norm_size) - mean * mean;
        var = fmaxf(var, 0.0f);
        float inv_std = rsqrtf(var + eps);
        s_mean    = mean;
        s_inv_std = inv_std;
    }
    __syncthreads();
    const float mean    = s_mean;
    const float inv_std = s_inv_std;

    // --------------------------------------------------------------
    // 4) Second pass: normalize, apply affine, write output
    // --------------------------------------------------------------
    for (int i = tid; i < half2_cnt; i += blockSize) {
        // load input, weight, bias as half2
        __half2 vin2 = __ldg(&in_ptr2[i]);
        __half2 win2 = __ldg(&w_ptr2[i]);
        __half2 bin2 = __ldg(&b_ptr2[i]);

        float2 vin = __half22float2(vin2);
        float2 win = __half22float2(win2);
        float2 bin = __half22float2(bin2);

        // normalize
        vin.x = (vin.x - mean) * inv_std;
        vin.y = (vin.y - mean) * inv_std;

        // affine
        vin.x = vin.x * win.x + bin.x;
        vin.y = vin.y * win.y + bin.y;

        // store back as half2
        __half2 vout2 = __floats2half2_rn(vin.x, vin.y);
        reinterpret_cast<__half2*>(out_ptr)[i] = vout2;
    }

    // tail element (if odd length)
    if (has_tail && tid == 0) {
        float x = __half2float(in_ptr[norm_size - 1]);
        float w = __half2float(weight[norm_size - 1]);
        float b = __half2float(bias[norm_size - 1]);
        float y = (x - mean) * inv_std;
        y = y * w + b;
        out_ptr[norm_size - 1] = __float2half(y);
    }
}

