    const int64_t norm_size = weight.numel();                 // normalized dimension size
    const int64_t outer_size = input.numel() / norm_size;    // number of independent slices

    // choose block size: min(MAX_TPB, norm_size) but at least 32
    int block = static_cast<int>(norm_size);
    if (block > MAX_TPB) block = MAX_TPB;
