# ModelNew: drop‑in replacement for the reference Model
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple, eps: float = 1e-5):
        """
        LayerNorm implemented with custom CUDA kernels.
        Learnable parameters γ (weight) and β (bias) are stored in fp16.
        """
        super().__init__()
        self.normalized_shape = normalized_shape
        self.eps = eps

        # Parameters match the normalized dimensions, stored as fp16
        self.weight = nn.Parameter(
            torch.ones(*normalized_shape, dtype=torch.float16, device="cuda")
        )
        self.bias = nn.Parameter(
            torch.zeros(*normalized_shape, dtype=torch.float16, device="cuda")
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        x: (B, *normalized_shape) tensor, dtype float16, CUDA.
        Returns tensor of same shape and dtype.
        """
        if x.dtype != torch.float16:
            raise RuntimeError("ModelNew expects fp16 input")
        if not x.is_cuda:
            raise RuntimeError("ModelNew expects CUDA tensor")

        # flatten normalized dimensions
        B = x.size(0)
        N = 1
        for s in self.normalized_shape:
            N *= s

        # per‑sample mean & variance (float32)
        mean = layernorm_ext.layernorm_mean_cuda(x, N)                # (B,)
        var  = layernorm_ext.layernorm_var_cuda(x, mean, N, self.eps) # (B,)

        # expand weight / bias to (B, N) without extra memory copies
        w_exp = self.weight.view(1, -1).expand(B, -1).contiguous()
        b_exp = self.bias.view(1, -1).expand(B, -1).contiguous()

        # final normalized output (fp16)
        out = layernorm_ext.layernorm_forward_cuda(
            x, mean, var, w_exp, b_exp, self.eps
        )
        return out

