import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA kernels: fast half‑precision LayerNorm (affine=True)
# ----------------------------------------------------------------------
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

#ifndef CHECK_CUDA
#define CHECK_CUDA(x) TORCH_CHECK(x.is_cuda(), #x " must be a CUDA tensor")
#endif

// ---------------------------------------------------------------------
// Kernel 1: per‑sample mean and inverse std (single block per sample)
// ---------------------------------------------------------------------
template <int BLOCK_SIZE>
__global__ void layernorm_meanvar_kernel(
    const __half* __restrict__ input,
    float* __restrict__ mean,
    float* __restrict__ inv_std,
    int N,
    float eps)
{
    // one block per sample (batch dimension)
    int batch_idx = blockIdx.x;
    const __half* sample = input + (size_t)batch_idx * N;

    // reduction buffers in shared memory
    __shared__ float s_sum[BLOCK_SIZE];
    __shared__ float s_sumsq[BLOCK_SIZE];

    float sum = 0.0f;
    float sumsq = 0.0f;

    // grid‑stride loop over elements of this sample
    for (int i = threadIdx.x; i < N; i += BLOCK_SIZE) {
        float v = __half2float(__ldg(sample + i));
        sum   += v;
        sumsq += v * v;
    }

    s_sum[threadIdx.x]   = sum;
    s_sumsq[threadIdx.x] = sumsq;
    __syncthreads();

    // parallel reduction (tree)
    for (int stride = BLOCK_SIZE >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x]   += s_sum[threadIdx.x + stride];
            s_sumsq[threadIdx.x] += s_sumsq[threadIdx.x + stride];
        }
        __syncthreads();
    }

    // write results (thread 0 of each block)
    if (threadIdx.x == 0) {
        float mu   = s_sum[0] / N;
        float var  = s_sumsq[0] / N - mu * mu;
        var = fmaxf(var, 0.0f);               // guard against negative variance
        mean[batch_idx]    = mu;
        inv_std[batch_idx] = rsqrtf(var + eps);
    }
}

// ---------------------------------------------------------------------
// Kernel 2: normalize and apply affine parameters
// ---------------------------------------------------------------------
template <int BLOCK_SIZE>
__global__ void layernorm_apply_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    const float* __restrict__ mean,
    const float* __restrict__ inv_std,
    __half* __restrict__ output,
    int N)
{
    int batch_idx = blockIdx.x;
    const __half* in  = input  + (size_t)batch_idx * N;
    __half*       out = output + (size_t)batch_idx * N;

    float mu = mean[batch_idx];
    float is = inv_std[batch_idx];

    for (int i = threadIdx.x; i < N; i += BLOCK_SIZE) {
        float x = __half2float(__ldg(in  + i));
        float w = __half2float(__ldg(weight + i));
        float b = __half2float(__ldg(bias   + i));

        float y = (x - mu) * is;          // normalize
        float z = y * w + b;               // affine

        out[i] = __float2half(z);
    }
}

// ---------------------------------------------------------------------
// Wrapper visible from Python
// ---------------------------------------------------------------------
torch::Tensor layernorm_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float eps)
{
    CHECK_CUDA(input);
    CHECK_CUDA(weight);
    CHECK_CUDA(bias);
    TORCH_CHECK(input.dtype()  == torch::kFloat16, "input must be float16");
    TORCH_CHECK(weight.dtype() == torch::kFloat16, "weight must be float16");
    TORCH_CHECK(bias.dtype()   == torch::kFloat16, "bias must be float16");

    input  = input.contiguous();
    weight = weight.contiguous();
