    int b = blockIdx.x;
    if (b >= batch) return;

    int tid = threadIdx.x;
    int stride = BLOCK_THREADS;

    // ---- first pass: compute mean and variance ----
    float sum = 0.f;
    float sumsq = 0.f;
    for (int i = tid; i < N; i += stride) {
        __half h = input[b * N + i];
        float v = __half2float(h);
        sum   += v;
        sumsq += v * v;
