#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef CHECK_CUDA
#define CHECK_CUDA(x) TORCH_CHECK(x.is_cuda(), #x " must be a CUDA tensor")
#endif
#ifndef CHECK_CONTIGUOUS
#define CHECK_CONTIGUOUS(x) TORCH_CHECK(x.is_contiguous(), #x " must be contiguous")
#endif
#ifndef CHECK_INPUT
#define CHECK_INPUT(x) CHECK_CUDA(x); CHECK_CONTIGUOUS(x)
#endif

// ---------------------------------------------------------------
// warp‑level sum reduction (float) – works on all CCs
// ---------------------------------------------------------------
__forceinline__ __device__ float warp_reduce_sum(float v) {
    #pragma unroll
    for (int offset = warpSize/2; offset > 0; offset >>= 1) {
        v += __shfl_down_sync(0xffffffff, v, offset);
    }
    return v;
}

// ---------------------------------------------------------------
// LayerNorm kernel (fp16 I/O, fp32 accumulation)
// ---------------------------------------------------------------
template <int BLOCK_SIZE>
__global__ void layernorm_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    const int64_t total,          // elements per sample to normalize
    const float eps) {

    constexpr int WARPS = BLOCK_SIZE / 32;
    __shared__ float warp_sum[WARPS];
    __shared__ float warp_sum2[WARPS];
    __shared__ float block_mean;
    __shared__ float block_inv_std;

    const int batch_idx = blockIdx.x;          // one block per sample
    const int tid       = threadIdx.x;
    const int lane      = tid & 31;
    const int warp_id   = tid >> 5;

    const __half* in_ptr = input  + batch_idx * total;
    const __half* w_ptr  = weight;
    const __half* b_ptr  = bias;
    __half* out_ptr      = output + batch_idx * total;

    // -----------------------------------------------------------
    // 1) compute sum and sum of squares (vectorized half2)
    // -----------------------------------------------------------
    float sum  = 0.0f;
    float sum2 = 0.0f;

    // process two half elements per iteration
    int64_t i = tid * 2;
    for (; i + 1 < total; i += BLOCK_SIZE * 2) {
        const __half2 h = *reinterpret_cast<const __half2*>(in_ptr + i);
        const float2 f = __half22float2(h);
        sum  += f.x + f.y;
        sum2 += f.x * f.x + f.y * f.y;
    }
    // tail element
    if (i < total) {
        float v = __half2float(in_ptr[i]);
        sum  += v;
        sum2 += v * v;
    }

    // warp reduction
    sum  = warp_reduce_sum(sum);
    sum2 = warp_reduce_sum(sum2);

    // store per‑warp partials
    if (lane == 0) {
        warp_sum[warp_id]  = sum;
        warp_sum2[warp_id] = sum2;
    }
    __syncthreads();

    // first warp finishes reduction across warps
    if (warp_id == 0) {
        float wsum  = (tid < WARPS) ? warp_sum[tid]  : 0.0f;
        float wsum2 = (tid < WARPS) ? warp_sum2[tid] : 0.0f;
        wsum  = warp_reduce_sum(wsum);
        wsum2 = warp_reduce_sum(wsum2);
        if (tid == 0) {
            float mean = wsum / static_cast<float>(total);
            float var  = wsum2 / static_cast<float>(total) - mean * mean;
            float inv_std = rsqrtf(var + eps);
            block_mean    = mean;
            block_inv_std = inv_std;
        }
    }
    __syncthreads();

    const float mean    = block_mean;
    const float inv_std = block_inv_std;

    // -----------------------------------------------------------
    // 2) normalize, apply affine transform, write back
    // -----------------------------------------------------------
    i = tid * 2;
    for (; i + 1 < total; i += BLOCK_SIZE * 2) {
        // load input
        const __half2 h_in = *reinterpret_cast<const __half2*>(in_ptr + i);
        const float2 f_in = __half22float2(h_in);

        // load weight & bias via __ldg (read‑only cache)
        const __half2 h_w = *reinterpret_cast<const __half2*>(w_ptr + i);
        const __half2 h_b = *reinterpret_cast<const __half2*>(b_ptr + i);
        const float2 f_w = __half22float2(h_w);
        const float2 f_b = __half22float2(h_b);

        // element 0
        float y0 = (f_in.x - mean) * inv_std;
        y0 = y0 * f_w.x + f_b.x;
        // element 1
        float y1 = (f_in.y - mean) * inv_std;
        y1 = y1 * f_w.y + f_b.y;

        // pack and store
        __half2 h_out;
        h_out.x = __float2half(y0);
        h_out.y = __float2half(y1);
        *reinterpret_cast<__half2*>(out_ptr + i) = h_out;
    }
    // tail element
    if (i < total) {
        float x = __half2float(in_ptr[i]);
        float w = __half2float(w_ptr[i]);
        float b = __half2float(b_ptr[i]);
        float y = (x - mean) * inv_std;
        y = y * w + b;
        out_ptr[i] = __float2half(y);
    }
}

// ---------------------------------------------------------------
// Wrapper exposed to Python
// ---------------------------------------------------------------
torch::Tensor layernorm_cuda(torch::Tensor input,
                             torch::Tensor weight,
