#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void maxpool2d_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    int batch_size,
    int channels,
    int input_height,
    int input_width,
    int output_height,
    int output_width,
    int kernel_size,
    int stride,
    int padding,
    int dilation) {

    int batch_idx = blockIdx.x;
    int channel_idx = blockIdx.y;
    int output_h = blockIdx.z * blockDim.x + threadIdx.x;
    int output_w = threadIdx.y;

    if (output_h >= output_height || output_w >= output_width) return;

    int input_h_start = output_h * stride - padding;
    int input_w_start = output_w * stride - padding;

    __half max_val = __ushort_as_half(0xFC00); // -INFINITY in fp16
    bool initialized = false;

    for (int kh = 0; kh < kernel_size; kh++) {
        for (int kw = 0; kw < kernel_size; kw++) {
            int input_h = input_h_start + kh * dilation;
            int input_w = input_w_start + kw * dilation;

            if (input_h >= 0 && input_h < input_height && 
                input_w >= 0 && input_w < input_width) {

                int input_idx = batch_idx * (channels * input_height * input_width) +
                               channel_idx * (input_height * input_width) +
                               input_h * input_width + input_w;

                __half val = input[input_idx];
                if (!initialized || __hgt(val, max_val)) {
                    max_val = val;
                    initialized = true;
                }
            }
        }
    }

    int output_idx = batch_idx * (channels * output_height * output_width) +
                     channel_idx * (output_height * output_width) +
                     output_h * output_width + output_w;

    output[output_idx] = max_val;
}

