#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef TILE_H
#define TILE_H 32          // output tile height per block
#endif
#ifndef TILE_W
#define TILE_W 32          // output tile width  per block
#endif

// -----------------------------------------------------------------
// Kernel
// -----------------------------------------------------------------
__global__ void maxpool2d_shared_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    const int N, const int C,
    const int H, const int W,
    const int H_out, const int W_out,
    const int kernel_h, const int kernel_w,
    const int stride_h, const int stride_w,
    const int pad_h, const int pad_w,
    const int dilation_h, const int dilation_w)
{
    // -----------------------------------------------------------------
    // 1) identify batch & channel handled by this block
    // -----------------------------------------------------------------
    const int nc = blockIdx.z;                 // 0 .. N*C-1
    const int n  = nc / C;
    const int c  = nc % C;

    // -----------------------------------------------------------------
    // 2) coordinates of the output tile this block works on
    // -----------------------------------------------------------------
    const int out_tile_y = blockIdx.y * TILE_H;
    const int out_tile_x = blockIdx.x * TILE_W;

    // -----------------------------------------------------------------
    // 3) size of the input region that must be resident in shared mem
    //    (covers all inputs needed for the whole output tile)
    // -----------------------------------------------------------------
    const int in_region_h = (TILE_H - 1) * stride_h + (kernel_h - 1) * dilation_h + 1;
    const int in_region_w = (TILE_W - 1) * stride_w + (kernel_w - 1) * dilation_w + 1;

    // -----------------------------------------------------------------
    // 4) allocate dynamic shared memory: in_region_h * in_region_w half values
    // -----------------------------------------------------------------
    extern __shared__ __half shmem[];
    const int sh_stride = in_region_w;                 // leading dimension in shared mem

    // -----------------------------------------------------------------
    // 5) each thread loads one (or more) input elements into shared memory
    // -----------------------------------------------------------------
    const int threads_per_block = blockDim.x * blockDim.y;
    const int thread_id = threadIdx.y * blockDim.x + threadIdx.x;
    const int total_sh_elements = in_region_h * in_region_w;
    const __half neg_inf = __float2half(-65504.0f);     // smallest half (acts as -inf)

    for (int idx = thread_id; idx < total_sh_elements; idx += threads_per_block) {
        int sy = idx / in_region_w;    // 0 .. in_region_h-1
        int sx = idx % in_region_w;    // 0 .. in_region_w-1

        // corresponding input coordinate (before padding)
        int in_y = out_tile_y * stride_h - pad_h + sy;
        int in_x = out_tile_x * stride_w - pad_w + sx;

        __half val = neg_inf;
        if (in_y >= 0 && in_y < H && in_x >= 0 && in_x < W) {
            // linear index into input: ((n*C + c)*H + in_y)*W + in_x
            int64_t in_idx = ((int64_t)n * C + c) * H * W + (int64_t)in_y * W + in_x;
            val = input[in_idx];
        }
        shmem[sy * sh_stride + sx] = val;
    }
    __syncthreads();

    // -----------------------------------------------------------------
    // 6) compute max for each valid output element inside the tile
    // -----------------------------------------------------------------
    const int ty = threadIdx.y;
    const int tx = threadIdx.x;
    const int out_y = out_tile_y + ty;
    const int out_x = out_tile_x + tx;

    if (ty < TILE_H && tx < TILE_W && out_y < H_out && out_x < W_out) {
        float max_val = -1e20f;        // sentinel in float

        // iterate over kernel window
        #pragma unroll
        for (int kh = 0; kh < kernel_h; ++kh) {
            int sh_y = ty * stride_h + kh * dilation_h;
            #pragma unroll
            for (int kw = 0; kw < kernel_w; ++kw) {
