                                  int64_t total_elements, int64_t reduce_dim_size,
                                  int64_t outer_size, int64_t inner_size) {
    // Use shared memory for reduction within block
    extern __shared__ float sdata[];

    int64_t tid = threadIdx.x;
    int64_t bid = blockIdx.x;

    // Grid-stride loop to handle all elements
    for (int64_t idx = bid * blockDim.x + tid; 
         idx < total_elements; 
         idx += gridDim.x * blockDim.x) {

        // Calculate outer and inner indices
        int64_t inner_idx = idx % inner_size;
        int64_t outer_idx = idx / inner_size;

        // Initialize sum for this element
        float sum_val = 0.0f;

        // Each thread processes multiple elements if necessary
        for (int64_t offset = 0; offset < reduce_dim_size; offset++) {
            int64_t input_idx = outer_idx * reduce_dim_size * inner_size + offset * inner_size + inner_idx;
