// ---------------------------------------------------------------------
// Sum reduction over a given dimension (keepdim=True)
// Input/Output are fp16 tensors. Accumulation performed in FP32.
// One block processes a tile of the innermost dimension for a single
// outer index (batch). Loop over the reduction axis is unrolled for
// better instruction-level parallelism.
// ---------------------------------------------------------------------
template <int BLOCK_SIZE>
__global__ void sum_reduce_kernel(const __half* __restrict__ in,
                                  __half* __restrict__ out,
                                  int64_t outer,
                                  int64_t reduce,
                                  int64_t inner) {
    // 2‑D grid: x -> inner tiles, y -> outer index
    int64_t outer_idx = blockIdx.y;
    int64_t inner_idx = blockIdx.x * BLOCK_SIZE + threadIdx.x;

    if (outer_idx >= outer || inner_idx >= inner) return;

    // pointer to the first element of the reduction axis for this (outer,inner)
    const __half* ptr = in + outer_idx * reduce * inner + inner_idx;

    float sum = 0.0f;
    int64_t r = 0;

    // Unroll the reduction loop by 4 for better ILP.
    for (; r + 3 < reduce; r += 4) {
        sum += __half2float(__ldg(ptr + (r    ) * inner));
        sum += __half2float(__ldg(ptr + (r+1) * inner));
        sum += __half2float(__ldg(ptr + (r+2) * inner));
        sum += __half2float(__ldg(ptr + (r+3) * inner));
    }
    for (; r < reduce; ++r) {
        sum += __half2float(__ldg(ptr + r * inner));
    }

    // write result (keepdim => output shape outer x 1 x inner)
    out[outer_idx * inner + inner_idx] = __float2half(sum);
}

