    int64_t outer = 1;
    for (int64_t i = 0; i < dim; ++i) outer *= inp.size(i);
    int64_t reduce = inp.size(dim);
    int64_t inner = 1;
    for (int64_t i = dim + 1; i < inp.dim(); ++i) inner *= inp.size(i);

    // Prepare output (keepdim=True).
    std::vector<int64_t> out_sizes(inp.sizes().vec());
    out_sizes[dim] = 1;
