__global__ void sum_reduce_kernel(const __half* __restrict__ in,
                                  __half* __restrict__ out,
                                  int64_t outer,      // product of dims before the reduced dim
                                  int64_t inner,      // product of dims after the reduced dim
                                  int64_t reduce_len) // size of the reduced dimension
