# ----------------------------------------------------------------------
# CUDA source: optimized sum reduction over dim=1 (float16 input/output)
# ----------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

#ifndef CHECK
#define CHECK(x) TORCH_CHECK(x, #x)
#endif

// ------------------------------------------------------------------
// Kernel: one block per (batch, col) pair.
// Each thread accumulates a strided subset of the reduction dimension
// into a float accumulator, then performs a warp‑shuffle reduction
// followed by a final reduction of warp results in shared memory.
// ------------------------------------------------------------------
template <int BLOCK_SIZE>
__global__ void sum_reduce_dim1_opt_kernel(
        const __half* __restrict__ in,
        __half* __restrict__ out,
        int B, int D1, int D2) {

    const int col   = blockIdx.x;   // dimension 2 index
    const int batch = blockIdx.y;   // dimension 0 index
    const int tid   = threadIdx.x;

    const __half* __restrict__ batch_ptr = in + batch * D1 * D2;

    // ----------------------------------------------------------------
    // 1) per‑thread accumulation over dim=1
    // ----------------------------------------------------------------
    float acc = 0.0f;
    // each thread processes elements spaced BLOCK_SIZE apart
    for (int d = tid; d < D1; d += BLOCK_SIZE) {
        // element (batch, d, col)
        acc += __half2float(__ldg(batch_ptr + d * D2 + col));
    }

    // ----------------------------------------------------------------
    // 2) warp‑level reduction using shuffles
    // ----------------------------------------------------------------
    const int lane   = tid & 31;                // thread index inside warp
    const int warpId = tid >> 5;                // warp number inside block

    // intra‑warp reduction
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        acc += __shfl_down_sync(0xffffffff, acc, offset);
    }

    // write per‑warp partial sums to shared memory
    __shared__ float warp_sums[BLOCK_SIZE / 32];
    if (lane == 0) {
        warp_sums[warpId] = acc;
    }
    __syncthreads();

    // ----------------------------------------------------------------
    // 3) final reduction of warp results (first warp only)
    // ----------------------------------------------------------------
    float block_sum = 0.0f;
    if (tid < (BLOCK_SIZE / 32)) {
        block_sum = warp_sums[tid];
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            block_sum += __shfl_down_sync(0xffffffff, block_sum, offset);
        }
    }

    // thread 0 writes the final reduced value
    if (tid == 0) {
        out[batch * D2 + col] = __float2half(block_sum);
    }
}

// ------------------------------------------------------------------
// Wrapper called from Python
// ------------------------------------------------------------------
torch::Tensor sum_reduce_dim1_opt_cuda(torch::Tensor input, int64_t dim) {
    CHECK(dim == 1) << "Only reduction over dim==1 is supported.";
    CHECK(input.is_cuda()) << "Input must be a CUDA tensor.";
    CHECK(input.scalar_type() == at::kHalf) << "Input must be float16.";
    CHECK(input.dim() == 3) << "Input must be 3‑D.";

    const int B  = input.size(0);
    const int D1 = input.size(1);
    const int D2 = input.size(2);

    auto output = torch::empty({B, 1, D2}, input.options());

    constexpr int BLOCK_SIZE = 256;          // must be multiple of 32
    dim3 block(BLOCK_SIZE);
    dim3 grid(D2, B);                        // x: column, y: batch

    sum_reduce_dim1_opt_kernel<BLOCK_SIZE><<<grid, block>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        B, D1, D2);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch failed: ", cudaGetErrorString(err));
    }
    return output;
}
