// TILE size (threads per block) – must be <= 1024 and a multiple of warp size
constexpr int TILE = 128;

// One block processes TILE columns of a single batch element.
template <int TILE_SZ>
__global__ void sum_reduce_dim1_coalesced_kernel(
        const __half* __restrict__ in,
        __half* __restrict__ out,
        int B, int D1, int D2) {

    const int batch_idx = blockIdx.x / ((D2 + TILE_SZ - 1) / TILE_SZ);
    const int tile_idx  = blockIdx.x % ((D2 + TILE_SZ - 1) / TILE_SZ);
    const int col_start = tile_idx * TILE_SZ;
    const int tid       = threadIdx.x;
    const int col       = col_start + tid;

    if (batch_idx >= B || col >= D2) return;

    float acc = 0.0f;
    // stride between successive rows in the innermost dimension
    const int row_stride = D2;

    // base pointer for this batch
    const __half* __restrict__ base = in + batch_idx * D1 * D2;

    // loop over reduction dimension (D1)
