    for (int d1 = 0; d1 < D1; ++d1) {
        // address: base + d1*D2 + col
        acc += __half2float(base[d1 * row_stride + col]);
    }

    // write result (output is (B,1,D2) -> flattened as B*D2)
    out[batch_idx * D2 + col] = __float2half(acc);
