# ----------------------------------------------------------------------
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

template <int UNROLL>
__global__ void sum_reduce_kernel_fp16(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    int64_t B,
    int64_t R,
    int64_t I)
{
    // each thread processes a pair of consecutive i indices (i0,i1)
    // total number of i‑pairs per batch
    int64_t I_pair = (I + 1) >> 1;               // ceil(I/2)

    int64_t total_pairs = B * I_pair;
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = gridDim.x * blockDim.x;

    for (; idx < total_pairs; idx += stride) {
        int64_t b = idx / I_pair;                // batch index
        int64_t ip = idx % I_pair;               // pair index within batch
        int64_t i0 = ip << 1;                    // first i
        int64_t i1 = i0 + 1;                     // second i (may be out‑of‑range)

        const __half* batch_ptr = input + b * R * I;   // start of batch

        float acc0 = 0.0f;
        float acc1 = 0.0f;

        // iterate over reduction dimension R
        int64_t r = 0;
        #pragma unroll
        for (; r + UNROLL - 1 < R; r += UNROLL) {
            #pragma unroll
            for (int u = 0; u < UNROLL; ++u) {
                // pointer to the row r+u, offset by i0 (contiguous for i0,i1)
                const __half2* row_ptr = reinterpret_cast<const __half2*>(batch_ptr + (r + u) * I + i0);
                // safe to read half2 even if i1==I (out‑of‑range) because the
                // launch guarantees i0 < I and we guard writes later.
                __half2 h2 = __ldg(row_ptr);
                float2 f2 = __half2float(h2);
                acc0 += f2.x;
                acc1 += f2.y;
            }
        }
        // tail loop for remaining rows
        for (; r < R; ++r) {
            const __half2* row_ptr = reinterpret_cast<const __half2*>(batch_ptr + r * I + i0);
            __half2 h2 = __ldg(row_ptr);
            float2 f2 = __half2float(h2);
            acc0 += f2.x;
            if (i1 < I) acc1 += f2.y;   // avoid reading past end when I is odd
        }

        // write results
        int64_t out_base = b * I;
        output[out_base + i0] = __float2half(acc0);
        if (i1 < I) {
            output[out_base + i1] = __float2half(acc1);
        }
    }
}

