    auto output = torch::empty({B, 1, I}, input.options());

    const int threads = 256;
    const int64_t I_pair = (I + 1) >> 1;
    const int64_t total_pairs = B * I_pair;
    const int blocks = (total_pairs + threads - 1) / threads;

    // unroll factor 8 gives a good balance
    sum_reduce_kernel_fp16<8><<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
