    // Spatial start of this block in output tensor
    // --------------------------------------------------------------
    int out_y0 = blockIdx.y * BLOCK_H;       // top‑left output row
    int out_x0 = blockIdx.x * BLOCK_W;       // top‑left output col

    // --------------------------------------------------------------
    // Size of the input tile required for this block
    // --------------------------------------------------------------
    const int TILE_H = (BLOCK_H - 1) * STRIDE + KERNEL_H;   // 71 for given params
    const int TILE_W = (BLOCK_W - 1) * STRIDE + KERNEL_W;   // 71

    // --------------------------------------------------------------
    // Shared memory layout: [C][TILE_H][TILE_W] of __half
    // --------------------------------------------------------------
    extern __shared__ __half shmem[];
    // helper to index into shared memory
    // idx = ((c * TILE_H) + ty) * TILE_W + tx
    // --------------------------------------------------------------

    // --------------------------------------------------------------
    // Load input tile cooperatively
    // --------------------------------------------------------------
    int threads_per_block = BLOCK_H * BLOCK_W;
    int thread_id = threadIdx.y * BLOCK_W + threadIdx.x;   // 0 … threads_per_block-1
    int total_elems = C * TILE_H * TILE_W;

    for (int idx = thread_id; idx < total_elems; idx += threads_per_block) {
        int c   = idx / (TILE_H * TILE_W);
        int rem = idx % (TILE_H * TILE_W);
        int ty  = rem / TILE_W;
        int tx  = rem % TILE_W;

        // Global input coordinates that correspond to this shared element
        int ih = -PAD + out_y0 * STRIDE + ty;
        int iw = -PAD + out_x0 * STRIDE + tx;

        __half val = __float2half(0.0f);
