            int in_idx = ((n * C + c) * H + ih) * W + iw;
            val = __ldg(input + in_idx);
        }
        shmem[(c * TILE_H + ty) * TILE_W + tx] = val;
    }
    __syncthreads();

    // --------------------------------------------------------------
    // Compute one output element per thread (if inside bounds)
    // --------------------------------------------------------------
    int out_y = out_y0 + threadIdx.y;
    int out_x = out_x0 + threadIdx.x;
    if (out_y < OH && out_x < OW) {
        float acc = __half2float(bias[oc]);   // bias per output channel

        // iterate over input channels and kernel spatial dims
        for (int ic = 0; ic < C; ++ic) {
            const __half* w_ptr = weight + ((oc * C + ic) * KERNEL_H * KERNEL_W);
            for (int kh = 0; kh < KERNEL_H; ++kh) {
                int sh_y = threadIdx.y * STRIDE + kh;   // shared‑mem row
                for (int kw = 0; kw < KERNEL_W; ++kw) {
                    int sh_x = threadIdx.x * STRIDE + kw;   // shared‑mem col
                    __half in_val = shmem[(ic * TILE_H + sh_y) * TILE_W + sh_x];
                    __half w_val  = __ldg(w_ptr + kh * KERNEL_W + kw);
                    acc += __half2float(in_val) * __half2float(w_val);
                }
            }
        }

        int out_idx = ((n * OC + oc) * OH + out_y) * OW + out_x;
        output[out_idx] = __float2half(acc);
    }
