    // 1) load required input patch into shared memory (once per block)
    // ------------------------------------------------------------------
    __shared__ __half sh_input[C_IN][SH_IN_H][SH_IN_W];

    // each thread loads multiple elements to fill the tile
    for (int ic = 0; ic < C_IN; ++ic) {
        // linear thread id within the block
        int tid = threadIdx.y * blockDim.x + threadIdx.x;
        int num_threads = blockDim.x * blockDim.y;
        int total = SH_IN_H * SH_IN_W;
        for (int idx = tid; idx < total; idx += num_threads) {
            int sh_i = idx / SH_IN_W;
            int sh_j = idx % SH_IN_W;
            int ih = oh0 * STRIDE - PAD + sh_i;
            int iw = ow0 * STRIDE - PAD + sh_j;
