    int64_t stride = blockDim.x * gridDim.x;

    for (; idx < out_numel; idx += stride) {
        int64_t base_offset = 0;
        int64_t red_size = 0;

        // Map linear idx of output (which lacks the reduced dim) to
        // multi‑dimensional coordinates of the input.
        if (dim == 0) {
            // output shape: (dim1, dim2)
            int64_t i1 = idx % dim1;
            int64_t i2 = idx / dim1;
            base_offset = i1 * stride1 + i2 * stride2;
            red_size = dim0;
        } else if (dim == 1) {
            // output shape: (dim0, dim2)
            int64_t i0 = idx % dim0;
            int64_t i2 = idx / dim0;
            base_offset = i0 * stride0 + i2 * stride2;
            red_size = dim1;
        } else { // dim == 2
            // output shape: (dim0, dim1)
            int64_t i0 = idx % dim0;
            int64_t i1 = idx / dim0;
            base_offset = i0 * stride0 + i1 * stride1;
            red_size = dim2;
