        int64_t residual = tid;
        int64_t base_offset = 0;
        for (int64_t d = 0; d < rank; ++d) {
            if (d == dim) continue;
            int64_t idx = residual % shape[d];
            residual /= shape[d];
            base_offset += idx * stride[d];
        }

        // Scan along the reduction dimension.
        float best_val = -FLT_MAX;
        int64_t best_idx = 0;
        int64_t red_stride = stride[dim];
        for (int64_t k = 0; k < reduction_size; ++k) {
