template <int BLOCK_SIZE>
__global__ void argmax_kernel_half(
    const __half* __restrict__ input,
    int64_t* __restrict__ output,
    int64_t dim_size,
    int64_t size_pre,
    int64_t size_post) {

    // each block processes one (pre,post) slice
    int64_t slice_id = blockIdx.x;
    if (slice_id >= size_pre * size_post) return;

    int64_t i_pre  = slice_id / size_post;
    int64_t i_post = slice_id % size_post;

    // base offset for this slice (stride over dim is size_post)
    int64_t base = i_pre * (dim_size * size_post) + i_post;

    // thread‑local maximum
    float thread_max = -FLT_MAX;
    int64_t thread_idx = 0;

    // strided scan over the reduction dimension
    for (int64_t k = threadIdx.x; k < dim_size; k += BLOCK_SIZE) {
        __half v_h = input[base + k * size_post];
        float v = __half2float(v_h);
        if (v > thread_max) {
            thread_max = v;
            thread_idx = k;
        }
    }

    // shared‑memory reduction
    __shared__ float smax[BLOCK_SIZE];
    __shared__ int64_t sidx[BLOCK_SIZE];
    int tid = threadIdx.x;
    smax[tid] = thread_max;
    sidx[tid] = thread_idx;
    __syncthreads();

    // reduce to the maximum (tie‑break by smaller index)
    for (int offset = BLOCK_SIZE / 2; offset > 0; offset >>= 1) {
        if (tid < offset) {
            float cand_max = smax[tid + offset];
            int64_t cand_idx = sidx[tid + offset];
            if (cand_max > smax[tid] ||
                (cand_max == smax[tid] && cand_idx < sidx[tid])) {
                smax[tid] = cand_max;
                sidx[tid] = cand_idx;
            }
        }
        __syncthreads();
    }

    // write result
    if (tid == 0) {
        output[slice_id] = sidx[0];
    }
}

