    const int64_t ndims = input.dim();
    dim = (dim < 0) ? (dim + ndims) : dim;
    TORCH_CHECK(dim >= 0 && dim < ndims, "dim out of range");

    int64_t dim_size = input.size(dim);
    int64_t size_pre = 1;
    for (int64_t i = 0; i < dim; ++i) size_pre *= input.size(i);
    int64_t size_post = 1;
    for (int64_t i = dim + 1; i < ndims; ++i) size_post *= input.size(i);

