    int stride_h,
    int pad_d,
    int pad_w,
    int pad_h,
    int dilation_d,
    int dilation_w,
    int dilation_h,
    int groups
) {
    int batch_idx = blockIdx.x;
    int out_ch_idx = blockIdx.y;
    int out_d = blockIdx.z * blockDim.x + threadIdx.x;
    int out_w = blockIdx.w * blockDim.y + threadIdx.y;
    int out_h = threadIdx.z;

    if (out_d >= output_depth || out_w >= output_width || out_h >= output_height) return;

    int group_size = out_channels / groups;
    int group_idx = out_ch_idx / group_size;
    int weight_out_ch_idx = out_ch_idx % group_size;

    __half sum = __float2half(0.0f);

    for (int ic = 0; ic < in_channels; ++ic) {
        for (int kd = 0; kd < kernel_depth; ++kd) {
            for (int kw = 0; kw < kernel_width; ++kw) {
                for (int kh = 0; kh < kernel_height; ++kh) {
                    int input_d = out_d * stride_d - pad_d + kd * dilation_d;
                    int input_w = out_w * stride_w - pad_w + kw * dilation_w;
                    int input_h = out_h * stride_h - pad_h + kh * dilation_h;

                    if (input_d >= 0 && input_d < input_depth &&
                        input_w >= 0 && input_w < input_width &&
                        input_h >= 0 && input_h < input_height) {

