# ---------------------------------------------------------------
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void conv3d_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,          // nullptr if no bias
    __half* __restrict__ output,
    int N,
    int C_in,
    int D_in,
    int H_in,
    int W_in,
    int C_out,
    int K,
    int stride,
    int padding,
    int dilation,
    int groups,
    int D_out,
    int H_out,
    int W_out)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C_out * D_out * H_out * W_out;
    if (idx >= total) return;

    // ---- unravel linear index ----
    int w_out = idx % W_out; idx /= W_out;
    int h_out = idx % H_out; idx /= H_out;
    int d_out = idx % D_out; idx /= D_out;
    int c_out = idx % C_out; idx /= C_out;
    int n = idx;  // batch index

    int channels_per_group = C_in / groups;
    int out_per_group = C_out / groups;
    int group_id = c_out / out_per_group;
    int c_in_start = group_id * channels_per_group;

    float acc = 0.0f;

    // ---- iterate over input channels belonging to this group ----
    for (int ic = 0; ic < channels_per_group; ++ic) {
        int c_in = c_in_start + ic;

        // ---- iterate over the kernel volume ----
        for (int kd = 0; kd < K; ++kd) {
            int d_in = d_out * stride - padding + kd * dilation;
            if (d_in < 0 || d_in >= D_in) continue;
            for (int kh = 0; kh < K; ++kh) {
                int h_in = h_out * stride - padding + kh * dilation;
                if (h_in < 0 || h_in >= H_in) continue;
                for (int kw = 0; kw < K; ++kw) {
                    int w_in = w_out * stride - padding + kw * dilation;
                    if (w_in < 0 || w_in >= W_in) continue;

                    // input offset
                    int input_offset = (((((n * C_in + c_in) * D_in + d_in) * H_in + h_in) * W_in) + w_in);
                    // weight offset (layout: [C_out, C_in/groups, K, K, K])
                    int weight_offset = ((((c_out * channels_per_group + ic) * K + kd) * K + kh) * K + kw);

                    float inp = __half2float(input[input_offset]);
                    float wgt = __half2float(weight[weight_offset]);
                    acc += inp * wgt;
                }
            }
        }
    }

    if (bias != nullptr) {
        acc += __half2float(bias[c_out]);
    }

    // write output
    int out_offset = (((((n * C_out + c_out) * D_out + d_out) * H_out + h_out) * W_out) + w_out);
    output[out_offset] = __float2half(acc);
}

torch::Tensor conv3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups)
{
    // input: [N, C_in, D, H, W]
    // weight: [C_out, C_in/groups, K, K, K]
    const int N   = input.size(0);
    const int C_in = input.size(1);
    const int D_in = input.size(2);
    const int H_in = input.size(3);
    const int W_in = input.size(4);
    const int C_out = weight.size(0);
    const int K = weight.size(2);   // kernel size (cubic)

    const int D_out = (D_in + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int H_out = (H_in + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int W_out = (W_in + 2 * padding - dilation * (K - 1) - 1) / stride + 1;

    auto options = input.options();
    torch::Tensor output = torch::empty({N, C_out, D_out, H_out, W_out}, options);

    const int total = N * C_out * D_out * H_out * W_out;
    const int threads = 256;
    const int blocks = (total + threads - 1) / threads;

    const __half* input_ptr  = reinterpret_cast<const __half*>(input.data_ptr<at::Half>());
    const __half* weight_ptr = reinterpret_cast<const __half*>(weight.data_ptr<at::Half>());
    const __half* bias_ptr   = nullptr;
