cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cstdint>

//---------------------------------------------------------------
// Kernel: one thread per output element (N, C_out, D_out, H_out, W_out)
//---------------------------------------------------------------
__global__ void conv3d_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,          // nullptr if no bias
    __half* __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int K, int stride, int padding,
    int dilation, int groups,
    int D_out, int H_out, int W_out)
{
    // Total number of output elements
    int64_t total = (int64_t)N * C_out * D_out * H_out * W_out;
    int64_t tid   = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t step  = (int64_t)gridDim.x * blockDim.x;

    for (int64_t linear_idx = tid; linear_idx < total; linear_idx += step) {
        // Decode linear index -> (n, oc, od, oh, ow)
        int64_t idx = linear_idx;
        int ow = idx % W_out; idx /= W_out;
        int oh = idx % H_out; idx /= H_out;
        int od = idx % D_out; idx /= D_out;
        int oc = idx % C_out; idx /= C_out;
        int n  = (int)idx;                     // remaining is batch index

        int C_out_per_group = C_out / groups;
        int C_in_per_group  = C_in  / groups;
        int g = oc / C_out_per_group;                 // group index
        int ic_start = g * C_in_per_group;
        int ic_end   = ic_start + C_in_per_group;

        float acc = 0.0f;   // accumulate in FP32

        for (int ic = ic_start; ic < ic_end; ++ic) {
            for (int kd = 0; kd < K; ++kd) {
                int id = od * stride - padding + kd * dilation;
                if (id < 0 || id >= D_in) continue;
                for (int kh = 0; kh < K; ++kh) {
                    int ih = oh * stride - padding + kh * dilation;
                    if (ih < 0 || ih >= H_in) continue;
                    for (int kw = 0; kw < K; ++kw) {
                        int iw = ow * stride - padding + kw * dilation;
                        if (iw < 0 || iw >= W_in) continue;

                        // Input index
                        int64_t input_idx = ((((( (int64_t)n * C_in + ic) * D_in + id)
                                             * H_in + ih) * W_in) + iw;

                        // Weight index: (oc, ic - ic_start, kd, kh, kw)
                        int64_t weight_idx = (((((( (int64_t)oc * C_in_per_group
                                                + (ic - ic_start)) * K + kd) * K + kh) * K) + kw);

                        float i_val = __half2float(input[input_idx]);
                        float w_val = __half2float(weight[weight_idx]);
                        acc += i_val * w_val;
                    }
                }
            }
        }

        if (bias != nullptr) {
            acc += __half2float(bias[oc]);
        }

        int64_t out_idx = ((((( (int64_t)n * C_out + oc) * D_out + od) * H_out + oh) * W_out) + ow);
        output[out_idx] = __float2half(acc);
    }
}

//---------------------------------------------------------------
// Wrapper called from Python
//---------------------------------------------------------------
torch::Tensor conv3d_forward(
    torch::Tensor input,   // (N, C_in, D_in, H_in, W_in)   fp16
    torch::Tensor weight,  // (C_out, C_in/groups, K, K, K) fp16
    torch::Tensor bias,    // (C_out) or empty               fp16
    int stride,
    int padding,
    int dilation,
    int groups)
{
    // Ensure contiguous tensors
    input  = input.contiguous();
    weight = weight.contiguous();
    if (bias.defined()) bias = bias.contiguous();

    const int N    = input.size(0);
    const int C_in = input.size(1);
    const int D_in = input.size(2);
    const int H_in = input.size(3);
    const int W_in = input.size(4);

    const int C_out = weight.size(0);
    const int K     = weight.size(2);   // square kernel assumed

    const int D_out = (D_in + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int H_out = (H_in + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int W_out = (W_in + 2 * padding - dilation * (K - 1) - 1) / stride + 1;

    auto options = torch::TensorOptions()
                       .dtype(input.dtype())
                       .device(input.device());

    torch::Tensor output = torch::empty({N, C_out, D_out, H_out, W_out}, options);

    const int threads = 256;
    int64_t total = (int64_t)N * C_out * D_out * H_out * W_out;
    int blocks = (int)((total + threads - 1) / threads);
    if (blocks == 0) blocks = 1;

    const __half* bias_ptr = nullptr;
    if (bias.defined() && bias.numel() > 0) {
        bias_ptr = reinterpret_cast<const __half*>(bias.data_ptr<at::Half>());
    }

    conv3d_kernel<<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(weight.data_ptr<at::Half>()),
        bias_ptr,
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        N, C_in, D_in, H_in, W_in,
        C_out, K, stride, padding, dilation, groups,
        D_out, H_out, W_out);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA error in conv3d_forward: ", cudaGetErrorString(err));
    }
    return output;
}
