#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

#ifndef DIV_UP
#define DIV_UP(a,b) (((a)+(b)-1)/(b))
#endif

// ------------------------------------------------------------------
// Kernel for fp16 convolution (all tensors are half, accumulation in float)
// ------------------------------------------------------------------
__global__ void conv3d_fp16_kernel(
    const __half* __restrict__ input,   // [N, C_in, D_in, H_in, W_in]
    const __half* __restrict__ weight,  // [C_out, C_in/g, K, K, K]
    const __half* __restrict__ bias,    // [C_out] or nullptr
    __half* __restrict__ output,        // [N, C_out, D_out, H_out, W_out]
    int N,
    int C_in,
    int D_in,
    int H_in,
    int W_in,
    int C_out,
    int K,
    int stride,
    int padding,
    int dilation,
    int groups,
    int D_out,
    int H_out,
    int W_out,
    int bias_flag)                         // 1 if bias is present
{
    // total number of output elements
    const long long total = (long long)N * C_out * D_out * H_out * W_out;
    const int ic_per_group = C_in / groups;
    const int oc_per_group = C_out / groups;

    for (long long idx = blockIdx.x * (long long)blockDim.x + threadIdx.x;
         idx < total;
         idx += (long long)gridDim.x * blockDim.x)
    {
        // decode linear index -> (n, oc, d_out, h_out, w_out)
        long long tmp = idx;
        int w_out = tmp % W_out; tmp /= W_out;
        int h_out = tmp % H_out; tmp /= H_out;
        int d_out = tmp % D_out; tmp /= D_out;
        int oc    = tmp % C_out; tmp /= C_out;
        int n     = tmp;                       // batch index

        int group_id = oc / oc_per_group;
        int ic_start = group_id * ic_per_group;
        int ic_end   = ic_start + ic_per_group;
        int ic_local = oc % oc_per_group;      // position of this oc inside its group

        float acc = 0.0f;

        // convolution loops
        for (int ic = ic_start; ic < ic_end; ++ic) {
            int ic_offset = ic - ic_start;      // 0 .. ic_per_group-1
            for (int kd = 0; kd < K; ++kd) {
                int d_in = d_out * stride - padding + kd * dilation;
                if (d_in < 0 || d_in >= D_in) continue;
                for (int kh = 0; kh < K; ++kh) {
                    int h_in = h_out * stride - padding + kh * dilation;
                    if (h_in < 0 || h_in >= H_in) continue;
                    for (int kw = 0; kw < K; ++kw) {
                        int w_in = w_out * stride - padding + kw * dilation;
                        if (w_in < 0 || w_in >= W_in) continue;

                        // flat input index
                        long long input_idx = ((((( (long long)n * C_in + ic) * D_in + d_in)
                                               * H_in + h_in) * W_in) + w_in);

                        // flat weight index: ((oc * ic_per_group + ic_offset) * K + kd) * K + kh) * K + kw
                        long long weight_idx = ((((( (long long)oc * ic_per_group + ic_offset) * K + kd)
                                                * K + kh) * K) + kw);

                        float inp = __half2float(input[input_idx]);
                        float wgt = __half2float(weight[weight_idx]);
                        acc += inp * wgt;
                    }
                }
            }
        }

        if (bias_flag) {
            acc += __half2float(bias[oc]);
        }

        // write output (store as half)
        output[idx] = __float2half(acc);
    }
}

// -----------------------------------------------------------------
// Host wrapper
// -----------------------------------------------------------------
torch::Tensor conv3d_fp16_forward(
    torch::Tensor input,   // [N, C_in, D, H, W]  fp16
    torch::Tensor weight,  // [C_out, C_in/g, K, K, K] fp16
    torch::Tensor bias,    // [C_out] fp16 or undefined
    int stride,
    int padding,
    int dilation,
    int groups)
{
    const int N   = input.size(0);
    const int C_in = input.size(1);
    const int D_in = input.size(2);
    const int H_in = input.size(3);
    const int W_in = input.size(4);

    const int C_out = weight.size(0);
    const int K = weight.size(2); // cubic kernel

    const int D_out = (D_in + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int H_out = (H_in + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int W_out = (W_in + 2 * padding - dilation * (K - 1) - 1) / stride + 1;

    auto output = torch::empty({N, C_out, D_out, H_out, W_out}, input.options());

    const int bias_flag = (bias.defined() && bias.numel() > 0) ? 1 : 0;

    const int threads = 256;
    const long long total = (long long)N * C_out * D_out * H_out * W_out;
    const int blocks = static_cast<int>((total + threads - 1) / threads);

    // launch kernel (all tensors are half)
    conv3d_fp16_kernel<<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(weight.data_ptr<at::Half>()),
        bias_flag ? reinterpret_cast<const __half*>(bias.data_ptr<at::Half>()) : nullptr,
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        N, C_in, D_in, H_in, W_in,
        C_out, K,
        stride, padding, dilation,
        groups,
        D_out, H_out, W_out,
        bias_flag);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel launch failed: ") + cudaGetErrorString(err));
    }
    return output;
}
