class ModelNew(nn.Module):
    """
    Drop‑in replacement for nn.Conv3d using a handcrafted fp16 CUDA kernel.
    Supports square kernels and identical stride/padding/dilation for all spatial dimensions.
    """
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.use_bias = bias

        # weight: (out_channels, in_channels // groups, K, K, K)
        self.weight = nn.Parameter(
            torch.empty(
                out_channels,
                in_channels // groups,
                kernel_size,
                kernel_size,
                kernel_size,
                dtype=torch.float16,
                device="cuda",
            )
        )
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        if bias:
            self.bias = nn.Parameter(
                torch.empty(out_channels, dtype=torch.float16, device="cuda")
            )
            nn.init.zeros_(self.bias)
        else:
            self.register_parameter("bias", None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if x.dtype != torch.float16:
            x = x.to(dtype=torch.float16)
        if not x.is_cuda:
            x = x.cuda()

        bias_tensor = self.bias if self.bias is not None else torch.empty(0, dtype=torch.float16, device=x.device)

        return conv3d_ext.conv3d_fp16_forward(
            x,
            self.weight,
            bias_tensor,
            self.stride,
            self.padding,
            self.dilation,
            self.groups,
        )

