    int output_width,
    int kernel_height,
    int kernel_width,
    int stride_h,
    int stride_w,
    int padding_h,
    int padding_w,
    int groups
) {
    int batch_idx = blockIdx.x;
    int out_ch_idx = blockIdx.y;
    int out_row = blockIdx.z * blockDim.x + threadIdx.x;
    int out_col = threadIdx.y;

    if (out_row >= output_height || out_col >= output_width) return;

    // Each block handles one output channel and batch
    int group_size = out_channels / groups;
    int group_idx = out_ch_idx / group_size;
    int weight_ch_idx = out_ch_idx % group_size;

    // Initialize accumulator
    float acc = 0.0f;

    // Loop over input channels and kernel elements
    for (int in_ch = 0; in_ch < in_channels; ++in_ch) {
        // For grouped convolutions, ensure we're processing the right group
        if (in_ch / (in_channels / groups) != group_idx) continue;

        // Loop over kernel elements
        for (int kh = 0; kh < kernel_height; ++kh) {
            for (int kw = 0; kw < kernel_width; ++kw) {
                // Compute input coordinates
                int input_row = out_row * stride_h - padding_h + kh;
                int input_col = out_col * stride_w - padding_w + kw;

                // Check bounds
                if (input_row >= 0 && input_row < input_height && 
                    input_col >= 0 && input_col < input_width) {

                    // Calculate indices
                    int input_idx = batch_idx * (in_channels * input_height * input_width) +
                                    in_ch * (input_height * input_width) +
                                    input_row * input_width + input_col;

                    int weight_idx = out_ch_idx * (in_channels / groups * kernel_height * kernel_width) +
                                     (in_ch % (in_channels / groups)) * (kernel_height * kernel_width) +
                                     kh * kernel_width + kw;

                    // Perform accumulation
                    float input_val = __half2float(input[input_idx]);
                    float weight_val = __half2float(weight[weight_idx]);
                    acc += input_val * weight_val;
                }
            }
        }
    }

    // Write result
    int output_idx = batch_idx * (out_channels * output_height * output_width) +
                    out_ch_idx * (output_height * output_width) +
                    out_row * output_width + out_col;

