# CUDA source implementing a correct half‑precision ConvTranspose2d
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__device__ __forceinline__ scalar_t atomicAddHalf(scalar_t* address, scalar_t val) {
#if __CUDA_ARCH__ >= 600
    // native half atomicAdd is supported on SM 6.0+
    return atomicAdd(address, val);
#else
    // fallback: accumulate in float (not needed for our target GPU)
    float old = __half2float(*address);
    float new_val;
    do {
        new_val = old + __half2float(val);
    } while (atomicCAS((int*)address, __float2int_rn(old), __float2int_rn(new_val)) != __float2int_rn(old));
    return __float2half(old);
#endif
}

// Kernel: each thread processes one input element and scatters its contributions
__global__ void conv_transpose2d_forward(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    __half* __restrict__ output,
    int N, int C_in, int H_in, int W_in,
    int C_out, int H_out, int W_out,
    int K, int stride, int padding,
    int groups)
{
    const int C_out_per_group = C_out / groups;
    const int C_in_per_group  = C_in  / groups;
    const int total = N * C_in * H_in * W_in;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride_grid = gridDim.x * blockDim.x;

    for (; idx < total; idx += stride_grid) {
        int tmp = idx;
        int w_in = tmp % W_in;   tmp /= W_in;
        int h_in = tmp % H_in;   tmp /= H_in;
        int ic   = tmp % C_in;   tmp /= C_in;
        int n    = tmp;

        // input value as float for higher‑precision multiply
        float i_val = __half2float(input[idx]);

        // group handling
        int g = ic / C_in_per_group;
        int ic_in_group = ic % C_in_per_group;
        int out_c_base = g * C_out_per_group;

        // base output coordinates (center of the kernel window)
        int out_h_base = h_in * stride - padding;
        int out_w_base = w_in * stride - padding;

        // iterate over kernel spatial dimensions
        for (int kh = 0; kh < K; ++kh) {
            int out_h = out_h_base + kh;
            if (out_h < 0 || out_h >= H_out) continue;

            for (int kw = 0; kw < K; ++kw) {
                int out_w = out_w_base + kw;
                if (out_w < 0 || out_w >= W_out) continue;

                // compute output offset for the first output channel of this group
                int out_offset = ((n * C_out + out_c_base) * H_out + out_h) * W_out + out_w;

                // accumulate over all output channels in the group
                for (int ocg = 0; ocg < C_out_per_group; ++ocg) {
                    // weight index: (ic, ocg, kh, kw) in row‑major order
                    int w_idx = ((ic * C_out_per_group + ocg) * K + kh) * K + kw;
                    float w_val = __half2float(weight[w_idx]);

                    float prod = i_val * w_val;
                    // atomic add into half‑precision output
                    atomicAddHalf(&output[out_offset + ocg * H_out * W_out],
                                  __float2half(prod));
                }
            }
        }
    }
}

// Simple bias addition (no atomics needed)
__global__ void add_bias_kernel(
    __half* __restrict__ output,
    const __half* __restrict__ bias,
    int N, int C_out, int H_out, int W_out)
{
    int total = N * C_out * H_out * W_out;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride_grid = gridDim.x * blockDim.x;

    for (; idx < total; idx += stride_grid) {
        int tmp = idx;
        int w = tmp % W_out;   tmp /= W_out;
        int h = tmp % H_out;   tmp /= H_out;
        int c = tmp % C_out;   // tmp now holds batch index (unused)
        __half b = bias[c];
        output[idx] = __hadd(output[idx], b);
    }
}

// Wrapper called from Python
torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int groups)
{
    // ensure contiguous half tensors
    input = input.contiguous();
    weight = weight.contiguous();
    bool has_bias = bias.defined() && bias.numel() > 0;
    if (has_bias) bias = bias.contiguous();

    const int N   = input.size(0);
    const int C_in = input.size(1);
    const int H_in = input.size(2);
    const int W_in = input.size(3);

    const int K = weight.size(2);          // square kernel
    const int C_out_per_group = weight.size(1);
    const int C_out = C_out_per_group * groups;

    const int H_out = (H_in - 1) * stride - 2 * padding + K;
    const int W_out = (W_in - 1) * stride - 2 * padding + K;

    auto options = input.options();
    // zero‑initialize output before atomic accumulation
    torch::Tensor output = torch::zeros({N, C_out, H_out, W_out}, options);

    const int total_in = N * C_in * H_in * W_in;
    const int block = 256;
    const int grid = (total_in + block - 1) / block;

    conv_transpose2d_forward<<<grid, block>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(weight.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        N, C_in, H_in, W_in,
        C_out, H_out, W_out,
        K, stride, padding,
        groups);
    cudaGetLastError();

    if (has_bias) {
        const int total_out = N * C_out * H_out * W_out;
        const int grid2 = (total_out + block - 1) / block;
        add_bias_kernel<<<grid2, block>>>(
            reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
            reinterpret_cast<const __half*>(bias.data_ptr<at::Half>()),
            N, C_out, H_out, W_out);
        cudaGetLastError();
    }

    return output;
}
