#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void conv_transpose2d_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    int N,
    int C_in,
    int H_in,
    int W_in,
    int C_out,
    int K,
    int stride,
    int padding,
    int output_padding,
    int groups,
    int H_out,
    int W_out)
{
    // total number of output elements
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C_out * H_out * W_out;
    if (idx >= total) return;

    // decode linear index to N, C_out, y, x
    int tmp = idx;
    int x_out = tmp % W_out;   tmp /= W_out;
    int y_out = tmp % H_out;   tmp /= H_out;
    int oc    = tmp % C_out;   int n = tmp / C_out;

    // bias contribution (if any)
    float acc = 0.0f;
    if (bias != nullptr) {
        acc = __half2float(bias[oc]);
    }

    // group handling
    int oc_per_group = C_out / groups;
    int ic_per_group = C_in / groups;
    int group_id = oc / oc_per_group;
    int oc_in_group = oc - group_id * oc_per_group;
    int ic_start = group_id * ic_per_group;

    // loop over input channels belonging to this group
    for (int ic = ic_start; ic < ic_start + ic_per_group; ++ic) {
        // loop over kernel spatial dimensions
        for (int ky = 0; ky < K; ++ky) {
            int y_in = y_out + padding - ky;
            if (y_in % stride != 0) continue;
            y_in = y_in / stride;
            if (y_in < 0 || y_in >= H_in) continue;

            for (int kx = 0; kx < K; ++kx) {
                int x_in = x_out + padding - kx;
                if (x_in % stride != 0) continue;
                x_in = x_in / stride;
                if (x_in < 0 || x_in >= W_in) continue;

                // weight layout: (C_in, C_out_per_group, K, K)
                int w_idx = ((ic * oc_per_group + oc_in_group) * K + ky) * K + kx;
                int in_idx = ((n * C_in + ic) * H_in + y_in) * W_in + x_in;

                float w = __half2float(weight[w_idx]);
                float i = __half2float(input[in_idx]);
                acc += i * w;
            }
        }
    }

    output[idx] = __float2half(acc);
}

