#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

// ---------------------------------------------------------------
// Forward kernel: scatter from input to output using atomicAdd on float accumulator
// ---------------------------------------------------------------
__global__ void conv_transpose2d_fp16_scatter_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    float* __restrict__ acc,
    const int N,
    const int C_in,
    const int C_out,
    const int H,
    const int W,
    const int H_out,
    const int W_out,
    const int K,
    const int stride,
    const int padding,
    const int groups)
{
    const int total_in = N * C_in * H * W;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride_grid = gridDim.x * blockDim.x;

    const int C_in_per_group  = C_in / groups;
    const int C_out_per_group = C_out / groups;

    for (; idx < total_in; idx += stride_grid) {
        // decode linear index to (n, c_in, h_in, w_in)
        int tmp = idx;
        int w_in = tmp % W;      tmp /= W;
        int h_in = tmp % H;      tmp /= H;
        int c_in = tmp % C_in;   tmp /= C_in;
        int n    = tmp;

        // group for this input channel
        int group = c_in / C_in_per_group;
        int c_in_in_grp = c_in % C_in_per_group;   // not used further

        // base output channel index for this group
        int c_out_base = group * C_out_per_group;

        // load input value once
        float in_f = __half2float(input[idx]);

        // iterate over kernel spatial positions
        for (int kh = 0; kh < K; ++kh) {
            int h_out = h_in * stride - padding + kh;
            if (h_out < 0 || h_out >= H_out) continue;

            for (int kw = 0; kw < K; ++kw) {
                int w_out = w_in * stride - padding + kw;
                if (w_out < 0 || w_out >= W_out) continue;

                // for each output channel in this group
                for (int c_out_rel = 0; c_out_rel < C_out_per_group; ++c_out_rel) {
                    int c_out = c_out_base + c_out_rel;

                    // weight index: (c_in, c_out_rel, kh, kw)
                    int w_idx = (((c_in * C_out_per_group) + c_out_rel) * K + kh) * K + kw;
                    float w_f = __half2float(weight[w_idx]);

                    // linear output index
                    int out_idx = (((n * C_out + c_out) * H_out + h_out) * W_out + w_out);

                    // atomic accumulation
                    atomicAdd(&acc[out_idx], in_f * w_f);
                }
            }
        }
    }
}

// ---------------------------------------------------------------
// Cast float accumulator to half output
// ---------------------------------------------------------------
__global__ void cast_fp32_to_fp16_kernel(
    const float* __restrict__ src,
    __half* __restrict__ dst,
    int total)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = gridDim.x * blockDim.x;
    for (; i < total; i += stride) {
        dst[i] = __float2half(src[i]);
    }
}

// ---------------------------------------------------------------
// Optional bias addition (half)
// ---------------------------------------------------------------
__global__ void bias_add_fp16_kernel(
    __half* __restrict__ output,
    const __half* __restrict__ bias,
    int total,
    int C_out,
    int H_out,
    int W_out)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = gridDim.x * blockDim.x;
    for (; i < total; i += stride) {
        int tmp = i;
        int w = tmp % W_out;  tmp /= W_out;
        int h = tmp % H_out;  tmp /= H_out;
        int c = tmp % C_out;  // channel index
        // n = tmp / C_out (unused)

        __half out_val = output[i];
        __half b = bias[c];
        output[i] = __hadd(out_val, b);
    }
}

