    int oc_per_group = out_channels / groups;
    int ic_per_group = in_channels  / groups;
    int group = oc / oc_per_group;
    int ic_start = group * ic_per_group;
    int ic_end   = ic_start + ic_per_group;

    float acc = 0.0f;

    // iterate over contributing input channels and kernel positions
    for (int ic = ic_start; ic < ic_end; ++ic) {
        for (int kh = 0; kh < kernel_h; ++kh) {
            // position of the input that maps to this output via this kernel row
            int ih_tmp = oh + padding - kh;
            if (ih_tmp % stride != 0) continue;
            int ih = ih_tmp / stride;
            if (ih < 0 || ih >= in_h) continue;

            for (int kw = 0; kw < kernel_w; ++kw) {
                int iw_tmp = ow + padding - kw;
                if (iw_tmp % stride != 0) continue;
                int iw = iw_tmp / stride;
                if (iw < 0 || iw >= in_w) continue;

                // input index: (N, C_in, H_in, W_in)
                int input_idx = ((n * in_channels + ic) * in_h + ih) * in_w + iw;

                // weight index with 180° flip (as required by transposed conv)
                int kh_f = kernel_h - 1 - kh;
                int kw_f = kernel_w - 1 - kw;
                // weight layout: (C_in, C_out_per_group, K_h, K_w)
                int weight_idx = ((ic * oc_per_group + (oc % oc_per_group)) * kernel_h + kh_f) * kernel_w + kw_f;

                acc += __half2float(input[input_idx]) * __half2float(weight[weight_idx]);
            }
        }
    }

    if (bias_defined) {
        acc += __half2float(bias[oc]);
    }

    // output index: (N, C_out, H_out, W_out)
    int out_idx = ((n * out_channels + oc) * out_h + oh) * out_w + ow;
    output[out_idx] = __float2half(acc);
}

torch::Tensor conv_transpose2d_fast(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride,
    int64_t padding,
    int64_t output_padding,
    int64_t groups)
{
