    input = input.contiguous().to(at::kHalf);
    weight = weight.contiguous().to(at::kHalf);
    if (bias.defined()) bias = bias.contiguous().to(at::kHalf);

    const int batch      = input.size(0);
    const int in_c       = input.size(1);
    const int in_h       = input.size(2);
    const int in_w       = input.size(3);
    const int k_h        = weight.size(2);
    const int k_w        = weight.size(3);
    const int stride_i   = static_cast<int>(stride);
    const int padding_i  = static_cast<int>(padding);
    const int outpad_i   = static_cast<int>(output_padding);
    const int groups_i   = static_cast<int>(groups);

    const int out_c = weight.size(1) * groups_i; // total output channels
    const int out_h = (in_h - 1) * stride_i - 2 * padding_i + k_h + outpad_i;
    const int out_w = (in_w - 1) * stride_i - 2 * padding_i + k_w + outpad_i;

    auto options = input.options();
    torch::Tensor output = torch::empty({batch, out_c, out_h, out_w}, options);

    const dim3 block(16, 16);
    const dim3 grid(
        (out_w + block.x - 1) / block.x,
        (out_h + block.y - 1) / block.y,
        batch * out_c
    );

    const __half* input_ptr  = reinterpret_cast<const __half*>(input.data_ptr<at::Half>());
    const __half* weight_ptr = reinterpret_cast<const __half*>(weight.data_ptr<at::Half>());
    const __half* bias_ptr   = nullptr;
    bool bias_defined = false;
    if (bias.defined() && bias.numel() > 0) {
        bias_ptr = reinterpret_cast<const __half*>(bias.data_ptr<at::Half>());
        bias_defined = true;
    }
    __half* output_ptr = reinterpret_cast<__half*>(output.data_ptr<at::Half>());

    conv_transpose2d_kernel<<<grid, block>>>(
        input_ptr,
        weight_ptr,
        bias_ptr,
        output_ptr,
        batch,
        in_c,
        in_h,
        in_w,
        out_c,
        out_h,
        out_w,
        k_h,
        k_w,
        stride_i,
        padding_i,
        groups_i,
        bias_defined
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel launch error: ") + cudaGetErrorString(err));
