cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void conv_transpose2d_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    int N,
    int C_in,
    int H_in,
    int W_in,
    int C_out,
    int H_out,
    int W_out,
    int K_h,
    int K_w,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int groups,
    int has_bias)               // 0/1 instead of bool for kernel compatibility
{
    const int total = N * C_out * H_out * W_out;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (int linear = idx; linear < total; linear += stride) {
        // ---- decode linear index into (n, oc, h_out, w_out) ----
        int w_out = linear % W_out;
        int tmp = linear / W_out;
        int h_out = tmp % H_out;
        tmp = tmp / H_out;
        int oc = tmp % C_out;
        int n = tmp / C_out;

        // ---- group handling ----
        int channels_per_group = C_in / groups;
        int out_per_group = C_out / groups;
        int g = oc / out_per_group;                // group index
        int oc_local = oc % out_per_group;          // output channel inside group
        int ic_start = g * channels_per_group;
        int ic_end   = ic_start + channels_per_group;

        float acc = 0.0f;

        // ---- iterate over kernel spatial dimensions ----
        for (int ky = 0; ky < K_h; ++ky) {
            int ih_numer = h_out + pad_h - ky;
            if (ih_numer % stride_h != 0) continue;
            int ih = ih_numer / stride_h;
            if (ih < 0 || ih >= H_in) continue;

            for (int kx = 0; kx < K_w; ++kx) {
                int iw_numer = w_out + pad_w - kx;
                if (iw_numer % stride_w != 0) continue;
                int iw = iw_numer / stride_w;
                if (iw < 0 || iw >= W_in) continue;

                // ---- accumulate over input channels in this group ----
                for (int ic = ic_start; ic < ic_end; ++ic) {
                    // input value
                    int inp_idx = ((n * C_in + ic) * H_in + ih) * W_in + iw;
                    __half inp_h = input[inp_idx];

                    // weight value: (C_in, C_out/groups, K_h, K_w)
                    int w_idx = (((ic * out_per_group) + oc_local) * K_h + ky) * K_w + kx;
                    __half w_h = weight[w_idx];

                    acc += __half2float(inp_h) * __half2float(w_h);
                }
            }
        }

        // ---- bias ----
        if (has_bias) {
            acc += __half2float(bias[oc]);
        }

        // ---- write output ----
        int out_idx = ((n * C_out + oc) * H_out + h_out) * W_out + w_out;
        output[out_idx] = __float2half(acc);
    }
}

