// C++ wrapper
// ------------------------------------------------------------------------
torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int groups)
{
    // Ensure contiguous half tensors
    input = input.contiguous();
    weight = weight.contiguous();
    if (bias.defined()) bias = bias.contiguous();

    const int N   = input.size(0);
    const int C_in = input.size(1);
    const int H_in = input.size(2);
    const int W_in = input.size(3);

    const int C_out = weight.size(1) * groups;   // weight: (C_in, C_out/groups, kH, kW)
    const int K_h   = weight.size(2);
    const int K_w   = weight.size(3);

    const int stride_h = stride;
    const int stride_w = stride;
    const int pad_h    = padding;
    const int pad_w    = padding;

    const int H_out = (H_in - 1) * stride_h - 2 * pad_h + K_h + output_padding;
    const int W_out = (W_in - 1) * stride_w - 2 * pad_w + K_w + output_padding;

    auto options = input.options();
    torch::Tensor output = torch::empty({N, C_out, H_out, W_out}, options);

    const int threads = 256;
    const int total   = N * C_out * H_out * W_out;
    const int blocks  = (total + threads - 1) / threads;

    const __half* bias_ptr = nullptr;
    int has_bias = 0;
    if (bias.defined() && bias.numel() > 0) {
        bias_ptr = reinterpret_cast<const __half*>(bias.data_ptr<at::Half>());
        has_bias = 1;
    }

    conv_transpose2d_kernel<<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(weight.data_ptr<at::Half>()),
        bias_ptr,
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        N, C_in, H_in, W_in,
        C_out, H_out, W_out,
        K_h, K_w,
        stride_h, stride_w,
        pad_h, pad_w,
        groups,
        has_bias
    );

    // synchronize to surface any launch errors
    cudaDeviceSynchronize();

    return output;
