    if (batch_idx >= batch_size || channel_idx >= in_channels) return;

    int tid = threadIdx.x;
    int total_elements = out_h * out_w;

    // Each thread handles multiple output elements
    for (int elem_idx = tid; elem_idx < total_elements; elem_idx += blockDim.x) {
        int out_y = elem_idx / out_w;
        int out_x = elem_idx % out_w;

        float sum = 0.0f;

        // Apply kernel
        for (int ky = 0; ky < kernel_h; ky++) {
            for (int kx = 0; kx < kernel_w; kx++) {
