cuda_source = r"""
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

#ifndef TILE_W
#define TILE_W 16
#endif
#ifndef TILE_H
#define TILE_H 16
#endif

// one block processes a TILE_W×TILE_H patch of the output for a
// single (batch, channel) image.
__global__ void depthwise_conv2d_tiled_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    const int batch,
    const int channels,
    const int in_h,
    const int in_w,
    const int out_h,
    const int out_w,
    const int k,
    const int stride,
    const int padding)
{
    // ------------------------------------------------------------------
    // identify which image (batch * channel) this block works on
    // ------------------------------------------------------------------
    const int img_idx = blockIdx.z;                 // 0 .. batch*channels-1
    const int b = img_idx / channels;
    const int c = img_idx % channels;

    // ------------------------------------------------------------------
    // output coordinates for this thread
    // ------------------------------------------------------------------
    const int ow = blockIdx.x * TILE_W + threadIdx.x;   // width index
    const int oh = blockIdx.y * TILE_H + threadIdx.y;   // height index

    // ------------------------------------------------------------------
    // shared memory for input tile (includes halo for kernel)
    // ------------------------------------------------------------------
    const int sm_w = TILE_W + k - 1;
    const int sm_h = TILE_H + k - 1;
    extern __shared__ __half smem[];   // size = sm_w * sm_h * sizeof(__half)

    // starting top‑left coordinate of the input region that maps to
    // the top‑left output element of this tile
    const int h_start = blockIdx.y * TILE_H * stride - padding;
    const int w_start = blockIdx.x * TILE_W * stride - padding;

    // ------------------------------------------------------------------
    // load input tile into shared memory (grid‑stride within the tile)
    // ------------------------------------------------------------------
    for (int y = threadIdx.y; y < sm_h; y += blockDim.y) {
        int in_y = h_start + y;
        for (int x = threadIdx.x; x < sm_w; x += blockDim.x) {
            int in_x = w_start + x;
            __half val = __float2half(0.0f);
            if (in_y >= 0 && in_y < in_h && in_x >= 0 && in_x < in_w) {
                const int in_idx = (((b * channels + c) * in_h) + in_y) * in_w + in_x;
                val = input[in_idx];
            }
            smem[y * sm_w + x] = val;
        }
    }
    __syncthreads();

    // ------------------------------------------------------------------
    // compute convolution for the thread's output element (if inside bounds)
    // ------------------------------------------------------------------
    if (ow < out_w && oh < out_h) {
        float acc = 0.0f;
        const int sm_y = threadIdx.y * stride;
        const int sm_x = threadIdx.x * stride;

        for (int ky = 0; ky < k; ++ky) {
            const int base_y = sm_y + ky;
            for (int kx = 0; kx < k; ++kx) {
                const int base_x = sm_x + kx;
                __half i = smem[base_y * sm_w + base_x];
                const int w_idx = (c * k + ky) * k + kx;
                __half w = weight[w_idx];
                acc += __half2float(i) * __half2float(w);
            }
        }
        if (bias != nullptr) {
            acc += __half2float(bias[c]);
        }
        const int out_idx = (((b * channels + c) * out_h) + oh) * out_w + ow;
        output[out_idx] = __float2half(acc);
    }
}

// ------------------------------------------------------------------
// Python‑visible wrapper
// ------------------------------------------------------------------
torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    const int stride,
    const int padding)
{
    const int batch    = input.size(0);
    const int channels = input.size(1);
    const int in_h     = input.size(2);
    const int in_w     = input.size(3);
    const int k        = weight.size(2); // square kernel

    const int out_h = (in_h + 2 * padding - k) / stride + 1;
    const int out_w = (in_w + 2 * padding - k) / stride + 1;

    auto output = torch::empty({batch, channels, out_h, out_w}, input.options());

    const __half* input_ptr  = reinterpret_cast<const __half*>(input.data_ptr<at::Half>());
    const __half* weight_ptr = reinterpret_cast<const __half*>(weight.data_ptr<at::Half>());
    const __half* bias_ptr   = (bias.defined() && bias.numel() > 0)
                               ? reinterpret_cast<const __half*>(bias.data_ptr<at::Half>())
                               : nullptr;
    __half* output_ptr = reinterpret_cast<__half*>(output.data_ptr<at::Half>());

    const dim3 block(TILE_W, TILE_H);
    const dim3 grid(
        (out_w + TILE_W - 1) / TILE_W,
        (out_h + TILE_H - 1) / TILE_H,
        batch * channels
    );

    const size_t shared_bytes = (TILE_W + k - 1) * (TILE_H + k - 1) * sizeof(__half);

    depthwise_conv2d_tiled_kernel<<<grid, block, shared_bytes>>>(
        input_ptr, weight_ptr, bias_ptr, output_ptr,
        batch, channels, in_h, in_w, out_h, out_w,
        k, stride, padding);
    return output;
}
