    const int bc_idx = blockIdx.z;
    const int b = bc_idx / channels;
    const int c = bc_idx % channels;

    // top‑left corner of the output tile this block computes
    const int out_y0 = blockIdx.y * TILE_H;
    const int out_x0 = blockIdx.x * TILE_W;

    // -------------------------------------------------------------
    // shared memory for the input patch needed by this tile
    // size = (TILE_H + K - 1) × (TILE_W + K - 1)
    // -------------------------------------------------------------
    extern __shared__ __half shmem[];
    const int sh_h = TILE_H + K - 1;
    const int sh_w = TILE_W + K - 1;
