// Kernel: one block processes one (batch, channel) pair.
// Tiles input into shared memory (including halo) and computes
// output elements with stride‑aware addressing.
// ---------------------------------------------------------------
extern "C" __global__
void depthwise_conv2d_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    int N, int C,
    int H, int W,
    int K, int stride, int padding,
    int H_out, int W_out,
