    // Output coordinates for this thread
    // -----------------------------------------------------------
    int out_x = blockIdx.x * blockDim.x + threadIdx.x;   // width idx
    int out_y = blockIdx.y * blockDim.y + threadIdx.y;   // height idx
    if (out_x >= W_out || out_y >= H_out) return;

    // -----------------------------------------------------------
    // Shared‑memory tile dimensions (include halo for kernel)
    // -----------------------------------------------------------
    const int TILE_X = blockDim.x;
    const int TILE_Y = blockDim.y;

    const int SHARED_W = TILE_X * stride + K - 1;   // width of shared tile
    const int SHARED_H = TILE_Y * stride + K - 1;   // height of shared tile

    extern __shared__ __half shmem[];               // size = SHARED_W*SHARED_H

    // -----------------------------------------------------------
    // Compute the top‑left corner (in input coordinates) of the tile
    // -----------------------------------------------------------
    int in_x_origin = blockIdx.x * TILE_X * stride - padding;
    int in_y_origin = blockIdx.y * TILE_Y * stride - padding;

    // -----------------------------------------------------------
    // Load input patch (with zero padding) into shared memory
    // Each thread may load multiple elements via a strided loop.
    // -----------------------------------------------------------
    for (int dy = threadIdx.y; dy < SHARED_H; dy += blockDim.y) {
        int in_y = in_y_origin + dy;
        for (int dx = threadIdx.x; dx < SHARED_W; dx += blockDim.x) {
