    // Load kernel weights for this channel into registers (K*K values)
    // -----------------------------------------------------------
    const __half* w_ptr = weight + c * K * K;
    // Unroll weight loading for typical small K (e.g., 3,5)
    __half w_reg[25];                // max K we anticipate =5 (25 elems)
#pragma unroll
    for (int i = 0; i < K*K; ++i) {
        w_reg[i] = w_ptr[i];
    }

    // -----------------------------------------------------------
    // Compute convolution for the output element handled by this thread
    // -----------------------------------------------------------
    float acc = has_bias ? __half2float(bias[c]) : 0.0f;

    int base_y = threadIdx.y * stride;
    int base_x = threadIdx.x * stride;

