#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void depthwise_conv2d_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,   // may be nullptr
    __half* __restrict__ output,
    int N, int C, int H, int W,
    int K, int stride, int padding,
    int H_out, int W_out)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * H_out * W_out;
    int stride_grid = gridDim.x * blockDim.x;

    for (; idx < total; idx += stride_grid) {
        // decode linear index
        int n = idx / (C * H_out * W_out);
        int rem = idx % (C * H_out * W_out);
        int c = rem / (H_out * W_out);
        int hw = rem % (H_out * W_out);
        int h_out = hw / W_out;
        int w_out = hw % W_out;

        int h_start = h_out * stride - padding;
        int w_start = w_out * stride - padding;

        float acc = 0.0f;
        // loop over kernel
        for (int kh = 0; kh < K; ++kh) {
            int h_in = h_start + kh;
            if (h_in < 0 || h_in >= H) continue;
            for (int kw = 0; kw < K; ++kw) {
                int w_in = w_start + kw;
                if (w_in < 0 || w_in >= W) continue;
                // compute flat indices
                int in_idx = ((n * C + c) * H + h_in) * W + w_in;
                int w_idx  = ((c * 1 + 0) * K + kh) * K + kw; // weight shape (C,1,K,K)

                __half i_val = input[in_idx];
                __half w_val = weight[w_idx];
                acc += __half2float(i_val) * __half2float(w_val);
            }
        }
        // add bias if present
        if (bias != nullptr) {
            acc += __half2float(bias[c]);
        }
        // write output
        int out_idx = ((n * C + c) * H_out + h_out) * W_out + w_out;
        output[out_idx] = __float2half(acc);
    }
}

torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,          // (N, C, H, W) fp16
    torch::Tensor weight,         // (C, 1, K, K) fp16
    torch::Tensor bias,           // (C) fp16 or empty
    int64_t stride,
    int64_t padding)
{
    TORCH_CHECK(input.is_cuda() && weight.is_cuda(),
        "input and weight must be CUDA tensors");
    TORCH_CHECK(input.is_contiguous() && weight.is_contiguous(),
        "input and weight must be contiguous");
    TORCH_CHECK(input.scalar_type() == torch::kFloat16 &&
                weight.scalar_type() == torch::kFloat16,
        "input and weight must be fp16");

    if (bias.defined() && bias.numel() > 0) {
        TORCH_CHECK(bias.is_cuda() && bias.is_contiguous(),
            "bias must be CUDA and contiguous");
        TORCH_CHECK(bias.scalar_type() == torch::kFloat16,
            "bias must be fp16");
        TORCH_CHECK(bias.dim() == 1 && bias.size(0) == input.size(1),
            "bias shape mismatch");
    }

    const int N = input.size(0);
    const int C = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);
    const int K = weight.size(2); // assume square kernel
    const int s = static_cast<int>(stride);
    const int p = static_cast<int>(padding);

    const int H_out = (H + 2 * p - K) / s + 1;
    const int W_out = (W + 2 * p - K) / s + 1;

    auto options = input.options();
    torch::Tensor output = torch::empty({N, C, H_out, W_out}, options);

    const int threads = 256;
    const int total = N * C * H_out * W_out;
    const int blocks = (total + threads - 1) / threads;

    // bias pointer handling
    const __half* bias_ptr = nullptr;
    if (bias.defined() && bias.numel() > 0) {
        bias_ptr = bias.data_ptr<at::Half>();
    }

