cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef TILE_H
#define TILE_H 16
#endif
#ifndef TILE_W
#define TILE_W 16
#endif

template <bool HAS_BIAS>
__global__ void depthwise_conv_kernel_tiled(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    const int B, const int C,
    const int H, const int W,
    const int K,
    const int stride,
    const int padding,
    const int H_out,
    const int W_out) {

    // each block processes one (batch, channel) pair
    const int bc = blockIdx.z;
    const int b = bc / C;
    const int c = bc % C;

    const int out_x0 = blockIdx.x * TILE_W;
    const int out_y0 = blockIdx.y * TILE_H;

    // shared memory tile holds the input region needed for this output tile
    // dimensions: (TILE_H*stride + K - 1) x (TILE_W*stride + K - 1)
    const int SH_H = TILE_H * stride + K - 1;
    const int SH_W = TILE_W * stride + K - 1;
    extern __shared__ __half shmem[];

    // ------------------------------------------------------------------
    // Load input patch into shared memory (grid‑stride loop for coverage)
    // ------------------------------------------------------------------
    for (int sy = threadIdx.y; sy < SH_H; sy += blockDim.y) {
        for (int sx = threadIdx.x; sx < SH_W; sx += blockDim.x) {
            const int in_y = out_y0 * stride - padding + sy;
            const int in_x = out_x0 * stride - padding + sx;
            __half val = __float2half(0.0f);
            if (in_y >= 0 && in_y < H && in_x >= 0 && in_x < W) {
                const int64_t in_idx = ((int64_t)b * C + c) * H * W
                                     + (int64_t)in_y * W + in_x;
                val = input[in_idx];
            }
            shmem[sy * SH_W + sx] = val;
        }
    }

    __syncthreads();

    // ------------------------------------------------------------------
    // Compute output elements that fall inside the tile
    // ------------------------------------------------------------------
    const int out_x = out_x0 + threadIdx.x;
    const int out_y = out_y0 + threadIdx.y;
    if (out_x < W_out && out_y < H_out) {
        // load kernel weights for this channel into registers (K*K)
        __half kdata[64];          // support up to K=8 (8*8=64)
        #pragma unroll
        for (int i = 0; i < K * K; ++i) {
            kdata[i] = weight[(int64_t)c * K * K + i];
        }

        float acc = 0.0f;
        #pragma unroll
        for (int ky = 0; ky < K; ++ky) {
            const int sh_y = threadIdx.y * stride + ky;
            #pragma unroll
            for (int kx = 0; kx < K; ++kx) {
                const int sh_x = threadIdx.x * stride + kx;
                __half h_in = shmem[sh_y * SH_W + sh_x];
                __half h_w  = kdata[ky * K + kx];
                acc += __half2float(h_in) * __half2float(h_w);
            }
        }

        if (HAS_BIAS) {
            acc += __half2float(bias[c]);
        }

        const int64_t out_idx = ((int64_t)b * C + c) * H_out * W_out
                              + (int64_t)out_y * W_out + out_x;
        output[out_idx] = __float2half(acc);
    }
}

// ----------------------------------------------------------------------
// C++ wrapper
// ----------------------------------------------------------------------
torch::Tensor depthwise_conv_forward_tiled(
        torch::Tensor input,
        torch::Tensor weight,
        torch::Tensor bias,
        int stride,
        int padding,
        bool has_bias) {

    const int B = input.size(0);
    const int C = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);
    const int K = weight.size(2);          // (C, K, K)

    const int H_out = (H + 2 * padding - K) / stride + 1;
    const int W_out = (W + 2 * padding - K) / stride + 1;

    auto output = torch::empty({B, C, H_out, W_out}, input.options());

    const dim3 block(TILE_W, TILE_H);
    const dim3 grid( (W_out + TILE_W - 1) / TILE_W,
                     (H_out + TILE_H - 1) / TILE_H,
                     B * C );

    const size_t shmem_bytes = (TILE_H * stride + K - 1) *
                               (TILE_W * stride + K - 1) *
                               sizeof(__half);

    if (has_bias) {
        depthwise_conv_kernel_tiled<true><<<grid, block, shmem_bytes>>>(
            reinterpret_cast<const __half*>(input.data_ptr()),
            reinterpret_cast<const __half*>(weight.data_ptr()),
            reinterpret_cast<const __half*>(bias.data_ptr()),
            reinterpret_cast<__half*>(output.data_ptr()),
            B, C, H, W, K, stride, padding, H_out, W_out);
    } else {
        depthwise_conv_kernel_tiled<false><<<grid, block, shmem_bytes>>>(
            reinterpret_cast<const __half*>(input.data_ptr()),
            reinterpret_cast<const __half*>(weight.data_ptr()),
            nullptr,
            reinterpret_cast<__half*>(output.data_ptr()),
            B, C, H, W, K, stride, padding, H_out, W_out);
    }

    return output;
}
