# CUDA source: half‑precision inclusive cumulative sum along an arbitrary dimension
# ----------------------------------------------------------------------
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <ATen/cuda/CUDAContext.h>

#ifndef CHECK
#define CHECK(x) TORCH_CHECK(x, #x)
#endif

// ------------------------------------------------------------------
// Kernel
// ------------------------------------------------------------------
// in  : [rows, len]   (row‑major, contiguous)
// out : [rows, len]   same layout
// Each thread processes one row (grid‑stride over rows)
__global__ void cumsum_kernel(const __half* __restrict__ in,
                              __half* __restrict__ out,
                              int64_t rows,
                              int64_t len) {
    int64_t tid   = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = gridDim.x * blockDim.x;

    for (int64_t r = tid; r < rows; r += stride) {
        const __half* in_row  = in  + r * len;
        __half*       out_row = out + r * len;

        float acc = 0.0f;                     // accumulate in fp32 for precision
        #pragma unroll 4
        for (int64_t i = 0; i < len; ++i) {
            acc += __half2float(in_row[i]);   // convert half -> float, add
            out_row[i] = __float2half(acc);   // store back as half
        }
    }
}

// ------------------------------------------------------------------
// Wrapper
// ------------------------------------------------------------------
torch::Tensor cumsum_cuda(torch::Tensor input, int64_t dim) {
    CHECK(input.is_cuda());
    CHECK(input.is_contiguous());
    CHECK(input.dtype() == torch::kFloat16);

    // --------------------------------------------------------------
    // Normalise dim (allow negative) and move it to the last axis
    // --------------------------------------------------------------
    const int64_t ndims = input.dim();
    int64_t dim_adj = dim >= 0 ? dim : dim + ndims;
    CHECK(dim_adj >= 0 && dim_adj < ndims);

    // permutation that brings the target dim to the end
    std::vector<int64_t> perm;
    perm.reserve(ndims);
    for (int64_t i = 0; i < ndims; ++i) {
        if (i != dim_adj) perm.push_back(i);
