    int head_idx = blockIdx.y;

    if (batch_idx >= batch_size || head_idx >= num_heads) return;

    const int stride_q = seq_len * embed_dim;
    const int stride_k = seq_len * embed_dim;
    const int stride_v = seq_len * embed_dim;
    const int stride_out = seq_len * embed_dim;

    const __half* q = Q + batch_idx * stride_q + head_idx * seq_len * embed_dim;
    const __half* k = K + batch_idx * stride_k + head_idx * seq_len * embed_dim;
    const __half* v = V + batch_idx * stride_v + head_idx * seq_len * embed_dim;
    __half* out = Out + batch_idx * stride_out + head_idx * seq_len * embed_dim;

    const float scale = 1.0f / sqrtf(static_cast<float>(embed_dim));

    const int block_size = 16;
    __shared__ float s_q[block_size][block_size];
    __shared__ float s_k[block_size][block_size];
    __shared__ float s_v[block_size][block_size];
    __shared__ float s_att[block_size][block_size];

    for (int i = 0; i < seq_len; i += block_size) {
        for (int j = 0; j < seq_len; j += block_size) {
            // Load Q block
            int tid = threadIdx.x;
            if (i + tid < seq_len && threadIdx.y < embed_dim) {
                s_q[threadIdx.y][tid] = __half2float(q[(i + tid) * embed_dim + threadIdx.y]);
