            sum *= scale;
            s_att[threadIdx.y][threadIdx.x] = sum;

            __syncthreads();

            // Apply softmax
            float max_val = -1e30f;
            for (int l = 0; l < block_size; ++l) {
                max_val = fmaxf(max_val, s_att[l][threadIdx.x]);
            }

            float sum_exp = 0.0f;
            for (int l = 0; l < block_size; ++l) {
                s_att[l][threadIdx.x] = expf(s_att[l][threadIdx.x] - max_val);
                sum_exp += s_att[l][threadIdx.x];
            }

            for (int l = 0; l < block_size; ++l) {
                s_att[l][threadIdx.x] /= sum_exp;
            }

            __syncthreads();

            // Multiply with V
            if (i + threadIdx.y < seq_len) {
                float result = 0.0f;
                for (int l = 0; l < block_size; ++l) {
                    result += s_att[threadIdx.y][l] * __half2float(v[(j + l) * embed_dim + threadIdx.x]);
                }
                out[(i + threadIdx.y) * embed_dim + threadIdx.x] = __float2half(result);
            }
        }
    }
