    const __half* K_ptr = K + batch_idx * stride_batch + head_idx * stride_head;
    const __half* V_ptr = V + batch_idx * stride_batch + head_idx * stride_head;
    __half* Out_ptr = Out + batch_idx * stride_batch + head_idx * stride_head;

    const int tile_size = 32;

    __shared__ float s_Q_tile[32][32];
    __shared__ float s_K_tile[32][32];

    for (int out_seq_idx = 0; out_seq_idx < seq_len; ++out_seq_idx) {
        __half* out_row = Out_ptr + out_seq_idx * stride_seq;

        // Initialize output row to zero
        for (int d = 0; d < embed_dim; ++d) {
            out_row[d] = __float2half(0.0f);
        }

        // Compute attention scores for this query position
        for (int tile_start = 0; tile_start < seq_len; tile_start += tile_size) {
            // Load Q tile
            for (int i = 0; i < tile_size && (tile_start + i) < seq_len; ++i) {
                if (threadIdx.x < embed_dim) {
                    s_Q_tile[threadIdx.x][i] = __half2float(Q_ptr[(out_seq_idx * stride_seq) + threadIdx.x]);
                }
