            // Load K tile
            for (int i = 0; i < tile_size && (tile_start + i) < seq_len; ++i) {
                if (threadIdx.y < embed_dim) {
                    s_K_tile[i][threadIdx.y] = __half2float(K_ptr[((tile_start + i) * stride_seq) + threadIdx.y]);
                }
            }

            __syncthreads();

            // Compute attention scores and accumulate
            for (int k = 0; k < tile_size && (tile_start + k) < seq_len; ++k) {
                float max_score = -1e9f;
                float sum_exp = 0.0f;

                // Find maximum score for numerical stability
                for (int i = 0; i < embed_dim; ++i) {
                    float score = s_Q_tile[i][0] * s_K_tile[k][i];
                    max_score = fmaxf(max_score, score);
