                for (int i = 0; i < embed_dim; ++i) {
                    float score = s_Q_tile[i][0] * s_K_tile[k][i];
                    float exp_score = __expf((score - max_score) * scale_factor);
                    exp_scores[i] = exp_score;
                    sum_exp += exp_score;
