                // Normalize and accumulate
                float inv_sum = 1.0f / (sum_exp + 1e-6f);
                for (int d = 0; d < embed_dim; ++d) {
                    float v_val = __half2float(V_ptr[(tile_start + k) * stride_seq + d]);
                    float weighted_val = exp_scores[d] * v_val * inv_sum;

                    float current_val = __half2float(out_row[d]);
                    current_val += weighted_val;
                    out_row[d] = __float2half(current_val);
                }
            }

