        const __half2 h2 = *reinterpret_cast<const __half2*>(row_ptr + c);
        float v0 = __half2float(__low2half(h2));
        float v1 = __half2float(__high2half(h2));
        thread_max = fmaxf(thread_max, v0);
        thread_max = fmaxf(thread_max, v1);
    }
    // warp reduction
    thread_max = warp_max(thread_max);
    // store per‑warp maxima in shared memory
    __shared__ float smax[32];               // up to 32 warps (max 1024 threads)
    if (lane == 0) smax[warp_id] = thread_max;
    __syncthreads();

    // first warp finishes the reduction
    float block_max = -FLT_MAX;
    if (warp_id == 0) {
        block_max = (lane < num_warps) ? smax[lane] : -FLT_MAX;
        block_max = warp_max(block_max);
        if (lane == 0) smax[0] = block_max;
    }
    __syncthreads();
    const float max_val = smax[0];

