#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <math.h>

#define CUDA_CHECK(err) if (err != cudaSuccess) { \
    printf("CUDA error %s:%d: %s\\n", __FILE__, __LINE__, cudaGetErrorString(err)); \
    exit(1); }

////////////////////////////////////////////////////////////////////////////////
// Kernel 1: compute raw attention scores Q @ K^T, scaled by 1/sqrt(D)
////////////////////////////////////////////////////////////////////////////////
template <int BLOCK>
__global__ void compute_scores_kernel(
    const __half* __restrict__ Q,
    const __half* __restrict__ K,
    __half* __restrict__ Scores,
    int B, int H, int S, int D,
    float scale) {

    const int total = B * H * S * S;
    int idx = blockIdx.x * BLOCK + threadIdx.x;
    int stride = gridDim.x * BLOCK;

    for (; idx < total; idx += stride) {
        int tmp = idx;
        int d_idx = tmp % D;               // unused, we compute over D later
        tmp /= D;
        // decode indices
        int j = tmp % S;
        tmp /= S;
        int i = tmp % S;
        tmp /= S;
        int h = tmp % H;
        int b = tmp / H;

        // compute dot product over D
        float sum = 0.0f;
        const __half* q_ptr = Q + (((b * H + h) * S + i) * D);
        const __half* k_ptr = K + (((b * H + h) * S + j) * D);
        #pragma unroll 4
        for (int d = 0; d < D; ++d) {
            sum += __half2float(q_ptr[d]) * __half2float(k_ptr[d]);
        }
        sum *= scale;
        Scores[idx] = __float2half(sum);
    }
}

////////////////////////////////////////////////////////////////////////////////
// Kernel 2: row‑wise softmax (in‑place) over Scores of shape (B,H,S,S)
////////////////////////////////////////////////////////////////////////////////
template <int BLOCK>
__global__ void softmax_kernel(
    __half* __restrict__ Scores,
    int B, int H, int S) {

    // each block handles one row (b,h,i)
    int row = blockIdx.x; // 0 .. B*H*S-1
    if (row >= B * H * S) return;

    int b = row / (H * S);
    int h = (row / S) % H;
    int i = row % S;

    // pointer to the start of this row
    __half* row_ptr = Scores + (( (b * H + h) * S + i) * S);

    // 1) compute max for numerical stability
    __shared__ float smax[BLOCK];
    float local_max = -FLT_MAX;
    for (int j = threadIdx.x; j < S; j += BLOCK) {
        float val = __half2float(row_ptr[j]);
        if (val > local_max) local_max = val;
    }
    smax[threadIdx.x] = local_max;
    __syncthreads();

    // reduction to find block max
    for (int offset = BLOCK / 2; offset > 0; offset >>= 1) {
        if (threadIdx.x < offset) {
            if (smax[threadIdx.x + offset] > smax[threadIdx.x])
                smax[threadIdx.x] = smax[threadIdx.x + offset];
        }
        __syncthreads();
    }
    float row_max = smax[0];

    // 2) compute sum of exp(x - max)
    __shared__ float ssum[BLOCK];
    float local_sum = 0.0f;
    for (int j = threadIdx.x; j < S; j += BLOCK) {
        float val = __half2float(row_ptr[j]);
        float e = __expf(val - row_max);
        local_sum += e;
        // store temporary exponent result back (reuse memory)
        row_ptr[j] = __float2half(e);
    }
    ssum[threadIdx.x] = local_sum;
    __syncthreads();

    // reduction to find block sum
    for (int offset = BLOCK / 2; offset > 0; offset >>= 1) {
        if (threadIdx.x < offset) {
            ssum[threadIdx.x] += ssum[threadIdx.x + offset];
        }
        __syncthreads();
    }
    float row_sum = ssum[0] + 1e-6f; // avoid div by zero

    // 3) normalize
    for (int j = threadIdx.x; j < S; j += BLOCK) {
        float e = __half2float(row_ptr[j]); // exponent stored earlier
        float prob = e / row_sum;
        row_ptr[j] = __float2half(prob);
    }
}

////////////////////////////////////////////////////////////////////////////////
// Kernel 3: output = softmax_scores @ V
////////////////////////////////////////////////////////////////////////////////
template <int BLOCK>
__global__ void apply_attention_kernel(
    const __half* __restrict__ Scores, // (B,H,S,S) after softmax
    const __half* __restrict__ V,
    __half* __restrict__ Out,
    int B, int H, int S, int D) {

    const int total = B * H * S * D;
    int idx = blockIdx.x * BLOCK + threadIdx.x;
    int stride = gridDim.x * BLOCK;

    for (; idx < total; idx += stride) {
        int tmp = idx;
        int d = tmp % D;
        tmp /= D;
        int i = tmp % S;
        tmp /= S;
        int h = tmp % H;
        int b = tmp / H;

        float acc = 0.0f;
        const __half* prob_ptr = Scores + (((b * H + h) * S + i) * S);
        const __half* v_ptr   = V      + (((b * H + h) * S) * D);
        for (int j = 0; j < S; ++j) {
            float prob = __half2float(prob_ptr[j]);
            float vval = __half2float(v_ptr[j * D + d]);
            acc += prob * vval;
        }
        Out[idx] = __float2half(acc);
    }
}

// ---------------------------------------------------------------------------
// Wrapper function exposed to Python
// ---------------------------------------------------------------------------
torch::Tensor scaled_dot_product_attention_cuda(torch::Tensor Q,
                                                torch::Tensor K,
                                                torch::Tensor V) {
    // ensure contiguous and half dtype
    Q = Q.contiguous();
    K = K.contiguous();
    V = V.contiguous();

    const int B = Q.size(0);
    const int H = Q.size(1);
    const int S = Q.size(2);
    const int D = Q.size(3);

