    const int rows = B * H * S;
    const int grid_softmax = rows; // one block per row
    softmax_kernel<BLOCK><<<grid_softmax, BLOCK>>>(
        reinterpret_cast<__half*>(Scores.data_ptr()),
        B, H, S);
