// Kernel 1: Compute Q @ K^T scaled, store in scores (B,H,S,S)
// -----------------------------------------------------------------------------
__global__ void compute_scores_kernel(const __half* __restrict__ Q,
                                      const __half* __restrict__ K,
                                      __half* __restrict__ scores,
                                      int B, int H, int S, int D,
