    int tmp = idx;
    int j = tmp % S; tmp /= S;
    int i = tmp % S; tmp /= S;
    int h = tmp % H; tmp /= H;
    int b = tmp;

    const __half* q_ptr = Q + (((b * H + h) * S + i) * D);
    const __half* k_ptr = K + (((b * H + h) * S + j) * D);

    float acc = 0.0f;
    for (int d = 0; d < D; ++d) {
        float qf = __half2float(q_ptr[d]);
        float kf = __half2float(k_ptr[d]);
        acc += qf * kf;
    }
    acc *= scale;
    scores[idx] = __float2half(acc);
}

// -----------------------------------------------------------------------------
// Kernel 2: Row‑wise softmax over last dimension (S)
// each block processes one row (B,H,i)
// -----------------------------------------------------------------------------
__global__ void softmax_kernel(__half* __restrict__ scores,
                               int rows, int S) {
    int row = blockIdx.x;
    if (row >= rows) return;

    __half* row_ptr = scores + row * S;

    // ---------- max reduction ----------
    float max_val = -INF;
    for (int idx = threadIdx.x; idx < S; idx += blockDim.x) {
        float v = __half2float(row_ptr[idx]);
        max_val = fmaxf(max_val, v);
    }

    extern __shared__ float shm[];   // size = blockDim.x floats
    shm[threadIdx.x] = max_val;
    __syncthreads();

    for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
        if (threadIdx.x < offset) {
            shm[threadIdx.x] = fmaxf(shm[threadIdx.x], shm[threadIdx.x + offset]);
        }
        __syncthreads();
    }
    float row_max = shm[0];
    __syncthreads();

    // ---------- sum of exp ----------
    float sum_exp = 0.0f;
    for (int idx = threadIdx.x; idx < S; idx += blockDim.x) {
        float v = __half2float(row_ptr[idx]);
        sum_exp += __expf(v - row_max);
    }
    shm[threadIdx.x] = sum_exp;
    __syncthreads();

    for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
        if (threadIdx.x < offset) {
            shm[threadIdx.x] += shm[threadIdx.x + offset];
        }
        __syncthreads();
    }
    float row_sum = shm[0];
    __syncthreads();

    // ---------- write normalized softmax ----------
    for (int idx = threadIdx.x; idx < S; idx += blockDim.x) {
        float v = __half2float(row_ptr[idx]);
        float prob = __expf(v - row_max) / row_sum;
        row_ptr[idx] = __float2half(prob);
    }
