// -----------------------------------------------------------------------------
// Kernel 3: Compute softmax_scores @ V -> output (B,H,S,D)
// -----------------------------------------------------------------------------
__global__ void compute_output_kernel(const __half* __restrict__ scores,
                                      const __half* __restrict__ V,
                                      __half* __restrict__ out,
                                      int B, int H, int S, int D) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * H * S * D;
    if (idx >= total) return;

    // decode linear index to (b,h,i,d)
    int tmp = idx;
    int d = tmp % D; tmp /= D;
    int i = tmp % S; tmp /= S;
    int h = tmp % H; tmp /= H;
    int b = tmp;

    const __half* score_row = scores + (((b * H + h) * S + i) * S);   // [S]
    const __half* v_base    = V + (((b * H + h) * S) * D);           // [S, D]

    float acc = 0.0f;
    for (int j = 0; j < S; ++j) {
        float s = __half2float(score_row[j]);
        float v = __half2float(v_base[j * D + d]);
        acc += s * v;
    }
    out[idx] = __float2half(acc);
