#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <float.h>

__global__ void attention_kernel(
    const __half* __restrict__ Q,
    const __half* __restrict__ K,
    const __half* __restrict__ V,
    __half* __restrict__ Out,
    int B, int H, int S, int D)
{
    // each block processes one (b, h, i) row
    int row = blockIdx.x;
    if (row >= B * H * S) return;

    int b = row / (H * S);
    int rem = row % (H * S);
    int h = rem / S;
    int i = rem % S;

    const __half* q_ptr = Q + ((b * H + h) * S + i) * D;          // Q[i]
    const __half* k_base = K + ((b * H + h) * S) * D;            // K[0]
    const __half* v_base = V + ((b * H + h) * S) * D;            // V[0]
    __half* out_ptr = Out + ((b * H + h) * S + i) * D;           // Out[i]

    // shared memory: scores[S] + tmp[blockDim.x]
    extern __shared__ float shared[];
    float* scores = shared;                     // length S
    float* tmp    = shared + S;                 // length blockDim.x

    const float scale = rsqrtf((float)D);       // 1/sqrt(D)

    // 1) Compute raw scores = Q[i]·K[j] * scale
    float thread_max = -FLT_MAX;
    for (int j = threadIdx.x; j < S; j += blockDim.x) {
        float dot = 0.0f;
        const __half* k_ptr = k_base + j * D;
        #pragma unroll 4
        for (int d = 0; d < D; ++d) {
            float qf = __half2float(q_ptr[d]);
            float kf = __half2float(k_ptr[d]);
            dot += qf * kf;
        }
        dot *= scale;
        scores[j] = dot;
        thread_max = fmaxf(thread_max, dot);
    }

    // 2) Reduce to find max across all j
    tmp[threadIdx.x] = thread_max;
    __syncthreads();
    for (int offset = blockDim.x >> 1; offset > 0; offset >>= 1) {
        if (threadIdx.x < offset) {
            tmp[threadIdx.x] = fmaxf(tmp[threadIdx.x], tmp[threadIdx.x + offset]);
        }
        __syncthreads();
    }
    float max_val = tmp[0];
    __syncthreads();

    // 3) Exponentiate and compute sum of exp
    float thread_sum = 0.0f;
    for (int j = threadIdx.x; j < S; j += blockDim.x) {
        float exp_val = __expf(scores[j] - max_val);
        scores[j] = exp_val;          // reuse storage for softmax numerator
        thread_sum += exp_val;
