    tmp[threadIdx.x] = thread_sum;
    __syncthreads();
    for (int offset = blockDim.x >> 1; offset > 0; offset >>= 1) {
        if (threadIdx.x < offset) {
            tmp[threadIdx.x] += tmp[threadIdx.x + offset];
        }
        __syncthreads();
    }
    float sum_exp = tmp[0];
    __syncthreads();

    // 4) Weighted sum over V using softmax weights
    for (int d = threadIdx.x; d < D; d += blockDim.x) {
        float acc = 0.0f;
        for (int j = 0; j < S; ++j) {
            float weight = scores[j] / sum_exp;
            float v_val = __half2float(v_base[j * D + d]);
            acc += weight * v_val;
