    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * H * S * D;
    if (idx >= total) return;

    int d = idx % D;
    int tmp = idx / D;
    int i = tmp % S;
    tmp = tmp / S;
    int h = tmp % H;
    int b = tmp / H;

    // V layout: (B, H, S, D)
    const __half* v_ptr_base = V + ((b * H + h) * S) * D;   // start of V for (b,h)
    const __half* score_ptr = scores + ((b * H + h) * S + i) * S; // row i of attention scores

    float acc = 0.0f;
    for (int j = 0; j < S; ++j) {
        float s = __half2float(score_ptr[j]);                     // softmax weight
        float v = __half2float(v_ptr_base[j * D + d]);           // V[j,d]
        acc += s * v;
