    cvta.to.global.u64 %rd5, %rd0;
    add.u64 %rd6, %rd5, %rd4;

    // load fp16, convert to f32
    ld.global.f16 %h0, [%rd6];
    cvt.f32.f16 %f3, %h0;

    // accumulate
    add.f32 %f1, %f1, %f3;
    mul.f32 %f4, %f3, %f3;
    add.f32 %f2, %f2, %f4;

    // i += blockDim.x
    add.u32 %r12, %r12, %r7;
    bra $LOOP_SUM;

$END_SUM:
    // store per‑thread partial results in shared memory
    mul.lo.u32 %r18, %r6, 4;          // byte offset (4 bytes per f32)
    st.shared.f32 [s_sum+%r18], %f1;
    st.shared.f32 [s_sumsq+%r18], %f2;

    // synchronize
    bar.sync 0;

    // ---------- reduction (thread 0 aggregates) ----------
    setp.ne.u32 %p1, %r6, 0;
    @%p1 bra $REDUCE_SKIP;   // only thread 0 proceeds

    // thread 0 sums all per‑thread results
    mov.f32 %f5, 0.0;   // total_sum
    mov.f32 %f6, 0.0;   // total_sumsq
    mov.u32 %r19, 0;    // j

$REDUCE_LOOP:
    setp.ge.u32 %p2, %r19, %r7;
    @%p2 bra $REDUCE_DONE;

    mul.lo.u32 %r20, %r19, 4;   // offset
    ld.shared.f32 %f7, [s_sum+%r20];
    add.f32 %f5, %f5, %f7;
    ld.shared.f32 %f8, [s_sumsq+%r20];
    add.f32 %f6, %f6, %f8;

    add.u32 %r19, %r19, 1;
    bra $REDUCE_LOOP;

$REDUCE_DONE:
    // write reduced totals back to shared (position 0)
    st.shared.f32 [s_sum], %f5;
    st.shared.f32 [s_sumsq], %f6;
$REDUCE_SKIP:

    // ensure all threads see the reduced results
    bar.sync 0;

    // load reduced totals
    ld.shared.f32 %f9,  [s_sum];
    ld.shared.f32 %f10, [s_sumsq];

    // compute mean = sum / group_elems
    cvt.f32.u32 %f11, %r11;
    div.f32 %f12, %f9, %f11;          // mean

    // variance = (sumsq / N) - mean*mean
    div.f32 %f13, %f10, %f11;         // avg of squares
    mul.f32 %f14, %f12, %f12;         // mean^2
    sub.f32 %f15, %f13, %f14;         // variance

    // variance + epsilon
    add.f32 %f16, %f15, %f30;         // eps already float32

    // inverse stddev
    rsqrt.approx.f32 %f17, %f16;      // 1/sqrt(var+eps)

    // broadcast mean & invstd via shared
    st.shared.f32 [s_mean], %f12;
    st.shared.f32 [s_invstd], %f17;

    bar.sync 0;

    // reload for all threads
    ld.shared.f32 %f18, [s_mean];
    ld.shared.f32 %f19, [s_invstd];

    // ---------- second pass: write normalized output ----------
    mov.u32 %r12, %r6;   // i = tid

$LOOP_OUT:
    setp.ge.u32 %p3, %r12, %r11;
    @%p3 bra $END_OUT;

    // recompute indices (same as above)
    div.u32 %r13, %r12, %r3;
    rem.u32 %r14, %r12, %r3;
    mad.lo.u32 %r15, %r8, %r10, %r13;
    mad.lo.u32 %r16, %r9, %r1, %r15;
    mad.lo.u32 %r17, %r16, %r3, %r14;

    // load input fp16, convert to f32
    mul.wide.u32 %rd7, %r17, 2;
    cvta.to.global.u64 %rd8, %rd0;
    add.u64 %rd9, %rd8, %rd7;
    ld.global.f16 %h1, [%rd9];
    cvt.f32.f16 %f20, %h1;

    // normalize: (x - mean) * inv_std
    sub.f32 %f21, %f20, %f18;
    mul.f32 %f22, %f21, %f19;

    // load weight for channel c (fp16)
    mul.wide.u32 %rd10, %r15, 2;
    cvta.to.global.u64 %rd11, %rd1;
    add.u64 %rd12, %rd11, %rd10;
    ld.global.f16 %h2, [%rd12];
    cvt.f32.f16 %f23, %h2;

    // load bias for channel c (fp16)
    mul.wide.u32 %rd13, %r15, 2;
    cvta.to.global.u64 %rd14, %rd2;
    add.u64 %rd15, %rd14, %rd13;
    ld.global.f16 %h3, [%rd15];
    cvt.f32.f16 %f24, %h3;

    // y = norm * w + b
    mad.f32 %f25, %f22, %f23, %f24;

    // convert back to fp16
    cvt.rn.f16.f32 %h4, %f25;

    // store output
    mul.wide.u32 %rd16, %r17, 2;
    cvta.to.global.u64 %rd17, %rd3;
    add.u64 %rd18, %rd17, %rd16;
    st.global.f16 [%rd18], %h4;

    // i += blockDim.x
    add.u32 %r12, %r12, %r7;
    bra $LOOP_OUT;

$END_OUT:
    ret;
}
"""

class ModelNew(nn.Module):
    def __init__(self, num_features: int, num_groups: int):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(num_features, dtype=torch.float16))
        self.bias   = nn.Parameter(torch.zeros(num_features, dtype=torch.float16))
        self.eps    = 1e-5
        self.num_groups = num_groups
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.dtype == torch.float16, "Input must be fp16"
        N, C = x.shape[0], x.shape[1]

        # compute spatial size (product of remaining dimensions)
        S = 1
        for dim in x.shape[2:]:
            S *= dim

        out = torch.empty_like(x)

        # launch one block per (batch element, group)
        blocks = N * self.num_groups
        threads = 256
        grid = (blocks, 1, 1)

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            self.bias.data_ptr(),
            out.data_ptr(),
            int(N),
            int(C),
            int(self.num_groups),
            int(S),
            float(self.eps)          # epsilon will be reinterpreted as float32 in PTX
        ]

        ptx_launch(self.module, "groupnorm", grid, (threads, 1, 1), args)
        return out

