class ModelNew(torch.nn.Module):
    """
    Group Normalization implemented in PTX (fp16 I/O, fp32 accumulation) for
    NVIDIA RTX PRO 6000 Blackwell (sm_120a).
    """
    def __init__(self, num_features: int, num_groups: int):
        super().__init__()
        self.num_features = num_features
        self.num_groups = num_groups
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure fp16 contiguous tensor
        x = x.to(torch.float16).contiguous()
        N, C, H, W = x.shape
        G = self.num_groups

        # Buffers for per‑group sum and sum‑of‑squares (fp32)
        sum_buf   = torch.zeros((N, G), dtype=torch.float32, device='cuda')
        sumsq_buf = torch.zeros_like(sum_buf)

        total_elems = N * C * H * W
        block = 256
        grid = ((total_elems + block - 1) // block, 1, 1)

        # First kernel: compute per‑group sum and sum of squares
        ptx_launch(
            self.module,
            "groupnorm_sum",
            grid,
            (block, 1, 1),
            [
                x.data_ptr(),
                sum_buf.data_ptr(),
                sumsq_buf.data_ptr(),
                N, C, H, W, G
            ]
        )

        # Second kernel: normalize using the statistics
        eps = 1e-5
        cnt_per_group = (C // G) * H * W
        out = torch.empty_like(x)

        ptx_launch(
            self.module,
            "groupnorm_norm",
            grid,
            (block, 1, 1),
            [
                x.data_ptr(),
                out.data_ptr(),
                sum_buf.data_ptr(),
                sumsq_buf.data_ptr(),
                N, C, H, W, G,
                eps,
                cnt_per_group
            ]
        )
        return out

