    cvta.to.global.u64 %rd5, %rd1;   // input base
    cvta.to.global.u64 %rd6, %rd2;   // output base
    cvta.to.global.u64 %rd7, %rd3;   // weight base
    cvta.to.global.u64 %rd8, %rd4;   // bias base

