    add.u64        %rd22, %rd8, %rd21;    // batch_offset_C + i*N
    cvt.u64.u32    %rd23, %r10;           // j as 64‑bit
    add.u64        %rd24, %rd22, %rd23;   // +j (elements)
    shl.b64        %rd25, %rd24, 1;       // byte offset
    add.u64        %rd26, %rd5, %rd25;    // address of C[i,j]
    cvt.rn.f16.f32 %h2, %f0;
    st.global.f16  [%rd26], %h2;

