.version 8.5
.target sm_120a
.address_size 64

.visible .entry batched_matmul(
    .param .u64 matmul_param_0,   // A pointer (fp16)
    .param .u64 matmul_param_1,   // B pointer (fp16)
    .param .u64 matmul_param_2,   // C pointer (fp16)
    .param .u32 matmul_param_3,   // batch size
    .param .u32 matmul_param_4,   // m (rows of A / C)
    .param .u32 matmul_param_5,   // n (cols of B / C)
    .param .u32 matmul_param_6    // k (inner dimension)
)
{
    // -------------------------------------------------
    // Register declarations
    // -------------------------------------------------
    .reg .pred   %p<5>;
    .reg .b32    %r<30>;
    .reg .b64    %rd<20>;
    .reg .f32    %f<4>;
    .reg .f16    %h<3>;

    // -------------------------------------------------
    // Load kernel parameters
    // -------------------------------------------------
    ld.param.u64 %rd1, [matmul_param_0];   // A base pointer
    ld.param.u64 %rd2, [matmul_param_1];   // B base pointer
    ld.param.u64 %rd3, [matmul_param_2];   // C base pointer
    ld.param.u32 %r8,  [matmul_param_3];   // batch
    ld.param.u32 %r9,  [matmul_param_4];   // m
    ld.param.u32 %r10, [matmul_param_5];   // n
    ld.param.u32 %r11, [matmul_param_6];   // k

    // -------------------------------------------------
    // Thread/block identifiers
    // -------------------------------------------------
    mov.u32 %r0, %ctaid.x;   // blockIdx.x → column tile (j)
    mov.u32 %r1, %ctaid.y;   // blockIdx.y → row    tile (i)
    mov.u32 %r2, %ctaid.z;   // blockIdx.z → batch index (b)

    mov.u32 %r3, %ntid.x;    // blockDim.x
    mov.u32 %r4, %ntid.y;    // blockDim.y

    mov.u32 %r5, %tid.x;     // threadIdx.x
    mov.u32 %r6, %tid.y;     // threadIdx.y

    // -------------------------------------------------
    // Compute global coordinates (i, j, b)
    // -------------------------------------------------
    mad.lo.s32 %r12, %r0, %r3, %r5;   // j = blockIdx.x * blockDim.x + threadIdx.x
    mad.lo.s32 %r13, %r1, %r4, %r6;   // i = blockIdx.y * blockDim.y + threadIdx.y
    mov.u32    %r14, %r2;            // b = batch index

    // -------------------------------------------------
    // Bounds check
    // -------------------------------------------------
    setp.ge.s32 %p0, %r13, %r9;   // i >= m ?
    @%p0 bra $L_DONE;
    setp.ge.s32 %p1, %r12, %r10;  // j >= n ?
    @%p1 bra $L_DONE;

    // -------------------------------------------------
    // Convert generic pointers to global address space
    // -------------------------------------------------
    cvta.to.global.u64 %rd4, %rd1;   // A base (global)
    cvta.to.global.u64 %rd5, %rd2;   // B base (global)
    cvta.to.global.u64 %rd6, %rd3;   // C base (global)

    // -------------------------------------------------
    // Compute per‑batch row offsets (in elements)
    // -------------------------------------------------
    // rowIdx = b * m + i
    mul.lo.s32 %r15, %r14, %r9;      // b * m
    add.s32    %r15, %r15, %r13;     // rowIdx

    // base offset for A: rowIdx * k
    mul.lo.s32 %r16, %r15, %r11;     // baseA_elem
    mul.wide.s32 %rd7, %r16, 2;      // baseA_byte (fp16 size = 2)

    // base offset for C: rowIdx * n
    mul.lo.s32 %r17, %r15, %r10;     // baseC_elem
    mul.wide.s32 %rd8, %r17, 2;      // baseC_byte

    // -------------------------------------------------
    // Compute batch offset for B (in elements)
    // -------------------------------------------------
    // batchB_elem = b * k * n
    mul.lo.s32 %r18, %r14, %r11;    // b * k
    mul.lo.s32 %r18, %r18, %r10;    // (b*k) * n
    mul.wide.s32 %rd9, %r18, 2;     // baseB_byte

    // -------------------------------------------------
    // Accumulator (fp32)
    // -------------------------------------------------
    mov.f32 %f0, 0f0;

    // -------------------------------------------------
    // Loop over K dimension
    // -------------------------------------------------
    mov.u32 %r19, 0;                 // p = 0
$L_K_LOOP:
    setp.ge.s32 %p2, %r19, %r11;    // p >= k ?
    @%p2 bra $L_K_END;

    // ---- Load A[b,i,p] (fp16) ----
    // addrA = baseA_byte + p*2
    mul.wide.s32 %rd10, %r19, 2;    // p*2
    add.u64 %rd11, %rd4, %rd7;      // A base
    add.u64 %rd12, %rd11, %rd10;    // final address
    ld.global.f16 %h0, [%rd12];
    cvt.f32.f16 %f1, %h0;

    // ---- Load B[b,p,j] (fp16) ----
    // offset = (p * n + j) * 2
    mul.lo.s32 %r20, %r19, %r10;    // p * n
    add.s32 %r20, %r20, %r12;       // p*n + j
    mul.wide.s32 %rd13, %r20, 2;    // *2 → bytes
    add.u64 %rd14, %rd5, %rd9;      // B batch base
    add.u64 %rd15, %rd14, %rd13;    // final address
    ld.global.f16 %h1, [%rd15];
    cvt.f32.f16 %f2, %h1;

    // ---- Multiply‑Accumulate ----
    fma.rn.f32 %f0, %f1, %f2, %f0;

    // ---- Increment p ----
    add.u32 %r19, %r19, 1;
    bra $L_K_LOOP;
$L_K_END:

    // -------------------------------------------------
    // Store result C[b,i,j] (fp16)
    // -------------------------------------------------
    // addrC = baseC_byte + j*2
    mul.wide.s32 %rd16, %r12, 2;    // j*2
    add.u64 %rd17, %rd6, %rd8;      // C base
    add.u64 %rd18, %rd17, %rd16;    // final address
    cvt.rn.f16.f32 %h2, %f0;
    st.global.f16 [%rd18], %h2;

$L_DONE:
    ret;
}
