    mov.u32         %r5, %ctaid.x;   // blockIdx.x (col tile)
    mov.u32         %r6, %ctaid.y;   // blockIdx.y (row tile)
    mov.u32         %r7, %ctaid.z;   // blockIdx.z (batch)

    mov.u32         %r8, %tid.x;     // threadIdx.x
    mov.u32         %r9, %tid.y;     // threadIdx.y

    mov.u32         %r10, %ntid.x;   // blockDim.x
    mov.u32         %r11, %ntid.y;   // blockDim.y

