    mad.lo.s32      %r12, %r6, %r11, %r9;   // row = blockIdx.y * blockDim.y + threadIdx.y
    mad.lo.s32      %r13, %r5, %r10, %r8;   // col = blockIdx.x * blockDim.x + threadIdx.x

