    // address of element i (bytes)
    mul.wide.u32    %rd9, %r6, 2;           // i * 2
    add.s64         %rd10, %rd7, %rd9;      // in_base + offset

    // load fp16, promote to fp32
    ld.global.f16   %h1, [%rd10];
    cvt.f32.f16     %f1, %h1;

    // accumulate
    add.f32         %f2, %f2, %f1;          // sum += x
    mul.f32         %f4, %f1, %f1;          // x*x
    add.f32         %f3, %f3, %f4;          // sumsq += x*x

    // stride forward
    add.u32         %r6, %r6, %r4;
    bra             $LOOP_SUM;

$END_LOOP_SUM:

    // store per‑thread partial results into shared memory
    mul.wide.u32    %rd11, %r5, 4;          // tid * 4 (bytes)
    mov.u64         %rd12, s_sum;
    add.u64         %rd13, %rd12, %rd11;
    st.shared.f32   [%rd13], %f2;

    mov.u64         %rd14, s_sumsq;
    add.u64         %rd15, %rd14, %rd11;
    st.shared.f32   [%rd15], %f3;

    bar.sync 0;                              // publish partials

    // -------------------------------------------------
    // Reduction on thread 0 to obtain total sum & sumsq
    setp.ne.u32     %p3, %r5, 0;            // %p3 = (tid != 0)
    @%p3 bra        $AFTER_REDUCE;         // non‑zero threads skip

    // thread 0: reduction over blockDim.x entries
    mov.f32         %f5, 0.0;               // total_sum
    mov.f32         %f6, 0.0;               // total_sumsq
    mov.u32         %r7, 0;                 // j = 0

$REDUCTION_LOOP:
    setp.ge.u32     %p4, %r7, %r4;
    @%p4 bra        $REDUCTION_END;

    // load sum[j]
    mul.wide.u32    %rd16, %r7, 4;
    mov.u64         %rd17, s_sum;
    add.u64         %rd18, %rd17, %rd16;
    ld.shared.f32   %f7, [%rd18];
    add.f32         %f5, %f5, %f7;

    // load sumsq[j]
    mov.u64         %rd19, s_sumsq;
    add.u64         %rd20, %rd19, %rd16;
    ld.shared.f32   %f8, [%rd20];
    add.f32         %f6, %f6, %f8;

    add.u32         %r7, %r7, 1;
    bra             $REDUCTION_LOOP;

$REDUCTION_END:
    // mean = total_sum / N
    cvt.f32.u32     %f9, %r2;               // N as float
    div.f32         %f10, %f5, %f9;         // mean

    // variance = (total_sumsq / N) - mean*mean
    div.f32         %f11, %f6, %f9;         // total_sumsq / N
    mul.f32         %f12, %f10, %f10;       // mean*mean
    sub.f32         %f11, %f11, %f12;       // var

    // epsilon and inv_std
    mov.f32         %f13, 1e-05;
    add.f32         %f11, %f11, %f13;       // var + eps
    rsqrt.approx.f32 %f14, %f11;           // 1/sqrt(var+eps)

    // store mean & inv_std in shared memory for broadcast
    mov.u64         %rd21, s_sum;
    st.shared.f32   [%rd21], %f10;         // mean
    mov.u64         %rd22, s_sumsq;
    st.shared.f32   [%rd22], %f14;         // inv_std

    // fall through
$AFTER_REDUCE:
    bar.sync 0;                              // make mean & inv_std visible

    // -------------------------------------------------
    // Broadcast mean & inv_std to all threads
    mov.u64         %rd23, s_sum;
    ld.shared.f32   %f10, [%rd23];          // mean
    mov.u64         %rd24, s_sumsq;
    ld.shared.f32   %f14, [%rd24];          // inv_std

    // Second pass: write normalized values
    mov.u32         %r6, %r5;               // i = threadIdx.x

$LOOP_NORM:
    setp.ge.u32     %p5, %r6, %r2;
    @%p5 bra        $END_LOOP_NORM;

    // load input element
    mul.wide.u32    %rd9, %r6, 2;
    add.s64         %rd10, %rd7, %rd9;
    ld.global.f16   %h2, [%rd10];
    cvt.f32.f16     %f1, %h2;

    // (x - mean) * inv_std
    sub.f32         %f1, %f1, %f10;
    mul.f32         %f1, %f1, %f14;

    // store as fp16
    cvt.rn.f16.f32  %h3, %f1;
    add.s64         %rd11, %rd8, %rd9;
    st.global.f16   [%rd11], %h3;

    // stride forward
    add.u32         %r6, %r6, %r4;
    bra             $LOOP_NORM;

$END_LOOP_NORM:
$L_EXIT:
    ret;
}
"""

