        super().__init__()
        # normalized_shape is ignored; we normalize over the flattened trailing dimensions
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.dtype == torch.float16, "Input must be FP16"
        B = x.shape[0]                          # batch dimension
        N = x.numel() // B                       # elements per batch (flattened)
