    shl.b64         %rd4, %rd3, 1;    // *2 (bytes per fp16)
    cvta.to.global.u64 %rd5, %rd0;
    add.u64         %rd6, %rd5, %rd4; // input_base

    // Accumulators (float32)
    mov.f32         %f2, 0.0;        // sum
    mov.f32         %f4, 0.0;        // sum of squares

