    ld.param.u64    %rd0, [input_ptr];
    ld.param.u64    %rd1, [output_ptr];
    ld.param.u64    %rd2, [sum_ptr];
    ld.param.u64    %rd3, [sumsq_ptr];
    ld.param.u32    %r0,  [batch];
    ld.param.u32    %r1,  [n_per_batch];
    ld.param.f32    %f13, [eps];

    // Thread / block indices
    mov.u32         %r2, %ctaid.x;   // batch index
    mov.u32         %r3, %ctaid.y;   // block index along N dimension
    mov.u32         %r4, %tid.x;    // threadIdx.x
    mov.u32         %r5, %ntid.x;   // blockDim.x

    // Compute global element index within the batch
    mul.lo.u32      %r6, %r3, %r5;   // blockIdx.y * blockDim.x
    add.u32         %r7, %r4, %r6;   // i = threadIdx.x + blockIdx.y*blockDim.x

    // Bounds check
    setp.ge.u32     %p0, %r7, %r1;
    @%p0 bra        END_KERNEL;

    // Base address for this batch (batch * N * 2 bytes)
    mul.wide.u32    %rd4, %r2, %r1;   // batch * N
    shl.b64         %rd5, %rd4, 1;    // *2 (bytes per fp16)

    // Input base pointer for this batch
    cvta.to.global.u64 %rd6, %rd0;
    add.u64         %rd7, %rd6, %rd5; // input_base

    // Output base pointer for this batch
    cvta.to.global.u64 %rd8, %rd1;
    add.u64         %rd9, %rd8, %rd5; // output_base

    // Load input element (fp16) and convert to f32
    mul.wide.u32    %rd10, %r7, 2;    // i * 2 (bytes)
    add.u64         %rd11, %rd7, %rd10;
    ld.global.f16   %h0, [%rd11];
    cvt.f32.f16     %f0, %h0;         // x as f32

    // Load per‑batch sum (float32)
    cvta.to.global.u64 %rd12, %rd2;
    mul.wide.u32    %rd13, %r2, 4;    // batch * sizeof(float)
    add.u64         %rd14, %rd12, %rd13;
    ld.global.f32   %f1, [%rd14];    // sum

    // Load per‑batch sum‑of‑squares (float32)
    cvta.to.global.u64 %rd15, %rd3;
    add.u64         %rd16, %rd15, %rd13;
    ld.global.f32   %f2, [%rd16];    // sumsq

