    cvt.f32.u32     %f3, %r1;        // N as float
    div.f32         %f4, %f1, %f3;   // mean = sum/N
    div.f32         %f5, %f2, %f3;   // mean_sq = sumsq/N
    mul.f32         %f6, %f4, %f4;   // mean^2
    sub.f32         %f7, %f5, %f6;   // var = mean_sq - mean^2
    add.f32         %f7, %f7, %f13;  // var + eps
    rsqrt.approx.f32 %f8, %f7;       // 1/sqrt(var+eps)

    // Normalize: (x - mean) * rsqrt(var+eps)
    sub.f32         %f9, %f0, %f4;   // x - mean
    mul.f32         %f10, %f9, %f8;  // normalized value

    // Store result as fp16
    cvt.rn.f16.f32  %h1, %f10;
    mul.wide.u32    %rd17, %r7, 2;   // i * 2 (bytes)
    add.u64         %rd18, %rd9, %rd17;
    st.global.f16   [%rd18], %h1;

