class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.normalized_shape = normalized_shape
        # Load PTX module once
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Apply Layer Normalization implemented in PTX.
        Expected input shape: (batch, *normalized_shape)
        """
        batch = x.size(0)

        # total number of elements per batch (product of normalized dimensions)
        n = 1
        for dim in self.normalized_shape:
            n *= dim

        # Allocate per‑batch sum and sum‑of‑squares buffers (float32)
        sum_buf   = torch.empty(batch, dtype=torch.float32, device=x.device)
        sumsq_buf = torch.empty(batch, dtype=torch.float32, device=x.device)

        block_sz = 256

        # First pass: compute per‑batch sum and sum‑of‑squares
        ptx_launch(
            self.module,
            "sum_reduce",
            grid=(batch, 1, 1),
            block=(block_sz, 1, 1),
            args=[
                x.data_ptr(),
                sum_buf.data_ptr(),
                sumsq_buf.data_ptr(),
                batch,
                n
            ]
        )

        # Second pass: normalize using the statistics
        out = torch.empty_like(x)
        eps = 1e-5
        grid_y = (n + block_sz - 1) // block_sz

        ptx_launch(
            self.module,
            "layernorm",
            grid=(batch, grid_y, 1),
            block=(block_sz, 1, 1),
            args=[
                x.data_ptr(),
                out.data_ptr(),
                sum_buf.data_ptr(),
                sumsq_buf.data_ptr(),
                batch,
                n,
                eps
            ]
        )
        return out

