    mov.u32   %r1, %ctaid.x;               // batch index
    mul.lo.u32 %r2, %r0, 2;                // bytes per slice = N * sizeof(fp16)
    mul.wide.u32 %rd4, %r1, %r2;           // 64‑bit byte offset for this batch

    //----- convert generic pointers to global address space ----------
    cvta.to.global.u64 %rd5, %rd0;   // input base
    cvta.to.global.u64 %rd6, %rd1;   // weight base
    cvta.to.global.u64 %rd7, %rd2;   // bias base
    cvta.to.global.u64 %rd8, %rd3;   // output base

    //----- input pointer for this batch -----------------------------
    add.u64 %rd9, %rd5, %rd4;        // input_ptr_batch

    //----- first pass: compute sum and sum of squares (float32) -----
    mov.f32 %f0, 0.0;                // sum
    mov.f32 %f1, 0.0;                // sumsq
    mov.u32 %r3, 0;                  // i = 0

$LOOP_SUM:
    setp.ge.u32 %p0, %r3, %r0;
    @%p0 bra $END_SUM;

    mul.wide.u32 %rd10, %r3, 2;      // offset = i * sizeof(fp16)
    add.u64 %rd11, %rd9, %rd10;
    ld.global.f16 %h0, [%rd11];
    cvt.f32.f16 %f2, %h0;            // x as f32

