    cvt.f32.u32 %f4, %r0;            // N as float
    div.f32 %f5, %f0, %f4;           // mean = sum / N
    div.f32 %f6, %f1, %f4;           // mean_sq = sumsq / N
    mul.f32 %f7, %f5, %f5;           // mean*mean
    sub.f32 %f8, %f6, %f7;           // var = mean_sq - mean*mean

    ld.const.f32 %f9, [eps];
    add.f32 %f8, %f8, %f9;           // var + eps

