class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        # reference LayerNorm for parameter values (float32)
        self.ln = nn.LayerNorm(normalized_shape=normalized_shape,
                               eps=1e-5,
                               elementwise_affine=True)

        # cast parameters to fp16 for the PTX kernel
        self.ln.weight.data = self.ln.weight.data.to(torch.float16)
        self.ln.bias.data   = self.ln.bias.data.to(torch.float16)

