        # ensure fp16 tensors
        x_fp16 = x.to(torch.float16, non_blocking=True)
        out = torch.empty_like(x_fp16)

        batch = x_fp16.shape[0]          # one CTA per batch element
        grid = (batch, 1, 1)
        block = (1, 1, 1)                # single thread per CTA

        args = [
            x_fp16.data_ptr(),
            self.ln.weight.data_ptr(),
            self.ln.bias.data_ptr(),
            out.data_ptr(),
            self.norm_size
        ]

        ptx_launch(self.module, "layernorm", grid, block, args)
        return out

