#   Architecture: RTX PRO 6000 Blackwell (sm_120a)

PTX_SOURCE = r"""
.version 8.7
.target sm_120a
.address_size 64

.visible .entry layernorm(
    .param .u64 layernorm_param_0,   // input  (half*)
    .param .u64 layernorm_param_1,   // output (half*)
    .param .u32 layernorm_param_2,   // batch  (int)
    .param .u32 layernorm_param_3,   // N (elements per batch element)
    .param .f32 layernorm_param_4    // eps
)
{
