    .reg .pred   %p<10>;
    .reg .b32    %r<30>;
    .reg .b64    %rd<30>;
    .reg .f32    %f<30>;
    .reg .f16    %h<5>;

    // Shared memory buffer (max 256 threads per block)
    .shared .align 4 .b32 sdata[256];

