    // Load kernel parameters
    ld.param.u64 %rdInPtr,   [layernorm_param_0];
    ld.param.u64 %rdOutPtr,  [layernorm_param_1];
    ld.param.u32 %rBatchCnt, [layernorm_param_2];
    ld.param.u32 %rN,        [layernorm_param_3];
    ld.param.f32 %fEps,      [layernorm_param_4];

