    // Determine which batch element this CTA processes
    mov.u32 %rBatchIdx, %ctaid.x;
    setp.ge.u32 %p0, %rBatchIdx, %rBatchCnt;
    @%p0 bra $L_exit;                     // out‑of‑range batch index

