    // Compute base addresses for this batch (byte offsets)
    // offsetElems = batchIdx * N   (64‑bit)
    mul.wide.s32 %rdOffsetElems, %rBatchIdx, %rN;
    // offsetBytes = offsetElems * 2 (half = 2 bytes)
    shl.b64 %rdOffsetBytes, %rdOffsetElems, 1;

    add.u64 %rdInBaseTmp, %rdInPtr, %rdOffsetBytes;
    add.u64 %rdOutBaseTmp, %rdOutPtr, %rdOffsetBytes;
    cvta.to.global.u64 %rdInBase,  %rdInBaseTmp;
    cvta.to.global.u64 %rdOutBase, %rdOutBaseTmp;

