    mul.wide.s32 %rdElemOff, %rIdx, 2;    // byte offset of element (2 bytes per half)
    add.u64 %rdElemAddr, %rdInBase, %rdElemOff;
    ld.global.f16 %h0, [%rdElemAddr];
    cvt.f32.f16 %f0, %h0;
    add.f32 %fSum, %fSum, %f0;

