    .param .u64 conv2d_fp16_param_1,   // weight  (96,3,11,11)
    .param .u64 conv2d_fp16_param_2,   // bias    (96)
    .param .u64 conv2d_fp16_param_3,   // output  (N,96,55,55)
    .param .u32 conv2d_fp16_param_4    // batch size N
)
{
    // -------------------- registers --------------------
    .reg .pred   %p<12>;
    .reg .b32    %r<64>;
    .reg .b64    %rd<30>;
    .reg .f32    %f<8>;
    .reg .f16    %h<8>;

    // -------------------- load parameters --------------------
    ld.param.u64    %rd1, [conv2d_fp16_param_0];   // input base
    ld.param.u64    %rd2, [conv2d_fp16_param_1];   // weight base
    ld.param.u64    %rd3, [conv2d_fp16_param_2];   // bias base
    ld.param.u64    %rd4, [conv2d_fp16_param_3];   // output base
    ld.param.u32    %r0,  [conv2d_fp16_param_4];   // N

    // -------------------- constants --------------------
    mov.u32 %r1, 96;      // C_out
    mov.u32 %r2, 55;      // H_out / W_out (square)
    mov.u32 %r3, 3;       // C_in
    mov.u32 %r4, 224;     // H_in / W_in (square)
    mov.u32 %r5, 11;      // K (kernel size)
    mov.u32 %r6, 4;       // stride
    mov.u32 %r7, 2;       // padding
    mov.u32 %r8, 2;       // element size in bytes (fp16)

    // -------------------- total output elements --------------------
    mul.lo.u32 %r9,  %r0, %r1;       // N * C_out
    mul.lo.u32 %r10, %r9, %r2;       // * H_out
    mul.lo.u32 %r11, %r10, %r2;      // * W_out  => total_out

    // -------------------- thread linear index --------------------
    mov.u32 %r12, %ctaid.x;
    mov.u32 %r13, %ntid.x;
    mov.u32 %r14, %tid.x;
    mad.lo.s32 %r15, %r12, %r13, %r14;   // global thread id

    // -------------------- bounds check --------------------
    setp.ge.s32 %p0, %r15, %r11;
    @%p0 bra $L_EXIT;

    // -------------------- decompose linear index --------------------
    // w = idx % W_out
    rem.u32 %r16, %r15, %r2;          // w
    // idx = idx / W_out
    div.u32 %r17, %r15, %r2;          // tmp1
    // h = tmp1 % H_out
    rem.u32 %r18, %r17, %r2;          // h
    // tmp2 = tmp1 / H_out
    div.u32 %r19, %r17, %r2;          // tmp2
    // oc = tmp2 % C_out
    rem.u32 %r20, %r19, %r1;          // oc
    // n = tmp2 / C_out
    div.u32 %r21, %r19, %r1;          // n

    // -------------------- compute input origin (top‑left of receptive field) --------------------
    mul.lo.u32 %r22, %r18, %r6;       // h * stride
    sub.s32    %r22, %r22, %r7;       // in_y = h*stride - pad
    mul.lo.u32 %r23, %r16, %r6;       // w * stride
    sub.s32    %r23, %r23, %r7;       // in_x = w*stride - pad

    // -------------------- convert generic pointers --------------------
    cvta.to.global.u64 %rd5, %rd1;    // input
    cvta.to.global.u64 %rd6, %rd2;    // weight
    cvta.to.global.u64 %rd7, %rd3;    // bias
    cvta.to.global.u64 %rd8, %rd4;    // output

    // -------------------- accumulator (fp32) --------------------
    mov.f32 %f0, 0.0;

    // -------------------- loop over input channels --------------------
    mov.u32 %r24, 0;                 // ic = 0
$IC_LOOP:
    setp.ge.s32 %p1, %r24, %r3;      // ic >= C_in ?
    @%p1 bra $IC_DONE;

        // loop over kernel height
        mov.u32 %r25, 0;             // kh = 0
$KH_LOOP:
        setp.ge.s32 %p2, %r25, %r5;  // kh >= K ?
        @%p2 bra $KH_DONE;

            // loop over kernel width
            mov.u32 %r26, 0;         // kw = 0
$KW_LOOP:
            setp.ge.s32 %p3, %r26, %r5;  // kw >= K ?
            @%p3 bra $KW_DONE;

                // iy = in_y + kh
                add.s32 %r27, %r22, %r25;
                // ix = in_x + kw
                add.s32 %r28, %r23, %r26;

                // ----- input bounds check -----
                setp.lt.s32 %p4, %r27, 0;        // iy < 0
                setp.ge.s32 %p5, %r27, %r4;      // iy >= H_in
                or.pred %p6, %p4, %p5;           // y out of bounds
                setp.lt.s32 %p7, %r28, 0;        // ix < 0
                setp.ge.s32 %p8, %r28, %r4;      // ix >= W_in
                or.pred %p9, %p7, %p8;           // x out of bounds
                or.pred %p10, %p6, %p9;          // any out of bounds
                @%p10 bra $KW_NEXT;               // skip this iteration

                // ----- compute input linear index -----
                // ((n*C_in + ic)*H_in + iy)*W_in + ix
                mul.lo.u32 %r29, %r21, %r3;       // n*C_in
                add.u32    %r30, %r29, %r24;      // + ic
                mul.lo.u32 %r31, %r30, %r4;       // * H_in
                add.u32    %r32, %r31, %r27;      // + iy
                mul.lo.u32 %r33, %r32, %r4;       // * W_in
                add.u32    %r34, %r33, %r28;      // + ix

                mul.wide.s32 %rd9, %r34, %r8;     // byte offset
                add.u64 %rd10, %rd5, %rd9;        // address
                ld.global.f16 %h0, [%rd10];

                // ----- compute weight linear index -----
                // ((oc*C_in + ic)*K + kh)*K + kw
                mul.lo.u32 %r35, %r20, %r3;       // oc*C_in
                add.u32    %r36, %r35, %r24;      // + ic
                mul.lo.u32 %r37, %r36, %r5;       // * K
                add.u32    %r38, %r37, %r25;      // + kh
                mul.lo.u32 %r39, %r38, %r5;       // * K
                add.u32    %r40, %r39, %r26;      // + kw

                mul.wide.s32 %rd11, %r40, %r8;    // byte offset
                add.u64 %rd12, %rd6, %rd11;       // address
                ld.global.f16 %h1, [%rd12];

                // ----- multiply‑accumulate (fp32) -----
                cvt.f32.f16 %f1, %h0;
                cvt.f32.f16 %f2, %h1;
                fma.rn.f32 %f0, %f1, %f2, %f0;   // f0 += f1*f2

$KW_NEXT:
                add.u32 %r26, %r26, 1;            // kw++
                bra $KW_LOOP;
$KW_DONE:
            // end kw loop
            add.u32 %r25, %r25, 1;                // kh++
            bra $KH_LOOP;
$KH_DONE:
        // end kh loop
        add.u32 %r24, %r24, 1;                    // ic++
        bra $IC_LOOP;
$IC_DONE:
    // -------------------- add bias --------------------
    mul.wide.s32 %rd13, %r20, %r8;                // bias offset = oc * 2
    add.u64 %rd14, %rd7, %rd13;
    ld.global.f16 %h2, [%rd14];
    cvt.f32.f16 %f3, %h2;
    add.f32 %f0, %f0, %f3;

    // -------------------- compute output linear index --------------------
    // ((n*C_out + oc)*H_out + h)*W_out + w
    mul.lo.u32 %r41, %r21, %r1;                  // n*C_out
    add.u32 %r42, %r41, %r20;                    // + oc
    mul.lo.u32 %r43, %r42, %r2;                  // * H_out
    add.u32 %r44, %r43, %r18;                    // + h
    mul.lo.u32 %r45, %r44, %r2;                  // * W_out
    add.u32 %r46, %r45, %r16;                    // + w

    mul.wide.s32 %rd15, %r46, %r8;               // byte offset
    add.u64 %rd16, %rd8, %rd15;                  // address

    // -------------------- store result (fp16) --------------------
    cvt.rn.f16.f32 %h3, %f0;
    st.global.f16 [%rd16], %h3;

$L_EXIT:
    ret;
}
"""

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        # Load the PTX module (ptx_load is provided by the harness)
        self.module = ptx_load(PTX_SOURCE)

    @property
    def weight(self):
        if not hasattr(self, "_weight"):
            self._weight = torch.nn.Parameter(
                torch.randn(96, 3, 11, 11, dtype=torch.float16, device="cuda")
            )
        return self._weight

    @property
    def bias(self):
        if not hasattr(self, "_bias"):
            self._bias = torch.nn.Parameter(
                torch.randn(96, dtype=torch.float16, device="cuda")
            )
        return self._bias

    def forward(self, x):
        # x: (N, 3, 224, 224) fp16 CUDA tensor
        N = x.size(0)
        out = torch.empty((N, 96, 55, 55), dtype=torch.float16, device=x.device)

        block = 256
        total_out = N * 96 * 55 * 55
        grid_x = (total_out + block - 1) // block
        grid = (grid_x, 1, 1)

        # Launch the PTX kernel (ptx_launch is provided by the harness)
        ptx_launch(
            self.module,
            "conv2d_fp16",
            grid,
            (block, 1, 1),
            [
                x.data_ptr(),
                self.weight.data_ptr(),
                self.bias.data_ptr(),
                out.data_ptr(),
                N,
            ],
        )
        return out

import torch

# PTX source for fp16 Conv2d (3‑in, 96‑out, 11×11, stride=4, padding=2) on sm_120a
PTX_SOURCE = r"""
.version 8.5
.target sm_120a
.address_size 64

.visible .entry conv2d_fp16(
    .param .u64   param_input,      // (N,3,H_in,W_in) fp16
    .param .u64   param_weight,    // (96,3,11,11) fp16
    .param .u64   param_bias,      // (96) fp16
    .param .u64   param_output,    // (N,96,H_out,W_out) fp16
    .param .u32   param_batch,     // N
    .param .u32   param_in_h,      // H_in
    .param .u32   param_in_w,      // W_in
    .param .u32   param_out_c,     // C_out (=96)
    .param .u32   param_out_h,     // H_out
    .param .u32   param_out_w,     // W_out
    .param .u32   param_total      // N*C_out*H_out*W_out
)
{
    .reg .pred  %p<10>;
    .reg .b32   %r<32>;
    .reg .b64   %rd<20>;
    .reg .f32   %f<8>;
    .reg .f16   %h<8>;

    // -------------------------------------------------------------
    // Load kernel parameters
    // -------------------------------------------------------------
    ld.param.u64    %rd1, [param_input];
    ld.param.u64    %rd2, [param_weight];
    ld.param.u64    %rd3, [param_bias];
    ld.param.u64    %rd4, [param_output];
    ld.param.u32    %r1,  [param_batch];
    ld.param.u32    %r2,  [param_in_h];
    ld.param.u32    %r3,  [param_in_w];
    ld.param.u32    %r4,  [param_out_c];
    ld.param.u32    %r5,  [param_out_h];
    ld.param.u32    %r6,  [param_out_w];
    ld.param.u32    %r7,  [param_total];

    // -------------------------------------------------------------
    // Compute linear thread index and bounds check
    // -------------------------------------------------------------
    mov.u32         %r8,  %ctaid.x;
    mov.u32         %r9,  %ntid.x;
    mov.u32         %r10, %tid.x;
    mad.lo.s32      %r11, %r8, %r9, %r10;          // linear thread id
    setp.ge.u32     %p0, %r11, %r7;               // if tid >= total -> exit
    @%p0 bra        $L_END;

    // -------------------------------------------------------------
    // Decompose linear index: batch, oc, oy, ox
    // -------------------------------------------------------------
    // oc = idx % C_out
    rem.u32         %r12, %r11, %r4;
    // tmp = idx / C_out
    div.u32         %r13, %r11, %r4;

    // oy = tmp % H_out
    rem.u32         %r14, %r13, %r5;
    // tmp2 = tmp / H_out
    div.u32         %r15, %r13, %r5;

    // ox = tmp2 % W_out
    rem.u32         %r16, %r15, %r6;
    // batch = tmp2 / W_out
    div.u32         %r17, %r15, %r6;

    // -------------------------------------------------------------
    // Convert generic pointers to global address space
    // -------------------------------------------------------------
    cvta.to.global.u64 %rd5, %rd1;   // input base
    cvta.to.global.u64 %rd6, %rd2;   // weight base
    cvta.to.global.u64 %rd7, %rd3;   // bias base
    cvta.to.global.u64 %rd8, %rd4;   // output base

    // -------------------------------------------------------------
    // Load bias for this output channel (fp16 -> fp32)
    // -------------------------------------------------------------
    mul.wide.s32    %rd9, %r12, 2;               // bias offset bytes
    add.s64         %rd10, %rd7, %rd9;
    ld.global.f16   %h0, [%rd10];
    cvt.f32.f16     %f0, %h0;                    // accumulator = bias

    // -------------------------------------------------------------
    // Loop over input channels (C_in = 3)
    // -------------------------------------------------------------
    mov.u32 %r18, 0;                 // ic = 0
$L_IC_LOOP:
    setp.ge.u32 %p1, %r18, 3;       // if ic >= 3 exit
    @%p1 bra $L_IC_LOOP_END;

    // Loop over kernel rows (ky = 0 .. 10)
    mov.u32 %r19, 0;                 // ky = 0
$L_KY_LOOP:
    setp.ge.u32 %p2, %r19, 11;      // ky >= 11 ?
    @%p2 bra $L_KY_LOOP_END;

    // compute input y coordinate: iy = oy*4 - 2 + ky
    mul.lo.s32 %r20, %r14, 4;       // oy*stride
    sub.s32    %r20, %r20, 2;       // -pad
    add.s32    %r20, %r20, %r19;    // +ky

    // Loop over kernel cols (kx = 0 .. 10)
    mov.u32 %r21, 0;                 // kx = 0
$L_KX_LOOP:
    setp.ge.u32 %p3, %r21, 11;      // kx >= 11 ?
    @%p3 bra $L_KX_LOOP_END;

    // compute input x coordinate: ix = ox*4 - 2 + kx
    mul.lo.s32 %r22, %r16, 4;       // ox*stride
    sub.s32    %r22, %r22, 2;       // -pad
    add.s32    %r22, %r22, %r21;    // +kx

    // -------------------------------------------------------------
    // Bounds check: 0 <= iy < H_in  && 0 <= ix < W_in
    // -------------------------------------------------------------
    setp.ge.s32 %p4, %r20, 0;       // iy >= 0
    setp.lt.s32 %p5, %r20, %r2;     // iy < H_in
    and.pred   %p4, %p4, %p5;       // iy valid?

    setp.ge.s32 %p5, %r22, 0;       // ix >= 0
    setp.lt.s32 %p6, %r22, %r3;     // ix < W_in
    and.pred   %p5, %p5, %p6;       // ix valid?

    and.pred   %p4, %p4, %p5;       // overall valid?
    @!%p4 bra $L_KX_NEXT;          // skip if out of bounds

    // -------------------------------------------------------------
    // Load input element (fp16 -> fp32)
    // -------------------------------------------------------------
    // input offset = ((batch*C_in + ic)*H_in + iy)*W_in + ix
    mul.lo.s32 %r23, %r17, 3;       // batch * C_in
    add.s32    %r23, %r23, %r18;    // + ic
    mul.lo.s32 %r24, %r23, %r2;     // * H_in
    add.s32    %r24, %r24, %r20;    // + iy
    mul.lo.s32 %r24, %r24, %r3;     // * W_in
    add.s32    %r24, %r24, %r22;    // + ix

    mul.wide.s32 %rd11, %r24, 2;    // bytes offset
    add.s64    %rd12, %rd5, %rd11;
    ld.global.f16 %h1, [%rd12];
    cvt.f32.f16 %f1, %h1;           // input_f32

    // -------------------------------------------------------------
    // Load weight element (fp16 -> fp32)
    // -------------------------------------------------------------
    // weight offset = ((oc*C_in + ic)*K + ky)*K + kx
    mul.lo.s32 %r25, %r12, 3;       // oc * C_in
    add.s32    %r25, %r25, %r18;    // + ic
    mul.lo.s32 %r25, %r25, 11;      // * K
    add.s32    %r25, %r25, %r19;    // + ky
    mul.lo.s32 %r25, %r25, 11;      // * K
    add.s32    %r25, %r25, %r21;    // + kx

    mul.wide.s32 %rd13, %r25, 2;    // bytes offset
    add.s64    %rd14, %rd6, %rd13;
    ld.global.f16 %h2, [%rd14];
    cvt.f32.f16 %f2, %h2;           // weight_f32

    // -------------------------------------------------------------
    // Accumulate: acc += weight * input
    // -------------------------------------------------------------
    fma.rn.f32 %f0, %f2, %f1, %f0;  // f0 = f2*f1 + f0

$L_KX_NEXT:
    add.u32 %r21, %r21, 1;          // kx++
    bra $L_KX_LOOP;

$L_KX_LOOP_END:
    add.u32 %r19, %r19, 1;          // ky++
    bra $L_KY_LOOP;

$L_KY_LOOP_END:
    add.u32 %r18, %r18, 1;          // ic++
    bra $L_IC_LOOP;

$L_IC_LOOP_END:
    // -------------------------------------------------------------
    // Store result (fp32 -> fp16)
    // -------------------------------------------------------------
    cvt.rn.f16.f32 %h0, %f0;        // final output half

    // output offset = ((batch*C_out + oc)*H_out + oy)*W_out + ox
    mul.lo.s32 %r26, %r17, %r4;     // batch * C_out
    add.s32    %r26, %r26, %r12;    // + oc
    mul.lo.s32 %r27, %r26, %r5;     // * H_out
    add.s32    %r27, %r27, %r14;    // + oy
    mul.lo.s32 %r27, %r27, %r6;     // * W_out
    add.s32    %r27, %r27, %r16;    // + ox

    mul.wide.s32 %rd15, %r27, 2;    // byte offset
    add.s64    %rd16, %rd8, %rd15;
    st.global.f16 [%rd16], %h0;

$L_END:
    ret;
}
"""

class ModelNew(torch.nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        # fp16 weight & bias on device (random init)
        self.weight = torch.randn(96, 3, 11, 11, dtype=torch.float16, device='cuda')
        self.bias   = torch.randn(96, dtype=torch.float16, device='cuda')
        # Load PTX module
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x):
        # x: (N,3,224,224) fp16
        N, C_in, H_in, W_in = x.shape
        C_out = self.weight.shape[0]
        H_out = (H_in + 2*2 - 11) // 4 + 1   # =55
        W_out = (W_in + 2*2 - 11) // 4 + 1   # =55

        out = torch.empty((N, C_out, H_out, W_out), dtype=torch.float16, device='cuda')
        total = N * C_out * H_out * W_out

        block = 256
        grid_x = (total + block - 1) // block
        grid = (grid_x, 1, 1)

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            self.bias.data_ptr(),
            out.data_ptr(),
            N,
            H_in,
            W_in,
            C_out,
            H_out,
            W_out,
            total
        ]

        ptx_launch(self.module, "conv2d_fp16", grid, (block, 1, 1), args)
        return out

