# PTX source for fp16 Conv2d (3→96, kernel=11, stride=4, padding=2) on RTX PRO 6000 Blackwell
PTX_SOURCE = r"""
.version 8.7
.target sm_120a
.address_size 64

.visible .const .u32 IN_C      = 3;
.visible .const .u32 OUT_C     = 96;
.visible .const .u32 IN_H      = 224;
.visible .const .u32 IN_W      = 224;
.visible .const .u32 KSIZE     = 11;
.visible .const .u32 STRIDE    = 4;
.visible .const .u32 PADDING   = 2;
.visible .const .u32 OUT_H     = 55;        // (224 + 2*2 - 11)/4 + 1
.visible .const .u32 OUT_W     = 55;
.visible .const .u32 PER_BATCH = OUT_C * OUT_H * OUT_W; // 96*55*55 = 290400
.visible .const .u32 OHOW      = OUT_H * OUT_W;          // 55*55 = 3025

.visible .entry conv2d_fp16(
    .param .u64 param_0,    // input   (B,3,224,224) fp16
    .param .u64 param_1,    // weight  (96,3,11,11) fp16
    .param .u64 param_2,    // bias    (96)        fp16
    .param .u64 param_3,    // output  (B,96,55,55)fp16
    .param .u32 param_4     // total output elements (int32)
)
{
    .reg .pred  %p<7>;
    .reg .b32   %r<45>;
    .reg .b64   %rd<15>;
    .reg .f32   %f<6>;
    .reg .f16   %h<4>;

    // -----------------------------------------------------------------
    // Load kernel parameters (generic pointers and total size)
    // -----------------------------------------------------------------
    ld.param.u64    %rd0, [param_0];
    ld.param.u64    %rd1, [param_1];
    ld.param.u64    %rd2, [param_2];
    ld.param.u64    %rd3, [param_3];
    ld.param.u32    %r0,  [param_4];          // total output elements

    // Convert generic pointers to global address space
    cvta.to.global.u64 %rd_input , %rd0;
    cvta.to.global.u64 %rd_weight, %rd1;
    cvta.to.global.u64 %rd_bias  , %rd2;
    cvta.to.global.u64 %rd_output, %rd3;

    // -----------------------------------------------------------------
    // Compute linear thread ID and bounds check
    // -----------------------------------------------------------------
    mov.u32         %r1, %ctaid.x;          // blockIdx.x
    mov.u32         %r2, %ntid.x;           // blockDim.x
    mov.u32         %r3, %tid.x;            // threadIdx.x
    mad.lo.s32      %r4, %r1, %r2, %r3;     // gid = blockIdx.x * blockDim.x + threadIdx.x

    setp.ge.s32 %p0, %r4, %r0;               // if (gid >= total) exit
    @%p0 bra $L_DONE;

    // -----------------------------------------------------------------
    // Decompose gid into batch, output channel, and spatial location
    // -----------------------------------------------------------------
    div.s32 %r5, %r4, PER_BATCH;          // batch index b
    rem.s32 %r6, %r4, PER_BATCH;          // offset inside batch

    div.s32 %r7, %r6, OHOW;               // output channel oc
    rem.s32 %r8, %r6, OHOW;               // remainder = oy*OUT_W + ox

    div.s32 %r9, %r8, OUT_W;              // output y (oy)
    rem.s32 %r10, %r8, OUT_W;             // output x (ox)

    // -----------------------------------------------------------------
    // Load bias for this output channel (fp16 -> fp32)
    // -----------------------------------------------------------------
    mul.wide.s32 %rd4, %r7, 2;            // bias offset (bytes)
    add.s64 %rd5, %rd_bias, %rd4;
    ld.global.f16 %h0, [%rd5];
    cvt.f32.f16 %f0, %h0;                 // accumulator = bias (fp32)

    // -----------------------------------------------------------------
