    mov.u32         %r5, %ctaid.x;          // blockIdx.x
    mov.u32         %r6, %ntid.x;           // blockDim.x
    mov.u32         %r7, %tid.x;            // threadIdx.x
    mad.lo.s32      %r8, %r5, %r6, %r7;     // linear thread id

