    cvta.to.global.u64 %rd3, %rd1;         // input base
    cvta.to.global.u64 %rd4, %rd2;         // output base

    //--- Compute base offset for this row (in elements) ---------------
    // row_offset = thread_id * cols
    mul.lo.u32      %r10, %r8, %r4;

