.version 8.5
.target sm_120a
.address_size 64

.visible .entry argmax_kernel(
    .param .u64 in_ptr,          // fp16 input tensor (contiguous)
    .param .u64 out_ptr,         // int64 output tensor (indices)
    .param .u32 n_out,           // total number of output elements (product of all dims except reduced)
    .param .u32 k,               // size of the reduced dimension
    .param .u32 inner_stride     // product of dimensions after the reduced dim (in elements)
)
