    // Load kernel arguments
    ld.param.u64    %rd1, [in_ptr];
    ld.param.u64    %rd2, [out_ptr];
    ld.param.u32    %r2,  [n_out];
    ld.param.u32    %r3,  [k];
    ld.param.u32    %r4,  [inner_stride];

