    // Compute global linear thread id: tid = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32         %r5, %ctaid.x;
    mov.u32         %r6, %ntid.x;
    mov.u32         %r7, %tid.x;
    mad.lo.s32      %r0, %r5, %r6, %r7;        // %r0 = tid

