    // offset = outer * slice_bytes + inner_off * 2
    mul.wide.u32    %rd6, %r9, %rd5;           // outer * slice_bytes
    shl.b32         %r10, %r10, 1;            // inner_off * 2 (bytes)
    cvt.u64.u32     %rd7, %r10;
    add.u64         %rd8, %rd6, %rd7;          // total byte offset from input base

    add.u64         %rd9, %rd3, %rd8;          // address of first fp16 element for this thread

