    // Load the first element as initial maximum
    ld.global.f16   %h1, [%rd9];
    cvt.f32.f16     %f1, %h1;                 // current max value (f32)
    mov.u32         %r11, 0;                  // current max index within reduced dim

    // -------------------------------------------------
    // Loop over remaining elements i = 1 .. k-1
    mov.u32         %r12, 1;                  // loop counter i
$LOOP_START:
    setp.ge.u32     %p1, %r12, %r3;           // if i >= k exit loop
    @%p1 bra        $LOOP_END;

