    mul.wide.u32    %rd10, %r12, %r8;         // i * inner_bytes (bytes)
    add.u64         %rd11, %rd9, %rd10;       // address of element i

    ld.global.f16   %h2, [%rd11];
    cvt.f32.f16     %f2, %h2;

