    setp.lt.f32     %p2, %f1, %f2;            // (f1 < f2) ?
    @%p2 mov.f32   %f1, %f2;
    @%p2 mov.u32   %r11, %r12;

    // i++
    add.u32         %r12, %r12, 1;
    bra             $LOOP_START;
$LOOP_END:

    // -------------------------------------------------
    // Store the resulting index (int64) to output
    // output offset = tid * 8 (bytes per int64)
    mul.wide.u32    %rd12, %r0, 8;            // byte offset for output element
    add.u64         %rd13, %rd4, %rd12;       // address of output element
    cvt.u64.u32     %rd14, %r11;              // zero‑extend index to 64‑bit
    st.global.u64   [%rd13], %rd14;

