    PTX‑based argmax for fp16 tensors, reducing over a user‑specified dimension.
    """
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim
        # Load the PTX module (ptx_load is provided by the harness)
        self.module = ptx_load(PTX_SOURCE)

