            self.module,
            "argmax_kernel",
            grid,
            (threads_per_block, 1, 1),
            [
                int(x.data_ptr()),   # input pointer (fp16)
                int(out.data_ptr()), # output pointer (int64)
                int(n_out),          # total output elements
                int(k),              # size of reduced dimension
                int(inner_stride)    # inner stride (in elements)
            ]
        )
        return out

