        # reference conv3d to obtain weight values (fp16)
        ref = nn.Conv3d(in_channels,
                        out_channels,
                        kernel_size=(kernel_size, kernel_size, kernel_size),
                        stride=stride,
                        padding=padding,
                        dilation=dilation,
                        groups=groups,
                        bias=bias)
        self.weight = nn.Parameter(ref.weight.detach().clone().half().contiguous())
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.kernel_size = kernel_size

