            self.weight.data_ptr(),
            out.data_ptr(),
            N,
            Cin,
            Cout,
            D_in,
            H_in,
            W_in,
            D_out,
            H_out,
            W_out,
            self.kernel_size,
            self.stride,
            self.padding,
            self.dilation,
            self.groups
        ]

        ptx_launch(self.module,
                   "conv3d_fp16",
                   grid,
                   (block, 1, 1),
                   args)

        return out

