    div.u32         %r_tmp, %r_tmp, %r_H_out;

    // oc = tmp % out_channels
    rem.u32         %r_oc, %r_tmp, %r_out_ch;
    div.u32         %r_batch_idx, %r_tmp, %r_out_ch;   // batch index

    // group id for this output channel
    div.u32         %r_group, %r_oc, %r_out_ch_pg;   // 0 .. groups-1

    // base input channel for this group
    mul.lo.u32      %r_in_c_base, %r_group, %r_in_ch_pg;

    // ---------- accumulator (float32) ----------
    mov.f32         %f0, 0.0;

    // ---------- loop over input channels within group ----------
    mov.u32         %r_in_c_off, 0;
$L_IN_C_LOOP:
    setp.ge.u32     %p1, %r_in_c_off, %r_in_ch_pg;
    @%p1 bra        $L_AFTER_IN_C_LOOP;          // exit if done

    // actual input channel index
    add.u32         %r_in_c, %r_in_c_base, %r_in_c_off;

    // ---------- loop over kernel height ----------
    mov.u32         %r_kh, 0;
$L_KH_LOOP:
    setp.ge.u32     %p2, %r_kh, %r_KH;
    @%p2 bra        $L_AFTER_KH_LOOP;

    // compute input y coordinate candidate: y_numer = oh + pad - kh
    add.u32         %r_y_tmp, %r_oh, %r_pad;
    sub.u32         %r_y_numer, %r_y_tmp, %r_kh;

    // check stride divisibility for y
    rem.u32         %r_mod_y, %r_y_numer, %r_stride;
    setp.ne.u32     %p3, %r_mod_y, 0;
    @%p3 bra        $L_KH_NEXT;         // not aligned, skip

    // y_in = y_numer / stride
    div.u32         %r_y_in, %r_y_numer, %r_stride;
    // check bounds 0 <= y_in < H_in
    setp.lt.u32     %p4, %r_y_in, %r_H_in;
    @!%p4 bra       $L_KH_NEXT;

    // ---------- loop over kernel width ----------
    mov.u32         %r_kw, 0;
$L_KW_LOOP:
    setp.ge.u32     %p5, %r_kw, %r_KW;
    @%p5 bra        $L_KW_NEXT;        // exit kw loop

    // compute input x coordinate candidate
    add.u32         %r_x_tmp, %r_ow, %r_pad;
    sub.u32         %r_x_numer, %r_x_tmp, %r_kw;

    // check stride divisibility for x
    rem.u32         %r_mod_x, %r_x_numer, %r_stride;
    setp.ne.u32     %p6, %r_mod_x, 0;
    @%p6 bra        $L_KW_INC;            // not aligned, skip

    // x_in = x_numer / stride
    div.u32         %r_x_in, %r_x_numer, %r_stride;
    // check bounds 0 <= x_in < W_in
    setp.lt.u32     %p7, %r_x_in, %r_W_in;
    @!%p7 bra       $L_KW_INC;

    // ----------- load input element ----------
    // offset = ((b * in_ch + in_c) * H_in + y_in) * W_in + x_in
    mul.lo.u32      %r_tmp1, %r_batch_idx, %r_in_ch;
    add.u32         %r_tmp1, %r_tmp1, %r_in_c;
    mul.lo.u32      %r_tmp1, %r_tmp1, %r_H_in;
    add.u32         %r_tmp1, %r_tmp1, %r_y_in;
    mul.lo.u32      %r_tmp1, %r_tmp1, %r_W_in;
    add.u32         %r_tmp1, %r_tmp1, %r_x_in;
    mul.wide.u32    %rd_off_in, %r_tmp1, 2;      // *sizeof(fp16)

    cvta.to.global.u64 %rd_in_ptr, %rd1;
    add.u64         %rd_addr_in, %rd_in_ptr, %rd_off_in;
    ld.global.f16   %h0, [%rd_addr_in];
    cvt.f32.f16     %f1, %h0;                     // input as fp32

    // ----------- load weight element ----------
    // weight layout: (out_ch, in_ch_per_group, KH, KW)
    // offset = ((oc * in_ch_pg + (in_c - in_c_base)) * KH + kh) * KW + kw
    sub.u32         %r_in_c_rel, %r_in_c, %r_in_c_base;
    mul.lo.u32      %r_tmp2, %r_oc, %r_in_ch_pg;
    add.u32         %r_tmp2, %r_tmp2, %r_in_c_rel;
    mul.lo.u32      %r_tmp2, %r_tmp2, %r_KH;
    add.u32         %r_tmp2, %r_tmp2, %r_kh;
    mul.lo.u32      %r_tmp2, %r_tmp2, %r_KW;
    add.u32         %r_tmp2, %r_tmp2, %r_kw;
    mul.wide.u32    %rd_off_wt, %r_tmp2, 2;

    cvta.to.global.u64 %rd_wt_ptr, %rd2;
    add.u64         %rd_addr_wt, %rd_wt_ptr, %rd_off_wt;
    ld.global.f16   %h1, [%rd_addr_wt];
    cvt.f32.f16     %f2, %h1;                     // weight as fp32

    // ----------- multiply-accumulate ----------
    fma.rn.f32      %f0, %f1, %f2, %f0;           // acc += in * w

$L_KW_INC:
    add.u32         %r_kw, %r_kw, 1;
    bra             $L_KW_LOOP;
$L_KW_NEXT:
    // continue with next kh
    add.u32         %r_kh, %r_kh, 1;
    bra             $L_KH_LOOP;
$L_KH_NEXT:
    // next input channel
    add.u32         %r_in_c_off, %r_in_c_off, 1;
    bra             $L_IN_C_LOOP;

$L_AFTER_IN_C_LOOP:
    // ---------- write output ----------
    // convert accumulator to fp16
    cvt.rn.f16.f32  %h2, %f0;

    // output offset = ((b * out_ch + oc) * H_out + oh) * W_out + ow
    mul.lo.u32      %r_tmp3, %r_batch_idx, %r_out_ch;
    add.u32         %r_tmp3, %r_tmp3, %r_oc;
    mul.lo.u32      %r_tmp3, %r_tmp3, %r_H_out;
    add.u32         %r_tmp3, %r_tmp3, %r_oh;
    mul.lo.u32      %r_tmp3, %r_tmp3, %r_W_out;
    add.u32         %r_tmp3, %r_tmp3, %r_ow;
    mul.wide.u32    %rd_off_out, %r_tmp3, 2;

    cvta.to.global.u64 %rd_out_ptr, %rd3;
    add.u64         %rd_addr_out, %rd_out_ptr, %rd_off_out;
    st.global.f16   [%rd_addr_out], %h2;

$L_EXIT:
    ret;
}
"""

class ModelNew(nn.Module):
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 output_padding: int = 0,
                 groups: int = 1,
                 bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.bias = bias

        # weight tensor in fp16 matching PyTorch ConvTranspose2d layout
        self.weight = torch.nn.Parameter(
            torch.randn(
                out_channels,
                in_channels // groups,
                kernel_size,
                kernel_size,
                dtype=torch.float16,
                device='cuda'
            )
        )
        if bias:
            self.bias_param = torch.nn.Parameter(
                torch.randn(out_channels, dtype=torch.float16, device='cuda')
            )
        else:
            self.register_parameter('bias_param', None)

        # load PTX module
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # ensure fp16
        x = x.to(dtype=torch.float16, device='cuda')
        batch, _, H_in, W_in = x.shape
        K = self.kernel_size
        S = self.stride
        P = self.padding
        OP = self.output_padding
        G = self.groups

        # compute output dimensions (same as torch.nn.ConvTranspose2d)
        H_out = (H_in - 1) * S - 2 * P + K + OP
        W_out = (W_in - 1) * S - 2 * P + K + OP

        out = torch.empty(
            batch,
            self.out_channels,
            H_out,
            W_out,
            dtype=torch.float16,
            device='cuda'
        )

        # launch configuration (1D grid)
        total = batch * self.out_channels * H_out * W_out
        block = 256
        grid_x = (total + block - 1) // block
        grid = (grid_x, 1, 1)

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            out.data_ptr(),
            batch,
            self.in_channels,
            self.out_channels,
            H_in,
            W_in,
            H_out,
            W_out,
            K,          # KH
            K,          # KW (square kernel)
            S,          # stride
            P,          # padding
            G           # groups
        ]

        ptx_launch(self.module, "conv_transpose2d_fp16", grid, (block, 1, 1), args)

        if self.bias:
            out = out + self.bias_param.view(1, -1, 1, 1)

        return out

