    .param .u32 in_channels,
    .param .u32 out_channels,
    .param .u32 H_in,
    .param .u32 W_in,
    .param .u32 K,
    .param .u32 H_out,
    .param .u32 W_out,
    .param .u32 N
)
{
    // ---------------------------------------------------------------
    // Register declarations
    // ---------------------------------------------------------------
    .reg .pred  %p<13>;
    .reg .b32   %r<32>;
    .reg .b64   %rd<39>;
    .reg .f32   %f<6>;
    .reg .f16   %h<4>;

    // ---------------------------------------------------------------
    // Load kernel parameters
    // ---------------------------------------------------------------
    ld.param.u64   %rd1, [input_ptr];
    ld.param.u64   %rd2, [weight_ptr];
    ld.param.u64   %rd3, [output_ptr];
    ld.param.u32   %r2,  [batch];
    ld.param.u32   %r3,  [in_channels];
    ld.param.u32   %r4,  [out_channels];
    ld.param.u32   %r5,  [H_in];
    ld.param.u32   %r6,  [W_in];
    ld.param.u32   %r7,  [K];
    ld.param.u32   %r8,  [H_out];
    ld.param.u32   %r9,  [W_out];
    ld.param.u32   %r10, [N];

