    mov.u32        %r1, %ntid.x;
    mov.u32        %r11,%tid.x;
    mad.lo.s32     %r12,%r0,%r1,%r11;          // %r12 = linear thread id

    // ---------------------------------------------------------------
    // Bounds check
    // ---------------------------------------------------------------
    setp.ge.u32    %p0, %r12, %r10;
    @%p0           bra $L_EXIT;

    // ---------------------------------------------------------------
    // Decompose linear index -> (b, oc, oy, ox)
    // ---------------------------------------------------------------
    mov.u32        %r13, %r12;                // tmp = idx

    rem.u32        %r14, %r13, %r9;           // ox = idx % W_out
    mov.u32        %r15, %r14;                // ox
    div.u32        %r13, %r13, %r9;           // idx /= W_out

    rem.u32        %r14, %r13, %r8;           // oy = idx % H_out
    mov.u32        %r16, %r14;                // oy
    div.u32        %r13, %r13, %r8;           // idx /= H_out

    rem.u32        %r14, %r13, %r4;           // oc = idx % out_channels
    mov.u32        %r17, %r14;                // oc
    div.u32        %r13, %r13, %r4;           // idx /= out_channels

    mov.u32        %r18, %r13;                // batch index (b)

    // ---------------------------------------------------------------
    // Compute output element byte offset (fp16 -> 2 bytes)
    // offset = ((b*outC + oc)*H_out + oy)*W_out + ox
    // ---------------------------------------------------------------
    mul.wide.u32   %rd4, %r18, %r4;           // b * out_channels
    cvt.u64.u32    %rd5, %r17;                // oc as 64-bit
    add.u64        %rd6, %rd4, %rd5;          // + oc
    mul.wide.u32   %rd7, %rd6, %r8;           // * H_out
    cvt.u64.u32    %rd8, %r16;                // oy as 64-bit
    add.u64        %rd9, %rd7, %rd8;          // + oy
    mul.wide.u32   %rd10, %rd9, %r9;          // * W_out
    cvt.u64.u32    %rd11, %r15;               // ox as 64-bit
    add.u64        %rd12, %rd10, %rd11;       // + ox (element index)
    shl.b64        %rd13, %rd12, 1;           // *2 -> byte offset

