$L_IC_LOOP:
    setp.ge.u32    %p1, %r19, %r3;
    @%p1           bra $L_IC_END;

    // Loop over kernel rows (ky)
    mov.u32        %r20, 0;                  // ky = 0
$L_KY_LOOP:
    setp.ge.u32    %p2, %r20, %r7;
    @%p2           bra $L_KY_END;

