$L_KX_LOOP:
    setp.ge.u32    %p6, %r22, %r7;
    @%p6           bra $L_KX_END;

    // ix = ox - kx
    sub.s32        %r23, %r15, %r22;
    // Bounds check for ix
    setp.lt.u32    %p7, %r23, 0;
    setp.ge.u32    %p8, %r23, %r6;
    or.pred        %p9, %p7, %p8;
    @%p9           bra $L_KX_CONT;

