    mul.wide.u32   %rd17, %r18, %r3;          // b*in_channels
    cvt.u64.u32    %rd18, %r19;               // ic as 64-bit
    add.u64        %rd19, %rd17, %rd18;       // + ic
    mul.wide.u32   %rd20, %rd19, %r5;         // * H_in
    cvt.u64.u32    %rd21, %r21;               // iy as 64-bit
    add.u64        %rd22, %rd20, %rd21;       // + iy
    mul.wide.u32   %rd23, %rd22, %r6;         // * W_in
    cvt.u64.u32    %rd24, %r23;               // ix as 64-bit
    add.u64        %rd25, %rd23, %rd24;       // + ix
    shl.b64        %rd26, %rd25, 1;           // byte offset
    add.u64        %rd27, %rd14, %rd26;       // address
    ld.global.f16  %h0, [%rd27];
    cvt.f32.f16    %f1, %h0;

