    // Load weight element (fp16) -> fp32
    // --------------------------------------------------------------
    // idx_w = ((ic*outC + oc)*K + ky)*K + kx
    mul.wide.u32   %rd28, %r19, %r4;          // ic*out_channels
    cvt.u64.u32    %rd29, %r17;               // oc as 64-bit
    add.u64        %rd30, %rd28, %rd29;       // + oc
    mul.wide.u32   %rd31, %rd30, %r7;         // * K
    cvt.u64.u32    %rd32, %r20;               // ky as 64-bit
    add.u64        %rd33, %rd31, %rd32;       // + ky
    mul.wide.u32   %rd34, %rd33, %r7;         // * K
    cvt.u64.u32    %rd35, %r22;               // kx as 64-bit
    add.u64        %rd36, %rd34, %rd35;       // + kx
    shl.b64        %rd37, %rd36, 1;           // byte offset
    add.u64        %rd38, %rd15, %rd37;       // address
    ld.global.f16  %h1, [%rd38];
    cvt.f32.f16    %f2, %h1;

    // --------------------------------------------------------------
    // Accumulate
    // --------------------------------------------------------------
    fma.rn.f32     %f0, %f1, %f2, %f0;

$L_KX_CONT:
    add.u32        %r22, %r22, 1;
    bra            $L_KX_LOOP;
$L_KX_END:

    // Next ky
    add.u32        %r20, %r20, 1;
    bra            $L_KY_LOOP;
$L_KY_END:

    // Next ic
    add.u32        %r19, %r19, 1;
    bra            $L_IC_LOOP;
$L_IC_END:

