    // Write back result (fp32 -> fp16)
    // ---------------------------------------------------------------
    cvt.rn.f16.f32 %h2, %f0;
    add.u64        %rd39, %rd16, %rd13;
    st.global.f16  [%rd39], %h2;

$L_EXIT:
    ret;
