            self.weight_fp16.data_ptr(),
            out.data_ptr(),
            batch,
            in_c,
            self.conv.out_channels,
            H_in,
            W_in,
            K,
            H_out,
            W_out,
            N
        ]

        ptx_launch(self.module, "conv_transpose2d_fp16", grid, (block, 1, 1), args)
        return out

