    stride=stride, padding=padding, groups=in_channels, bias=bias).
    """
    def __init__(self, in_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, bias: bool = False):
        super().__init__()
        # Initialize reference conv to obtain weights/bias in fp16
        ref = nn.Conv2d(in_channels, in_channels, kernel_size,
                        stride=stride, padding=padding,
                        groups=in_channels, bias=bias)
        self.weight = ref.weight.detach().contiguous().half()
        self.bias = (ref.bias.detach().contiguous().half()
                     if bias else None)

        self.module = ptx_load(PTX_SOURCE)

        self.stride = stride
        self.padding = padding
        self.kernel_size = kernel_size
        self.bias_flag = 1 if bias else 0

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        N, C, H, W = x.shape
        K = self.kernel_size
        s = self.stride
        p = self.padding

        H_out = (H + 2 * p - K) // s + 1
        W_out = (W + 2 * p - K) // s + 1

        out = torch.empty((N, C, H_out, W_out),
                          dtype=torch.float16,
                          device=x.device)

        total = N * C * H_out * W_out
        block = 256
        grid_x = (total + block - 1) // block
        grid = (grid_x, 1, 1)

        bias_ptr = self.bias.data_ptr() if self.bias is not None else 0

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            bias_ptr,
            out.data_ptr(),
            N, C, H, W,
            K, s, p,
            self.bias_flag,
            H_out, W_out
        ]

        ptx_launch(self.module, "depthwise_conv2d", grid, (block, 1, 1), args)
        return out

