                                 dtype=torch.float16, device='cuda')
        torch.nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

        if self.bias:
            self.bias_param = torch.empty(in_channels, dtype=torch.float16,
                                          device='cuda')
            fan_in = kernel_size * kernel_size
            bound = 1.0 / math.sqrt(fan_in)
            torch.nn.init.uniform_(self.bias_param, -bound, bound)
        else:
            self.bias_param = None

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        N, C, H, W = x.shape
        K = self.kernel_size
        S = self.stride
        P = self.padding
        H_out = (H + 2 * P - K) // S + 1
        W_out = (W + 2 * P - K) // S + 1

        out = torch.empty(N, C, H_out, W_out,
                          dtype=torch.float16, device='cuda')

        total = N * C * H_out * W_out
        block = 256
        grid_x = (total + block - 1) // block
        grid = (grid_x, 1, 1)

