            x.data_ptr(),
            self.weight.data_ptr(),
            self.bias_param.data_ptr() if self.bias else 0,
            out.data_ptr(),
            N,
            C,
            H,
            W,
            K,
            S,
            P,
            H_out,
            W_out,
            int(self.bias)   # bias_flag
        ]

        ptx_launch(self.module, "depthwise_conv2d", grid, (block, 1, 1), args)
        return out

