import torch
import torch.nn as nn
import tilelang
import tilelang.language as T


def build_relu_kernel(M: int, N: int, block_M: int = 128, block_N: int = 256,
                      threads: int = 128, dtype: str = "float16"):

    @T.prim_func
    def relu_kernel(
        A: T.Tensor((M, N), dtype),
        B: T.Tensor((M, N), dtype),
    ):
        with T.Kernel(T.ceildiv(N, block_N), T.ceildiv(M, block_M), threads=threads) as (bx, by):
            A_shared = T.alloc_shared((block_M, block_N), dtype)
            B_local = T.alloc_fragment((block_M, block_N), dtype)

            # Load data into shared memory
            T.copy(A[by * block_M, bx * block_N], A_shared)

            # Apply ReLU operation
            for i, j in T.Parallel(block_M, block_N):
                B_local[i, j] = T.max(A_shared[i, j], T.float16(0.0))

            # Copy result back to global memory
            T.copy(B_local, B[by * block_M, bx * block_N])

    return tilelang.compile(relu_kernel, out_idx=[1], target="cuda")


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._kernel_cache = {}

    def _get_kernel(self, M: int, N: int, dtype: str):
        key = (M, N, dtype)
        if key not in self._kernel_cache:
            self._kernel_cache[key] = build_relu_kernel(M, N, dtype=dtype)
        return self._kernel_cache[key]

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x_c = x.contiguous()
        original_shape = x_c.shape
        x_c = x_c.view(-1, x_c.size(-1))
        M, N = x_c.shape
        kernel = self._get_kernel(M, N, "float16")
        y = kernel(x_c)
        return y.view(original_shape)

