def build_reduce_sum_kernel(M: int, N: int, K: int, reduce_dim: int, block_M: int = 128, block_N: int = 256,
                            block_K: int = 128, threads: int = 128, dtype: str = "float16"):

    @T.prim_func
    def reduce_sum_kernel(
        A: T.Tensor((M, N, K), dtype),
        B: T.Tensor((M, N, K), dtype),
    ):
        with T.Kernel(T.ceildiv(K, block_K), T.ceildiv(N, block_N), T.ceildiv(M, block_M), threads=threads) as (bz, by, bx):
            # Allocate shared memory for the input tile
            A_shared = T.alloc_shared((block_M, block_N, block_K), dtype)

            # Allocate fragment for accumulation
            B_local = T.alloc_fragment((block_M, block_N, block_K), "float32")

            # Initialize accumulator to zero
            T.clear(B_local)

            # Copy input data to shared memory
            T.copy(A[bx * block_M : bx * block_M + block_M, 
                     by * block_N : by * block_N + block_N, 
                     bz * block_K : bz * block_K + block_K], 
                   A_shared)

            # Perform reduction along the specified dimension
            if reduce_dim == 2:
                # Reduce along K dimension
                for k in T.Parallel(block_K):
                    for j in T.Parallel(block_N):
                        for i in T.Parallel(block_M):
                            B_local[i, j, 0] += A_shared[i, j, k]
                # Write result back to global memory
                T.copy(B_local[:, :, 0], 
                       B[bx * block_M : bx * block_M + block_M, 
                         by * block_N : by * block_N + block_N, 
                         0 : 1])
            elif reduce_dim == 1:
                # Reduce along N dimension
                for j in T.Parallel(block_N):
                    for k in T.Parallel(block_K):
                        for i in T.Parallel(block_M):
                            B_local[i, 0, k] += A_shared[i, j, k]
                # Write result back to global memory
                T.copy(B_local[:, 0, :], 
                       B[bx * block_M : bx * block_M + block_M, 
                         0 : 1, 
                         bz * block_K : bz * block_K + block_K])
            else:
                # Reduce along M dimension
                for i in T.Parallel(block_M):
                    for j in T.Parallel(block_N):
                        for k in T.Parallel(block_K):
                            B_local[0, j, k] += A_shared[i, j, k]
                # Write result back to global memory
                T.copy(B_local[0, :, :], 
                       B[0 : 1, 
                         by * block_N : by * block_N + block_N, 
                         bz * block_K : bz * block_K + block_K])

    return tilelang.compile(reduce_sum_kernel, out_idx=[1], target="cuda")


