    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._kernel_cache = {}

    def _get_kernel(self, M: int, N: int, K: int, reduce_dim: int, dtype: str):
        key = (M, N, K, reduce_dim, dtype)
        if key not in self._kernel_cache:
            self._kernel_cache[key] = build_reduce_sum_kernel(M, N, K, reduce_dim, dtype=dtype)
        return self._kernel_cache[key]

    def forward(self, x: torch.Tensor) -> torch.Tensor:
