        original_shape = x_c.shape

        # Handle 3D case directly
        if len(original_shape) == 3:
            M, N, K = original_shape
        else:
            # For higher dimensional tensors, flatten to 3D
            M = original_shape[0]
            N = original_shape[1]
            K = 1
            for i in range(2, len(original_shape)):
                K *= original_shape[i]

        # Determine the actual reduction dimension
        reduce_dim = self.dim
        if reduce_dim < 0:
            reduce_dim = len(original_shape) + reduce_dim

        # Map reduction dimension to our 3D kernel
        # In the kernel we always have M, N, K dimensions
        # So we need to adjust which dimension to reduce over
        if reduce_dim == 0:
            kernel_reduce_dim = 0  # Reduce along M
        elif reduce_dim == 1:
            kernel_reduce_dim = 1  # Reduce along N  
        else:
            kernel_reduce_dim = 2  # Reduce along K

        # Adjust shapes for kernel compatibility
        # We'll process the tensor in chunks to make sure we have proper dimensions
        if reduce_dim == 0:
            # Reduce along first dimension - output shape will be (1, N, K)
            M = 1
        elif reduce_dim == 1:
            # Reduce along second dimension - output shape will be (M, 1, K)
            N = 1
        else:
            # Reduce along last dimension - output shape will be (M, N, 1)
            K = 1

        kernel = self._get_kernel(M, N, K, kernel_reduce_dim, "float16")

        # Run kernel
        result = kernel(x_c)

        # Return with proper shape
        new_shape = list(original_shape)
        new_shape[reduce_dim] = 1
        return result.view(new_shape)

