def build_sum_reduction_kernel(M: int, N: int, block_M: int = 128, block_N: int = 256,
                               threads: int = 128):
    @T.prim_func
    def sum_reduction_kernel(
        A: T.Tensor((M, N), "float16"),
        B: T.Tensor((M, 1), "float16"),
    ):
        with T.Kernel(T.ceildiv(N, block_N), T.ceildiv(M, block_M), threads=threads) as (bx, by):
            # Allocate shared memory for reduction
            shared_data = T.alloc_shared((block_N,), "float16")
            # Allocate fragment for accumulation
            accum = T.alloc_fragment((1, 1), "float32")

            # Initialize accumulator
            T.clear(accum)

            # Loop over the reduction dimension with pipelining
            for i in T.Pipelined(T.ceildiv(N, block_N), num_stages=2):
                # Copy data to shared memory
                start_idx = bx * block_N
                T.copy(A[by * block_M, start_idx:start_idx + block_N], shared_data)

                # Reduce within block
                for j in T.Parallel(block_N):
                    if start_idx + j < N:
                        accum[0, 0] += shared_data[j]

            # Write result
            if T.get_thread_binding(0) == 0:
                B[by * block_M, 0] = accum[0, 0]

    return tilelang.compile(sum_reduction_kernel, out_idx=[1], target="cuda")


