        key = (M, N)
        if key not in self._kernel_cache:
            self._kernel_cache[key] = build_sum_reduction_kernel(M, N)
        return self._kernel_cache[key]

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Reshape input to match expected shape (M, N) where M is batch dims and N is reduction dim
        original_shape = x.shape
        x_reshaped = x.view(-1, x.size(-1))

        # Get kernel for this shape
        M, N = x_reshaped.shape
        kernel = self._get_kernel(M, N)

        # Run kernel
        result = kernel(x_reshaped)

        # Reshape result to match PyTorch behavior
        return result.view(original_shape[:-1] + (1,))

